import { MailIndex, buildThreads, parseQuery, stripHtml } from "./search.mjs";
import { initI18n, setLocale, t, applyStaticTranslations, populateLanguageSelect } from "./i18n.mjs";

"use strict";

/* ============================================================
   helpers
   ============================================================ */
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));
const esc = (value) => String(value == null ? "" : value).replace(/[&<>"']/g, (ch) => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
}[ch]));
const uid = (prefix) => `${prefix}_${(crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2)).replace(/-/g, "").slice(0, 18)}`;
const clone = (value) => structuredClone(value);
const escapeRegExp = (value) => String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const DELEGATED_SESSION_KEY = "a8m.delegated.window";
const DELEGATED_SESSION_HEADER = "X-A8M-Delegated-Session";

const avatarFailures = new Set();
const normalizedEmailDomain = (value) => normalizeEmail(value).split("@")[1] || "";
const senderAvatarSource = (person) => {
  const email = normalizeEmail(person?.email);
  const domain = normalizedEmailDomain(email);
  if (!email || !domain || !domain.includes(".") || avatarFailures.has(domain)) return "";
  const ownDomain = normalizedEmailDomain(state?.user?.email);
  if (ownDomain && domain === ownDomain) return "";
  return `/api/mail/avatar?address=${encodeURIComponent(email)}`;
};
const avatar = (person, size = "md") => {
  const p = person || { initials: "?", color: "#64748b" };
  const photo = senderAvatarSource(p);
  return `<span class="avatar avatar-${size}" style="--av:${esc(p.color || "#64748b")}" aria-hidden="true">${photo ? `<img class="avatar-photo" src="${esc(photo)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-avatar-domain="${esc(normalizedEmailDomain(p.email))}">` : ""}<span class="avatar-initials">${esc(p.initials || "?")}</span></span>`;
};
document.addEventListener("load", (event) => {
  const image = event.target;
  if (image instanceof HTMLImageElement && image.matches("img[data-avatar-domain]")) image.closest(".avatar")?.classList.add("has-photo");
}, true);
document.addEventListener("error", (event) => {
  const image = event.target;
  if (!(image instanceof HTMLImageElement) || !image.matches("img[data-avatar-domain]")) return;
  const domain = image.getAttribute("data-avatar-domain") || "";
  if (domain) avatarFailures.add(domain);
  const holder = image.closest(".avatar");
  image.remove();
  holder?.classList.remove("has-photo");
}, true);

const initialsFrom = (value) => {
  const parts = String(value || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  return String(value || "?").slice(0, 2).toUpperCase();
};

const displayNameFromEmail = (value) => {
  const local = String(value || "").split("@")[0].replace(/[._-]+/g, " ").trim();
  if (!local) return "Guest";
  return local.replace(/\b\w/g, (letter) => letter.toUpperCase());
};

const personLabel = (person) => person ? (person.name || person.email) : "Unknown sender";
const recipientLabel = (message) => {
  const list = Array.isArray(message.to) ? message.to : message.to ? [message.to] : [];
  if (!list.length) return "no recipient";
  if (list.length === 1) return list[0].name || list[0].email;
  return `${list[0].name || list[0].email} +${list.length - 1}`;
};

const normalizeEmail = (email) => String(email || "").trim().toLowerCase();

const SAFE_EMAIL_STYLE_PROPERTIES = new Set([
  "color", "background-color", "background", "font-family", "font-size", "font-weight", "font-style",
  "font-variant", "text-decoration", "text-align", "text-indent", "line-height", "letter-spacing", "vertical-align",
  "margin", "margin-top", "margin-right", "margin-bottom", "margin-left",
  "padding", "padding-top", "padding-right", "padding-bottom", "padding-left",
  "border", "border-top", "border-right", "border-bottom", "border-left",
  "border-color", "border-width", "border-style", "border-radius", "border-collapse", "border-spacing",
  "width", "max-width", "height", "max-height", "display", "white-space", "word-break",
  "overflow-wrap", "list-style-type", "text-transform", "table-layout", "opacity",
]);

function safeEmailStyle(value) {
  const declarations = [];
  for (const part of String(value || "").split(";")) {
    const index = part.indexOf(":");
    if (index < 0) continue;
    const property = part.slice(0, index).trim().toLowerCase();
    const declaration = part.slice(index + 1).trim();
    if (!SAFE_EMAIL_STYLE_PROPERTIES.has(property) || !declaration) continue;
    if (/url\s*\(|expression\s*\(|@import|[<>]/i.test(declaration)) continue;
    declarations.push(`${property}: ${declaration}`);
  }
  return declarations.join("; ");
}

function emailImageProxyURL(source) {
  return `/api/mail/image?url=${encodeURIComponent(source)}`;
}

function emailImageSource(source) {
  const value = String(source || "").trim();
  if (!value) return "";
  if (/^cid:/i.test(value)) return "";
  if (/^data:image\/(?:png|jpe?g|gif|webp|avif|bmp|x-icon)(?:;base64)?,/i.test(value)) return value;
  if (/^https?:\/\//i.test(value)) return emailImageProxyURL(value);
  if (/^\/\//.test(value)) return emailImageProxyURL(`https:${value}`);
  return "";
}

function cidImageMap(message) {
  const map = new Map();
  for (const attachment of (message?.attachments || [])) {
    if (!attachment.contentId || !String(attachment.mime || "").startsWith("image/")) continue;
    const key = String(attachment.contentId).replace(/^<|>$/g, "").toLowerCase();
    if (key && attachment.contentUrl) map.set(key, attachment.contentUrl);
  }
  return map;
}

const EMAIL_NAMED_COLORS = {
  black: [0, 0, 0], white: [255, 255, 255], gray: [128, 128, 128], grey: [128, 128, 128],
  silver: [192, 192, 192], red: [255, 0, 0], blue: [0, 0, 255], green: [0, 128, 0],
  navy: [0, 0, 128], maroon: [128, 0, 0], purple: [128, 0, 128], teal: [0, 128, 128],
  olive: [128, 128, 0], yellow: [255, 255, 0], lime: [0, 255, 0], aqua: [0, 255, 255],
  fuchsia: [255, 0, 255]
};

let emailColorProbe = null;
const emailColorCache = new Map();

function parseEmailColorFast(raw) {
  let match = raw.match(/^#([0-9a-f]{3,8})$/i);
  if (match) {
    let hex = match[1];
    if (hex.length === 3 || hex.length === 4) {
      hex = hex.split("").map((part) => part + part).join("");
    }
    if (hex.length === 6 || hex.length === 8) {
      if (hex.length === 8 && hex.slice(6) === "00") return null;
      return [parseInt(hex.slice(0, 2), 16), parseInt(hex.slice(2, 4), 16), parseInt(hex.slice(4, 6), 16)];
    }
    return null;
  }
  match = raw.match(/^rgba?\(\s*([\d.]+)\s*[,\s]\s*([\d.]+)\s*[,\s]\s*([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/i);
  if (match) {
    if (match[4] != null) {
      const alpha = match[4].endsWith("%") ? Number(match[4].slice(0, -1)) / 100 : Number(match[4]);
      if (alpha === 0) return null;
    }
    return [Number(match[1]), Number(match[2]), Number(match[3])];
  }
  return EMAIL_NAMED_COLORS[raw] || null;
}

function parseEmailColor(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (!raw || ["transparent", "inherit", "initial", "unset", "currentcolor", "none"].includes(raw)) return null;
  if (emailColorCache.has(raw)) return emailColorCache.get(raw);
  let result = parseEmailColorFast(raw);
  if (!result) {
    // Let the browser parse the full CSS Color grammar (hsl, hwb, lab, newer
    // named colours). The canvas normalises it to hex or rgba for us.
    try {
      emailColorProbe = emailColorProbe || document.createElement("canvas").getContext("2d");
      if (emailColorProbe) {
        emailColorProbe.fillStyle = "#010203";
        emailColorProbe.fillStyle = raw;
        const normalized = String(emailColorProbe.fillStyle || "").toLowerCase();
        if (normalized && normalized !== "#010203") result = parseEmailColorFast(normalized);
      }
    } catch {}
  }
  if (emailColorCache.size > 4096) emailColorCache.clear();
  emailColorCache.set(raw, result);
  return result;
}

function emailColorLuminance(rgb) {
  return (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
}

function emailElementBackground(node) {
  if (!node || node.nodeType !== 1) return null;
  return parseEmailColor(node.style?.backgroundColor || "")
    || parseEmailColor(node.getAttribute?.("bgcolor") || "");
}

function emailElementColor(node) {
  if (!node || node.nodeType !== 1) return null;
  return parseEmailColor(node.style?.color || "")
    || parseEmailColor(node.getAttribute?.("color") || "");
}

function emailNearestBackground(node) {
  for (let element = node; element && element.nodeType === 1; element = element.parentElement) {
    const color = emailElementBackground(element);
    if (color) return color;
  }
  return null;
}

// Email clients routinely keep dark inline text that disappears on a dark
// reading surface. Annotate the affected nodes so CSS can adapt them in dark
// mode while leaving light-background cards and explicit brand colours intact.
function annotateEmailContrast(node) {
  const ownBackground = emailElementBackground(node);
  if (ownBackground) {
    const luminance = emailColorLuminance(ownBackground);
    if (luminance > 0.6) node.dataset.emailLightSurface = "1";
    else if (luminance < 0.4) node.dataset.emailDarkSurface = "1";
  }
  const color = emailElementColor(node);
  if (!color) return;
  const nearest = emailNearestBackground(node);
  const luminance = emailColorLuminance(color);
  if (luminance < 0.5) {
    if (!nearest) {
      node.dataset.emailDarkPageText = "1";
    } else {
      const background = emailColorLuminance(nearest);
      if (background < 0.4) node.dataset.emailOnDark = "1";
    }
  } else if (luminance > 0.7) {
    if (!nearest) {
      node.dataset.emailLightPageText = "1";
    } else if (emailColorLuminance(nearest) > 0.6) {
      node.dataset.emailOnLight = "1";
    }
  }
}

function safeEmailHtml(html, { message = null, allowImages = true } = {}) {
  const template = document.createElement("template");
  template.innerHTML = String(html || "");
  template.content.querySelectorAll("script, style, iframe, object, embed, form, link, meta, base, svg, math").forEach((node) => node.remove());
  const cidImages = cidImageMap(message);
  template.content.querySelectorAll("*").forEach((node) => {
    for (const attribute of Array.from(node.attributes)) {
      const name = attribute.name.toLowerCase();
      if (name.startsWith("on") || name === "srcdoc" || name === "formaction" || name === "srcset") node.removeAttribute(attribute.name);
      if (name === "style") {
        const safe = safeEmailStyle(attribute.value);
        if (safe) node.setAttribute("style", safe);
        else node.removeAttribute(attribute.name);
      }
      if ((name === "href" || name === "src") && /^\s*javascript:/i.test(attribute.value)) node.removeAttribute(attribute.name);
    }
    if (node.tagName === "A") {
      node.setAttribute("target", "_blank");
      node.setAttribute("rel", "noopener noreferrer nofollow");
    }
    if (node.tagName === "IMG") {
      const source = node.getAttribute("src") || "";
      if (source) node.setAttribute("data-email-src", source);
      let cidKey = /^cid:/i.test(source) ? source.slice(4).replace(/^<|>$/g, "").toLowerCase() : "";
      if (cidKey.includes("%")) {
        try { cidKey = decodeURIComponent(cidKey); } catch {}
      }
      const cidURL = cidKey ? cidImages.get(cidKey) : "";
      // Preserve the designer's intended dimensions (logos are often width="200"
      // or width="240px"); removing them stretched images to intrinsic size.
      for (const dimension of ["width", "height"]) {
        const value = String(node.getAttribute(dimension) || "").trim();
        if (value && !/^\d{1,5}(?:%|px)?$/i.test(value)) node.removeAttribute(dimension);
      }
      // Outlook treats a numeric width attribute as the rendered width even
      // when the email also carries width:100% in its inline style. Apply the
      // same precedence so logos do not fill the whole compose column.
      const widthValue = String(node.getAttribute("width") || "").trim();
      if (/^\d{1,5}(?:px)?$/i.test(widthValue)) {
        node.style.width = `${parseInt(widthValue, 10)}px`;
      }
      node.setAttribute("decoding", "async");
      node.setAttribute("referrerpolicy", "no-referrer");
      node.setAttribute("class", "email-image");
      if (cidURL) {
        node.setAttribute("src", cidURL);
      } else if (allowImages) {
        const proxied = emailImageSource(source);
        if (proxied) node.setAttribute("src", proxied);
        else {
          node.setAttribute("data-blocked-src", source);
          node.setAttribute("src", "data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=");
          node.classList.add("is-blocked-image");
        }
      } else {
        node.setAttribute("data-blocked-src", source);
        node.setAttribute("src", "data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=");
        node.classList.add("is-blocked-image");
      }
    }
  });
  template.content.querySelectorAll("*").forEach(annotateEmailContrast);
  return template.innerHTML;
}

function emailHasImages(html) {
  const template = document.createElement("template");
  template.innerHTML = String(html || "");
  return Boolean(template.content.querySelector("img"));
}

function formatBytes(bytes) {
  const value = Number(bytes) || 0;
  if (value >= 1024 ** 3) {
    const gb = value / 1024 ** 3;
    const text = gb >= 10 ? gb.toFixed(1) : gb.toFixed(2);
    return `${text.replace(/\.0+$/, "").replace(/(\.\d)0$/, "$1")} GB`;
  }
  if (value >= 1024 ** 2) return `${(value / 1024 ** 2).toFixed(1).replace(/\.0$/, "")} MB`;
  if (value >= 1024) return `${Math.round(value / 1024)} KB`;
  return `${value} B`;
}

function currentLocale() {
  return (state.preferences && state.preferences.language) || DEFAULT_PREFERENCES.language;
}

function currentTimeZone() {
  return (state.preferences && state.preferences.timeZone) || DEFAULT_PREFERENCES.timeZone;
}

function timeZoneParts(value, timeZone = currentTimeZone()) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false
  });
  const parts = {};
  for (const part of formatter.formatToParts(date)) {
    if (part.type !== "literal") parts[part.type] = part.value;
  }
  let hour = Number(parts.hour);
  if (hour === 24) hour = 0;
  return { year: Number(parts.year), month: Number(parts.month), day: Number(parts.day), hour, minute: Number(parts.minute), second: Number(parts.second) };
}

function dateKeyInZone(value, timeZone = currentTimeZone()) {
  const parts = timeZoneParts(value, timeZone);
  return parts ? partsToKey(parts) : "";
}

function partsToKey(parts) {
  return `${parts.year}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`;
}

function keyToParts(key) {
  const match = String(key || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return match ? { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) } : null;
}

function addDaysToKey(key, days) {
  const parts = keyToParts(key);
  if (!parts) return key;
  const date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day + days, 12));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
}

function weekdayOfKey(key) {
  const parts = keyToParts(key);
  if (!parts) return 0;
  const day = new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12)).getUTCDay();
  return day === 0 ? 7 : day;
}

function timeZoneOffsetMs(date, timeZone = currentTimeZone()) {
  const parts = timeZoneParts(date, timeZone);
  if (!parts) return 0;
  const asUTC = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second);
  return asUTC - Math.floor(date.getTime() / 1000) * 1000;
}

function zonedWallTimeToUtc(dateKey, time, timeZone = currentTimeZone()) {
  const parts = keyToParts(dateKey);
  if (!parts) return null;
  const [hours, minutes] = String(time || "09:00").split(":").map(Number);
  const desired = Date.UTC(parts.year, parts.month - 1, parts.day, hours || 0, minutes || 0, 0);
  let stamp = desired;
  for (let index = 0; index < 3; index += 1) {
    const offset = timeZoneOffsetMs(new Date(stamp), timeZone);
    const next = desired - offset;
    if (Math.abs(next - stamp) < 1000) { stamp = next; break; }
    stamp = next;
  }
  return new Date(stamp);
}

function formatClock(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat(currentLocale(), {
    hour: "numeric",
    minute: "2-digit",
    hour12: state.preferences?.timeFormat !== "24h",
    timeZone: currentTimeZone()
  }).format(date);
}

function formatListWhen(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const key = dateKeyInZone(date);
  const today = dateKeyInZone(new Date());
  if (key === today) return formatClock(date);
  if (key === addDaysToKey(today, -1)) return "Yesterday";
  const todayParts = keyToParts(today);
  const dateParts = keyToParts(key);
  const dayDiff = Math.round((Date.UTC(todayParts.year, todayParts.month - 1, todayParts.day) - Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day)) / 86400000);
  if (dayDiff >= 0 && dayDiff < 7) return new Intl.DateTimeFormat(currentLocale(), { weekday: "short", timeZone: currentTimeZone() }).format(date);
  if (dateParts.year === todayParts.year) return new Intl.DateTimeFormat(currentLocale(), { month: "short", day: "numeric", timeZone: currentTimeZone() }).format(date);
  return new Intl.DateTimeFormat(currentLocale(), { month: "short", day: "numeric", year: "numeric", timeZone: currentTimeZone() }).format(date);
}

function formatDateOnly(value) {
  let key = "";
  let date = null;
  if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    key = value;
    const parts = keyToParts(key);
    date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day, 12));
  } else {
    date = new Date(value);
    if (Number.isNaN(date.getTime())) return "";
    key = dateKeyInZone(date);
  }
  const format = state.preferences?.dateFormat || "auto";
  if (format === "ymd") return key;
  if (format === "dmy") return new Intl.DateTimeFormat(currentLocale(), { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }).format(date);
  return new Intl.DateTimeFormat(currentLocale(), { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }).format(date);
}

function formatFullWhen(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const key = dateKeyInZone(date);
  const today = dateKeyInZone(new Date());
  if (key === today) return `Today at ${formatClock(date)}`;
  if (key === addDaysToKey(today, -1)) return `Yesterday at ${formatClock(date)}`;
  const dateText = new Intl.DateTimeFormat(currentLocale(), { month: "long", day: "numeric", timeZone: currentTimeZone() }).format(date);
  return `${dateText} at ${formatClock(date)}`;
}

function formatAuditWhen(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  const dateText = new Intl.DateTimeFormat(currentLocale(), { month: "short", day: "numeric", timeZone: currentTimeZone() }).format(date);
  return `${dateText}, ${formatClock(date)}`;
}

function formatDateTimeFull(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const dateText = new Intl.DateTimeFormat(currentLocale(), {
    weekday: "short", month: "long", day: "numeric", year: "numeric",
    timeZone: currentTimeZone()
  }).format(date);
  return `${dateText} · ${formatClock(date)} ${formatTimeZoneShort(currentTimeZone(), date)}`;
}

function formatTimeZoneShort(timeZone = currentTimeZone(), date = new Date()) {
  try {
    const part = new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: "short" }).formatToParts(date).find((item) => item.type === "timeZoneName");
    return part ? part.value : timeZone;
  } catch {
    return timeZone;
  }
}

function formatTimeZoneLabel(timeZone = currentTimeZone(), date = new Date()) {
  const offset = timeZoneOffsetMs(date, timeZone);
  const sign = offset >= 0 ? "+" : "-";
  const minutes = Math.abs(Math.round(offset / 60000));
  return `${timeZone.replace(/_/g, " ")} · UTC${sign}${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")} · ${formatTimeZoneShort(timeZone, date)}`;
}

function formatRelativeTime(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const diff = date.getTime() - Date.now();
  const abs = Math.abs(diff);
  let unit = "minute";
  let divisor = 60000;
  if (abs >= 86400000) { unit = "day"; divisor = 86400000; }
  else if (abs >= 3600000) { unit = "hour"; divisor = 3600000; }
  return new Intl.RelativeTimeFormat(currentLocale(), { numeric: "auto" }).format(Math.round(diff / divisor), unit);
}

function startOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function parseDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatCountdown(ms) {
  return `${Math.max(0, Math.ceil(ms / 1000))}s`;
}

function htmlToText(html) {
  const div = document.createElement("div");
  div.innerHTML = String(html || "");
  return (div.textContent || "").replace(/\s+/g, " ").trim();
}

function textToEditorHTML(text) {
  const value = String(text || "");
  return value.split(/\n{2,}/).map((paragraph) =>
    `<p>${esc(paragraph).replace(/\n/g, "<br>")}</p>`
  ).join("") || "";
}

function sanitizeEditorHTML(raw) {
  const template = document.createElement("template");
  template.innerHTML = String(raw || "");
  template.content.querySelectorAll("script, style, iframe, object, embed, form, input, textarea, button, meta, link, svg, math").forEach((node) => node.remove());
  template.content.querySelectorAll("*").forEach((node) => {
    for (const attr of Array.from(node.attributes || [])) {
      const name = attr.name.toLowerCase();
      if (name.startsWith("on") || name === "srcdoc" || name === "formaction") node.removeAttribute(attr.name);
      if ((name === "href" || name === "src") && /^\s*javascript:/i.test(attr.value)) node.removeAttribute(attr.name);
    }
  });
  return template.innerHTML;
}

function handleEditorHistoryShortcut(event) {
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return false;
  const key = String(event.key || "").toLowerCase();
  const redo = key === "y" || (key === "z" && event.shiftKey);
  const undo = key === "z" && !event.shiftKey;
  if (!undo && !redo) return false;
  const editor = event.target?.closest?.('[data-compose-editor], .compose-text, #signatureEditorBody, #signatureEditorPlain, #identityEditorSignature, #identityEditorSignaturePlain');
  if (!editor) return false;
  event.preventDefault();
  editor.focus();
  try { document.execCommand(redo ? "redo" : "undo", false); } catch {}
  editor.dispatchEvent(new Event("input", { bubbles: true }));
  return true;
}

const COMPOSE_ALIGNMENT_SHORTCUTS = {
  l: "justifyLeft",
  e: "justifyCenter",
  r: "justifyRight",
  j: "justifyFull"
};

function handleComposeAlignmentShortcut(event) {
  if (!(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey) return false;
  const command = COMPOSE_ALIGNMENT_SHORTCUTS[String(event.key || "").toLowerCase()];
  if (!command) return false;
  const editor = event.target?.closest?.("[data-compose-editor]");
  if (!editor) return false;
  const section = editor.closest(".compose[data-compose-id]");
  const session = sessionById(section?.getAttribute("data-compose-id"));
  if (!session) return false;
  event.preventDefault();
  applyComposeEditorCommand(session, command);
  return true;
}

function editorPlainText(html) {
  const div = document.createElement("div");
  div.innerHTML = String(html || "");
  return (div.innerText || div.textContent || "").replace(/ /g, " ").trim();
}

function originalImageSource(image) {
  return String(image?.getAttribute?.("data-email-src") || image?.getAttribute?.("src") || "").trim();
}

function normalizeEditorImageSources(root) {
  if (!root) return;
  root.querySelectorAll("img").forEach((image) => {
    const source = String(image.getAttribute("src") || "").trim();
    if (!source) return;
    const original = originalImageSource(image);
    if (/^data:image\/(?:png|jpe?g|gif|webp|avif|bmp|x-icon)(?:;base64)?,/i.test(original)) {
      if (!image.getAttribute("src")) image.setAttribute("src", original);
      image.removeAttribute("data-email-src");
      return;
    }
    if (/^\/api\/mail\/image\?/i.test(original)) {
      try {
        const proxied = new URL(original, window.location.origin);
        const target = proxied.searchParams.get("url") || "";
        if (/^https?:\/\//i.test(target)) image.setAttribute("data-email-src", target);
      } catch {}
      return;
    }
    if (/^https?:\/\//i.test(original) || /^\/\//.test(original)) {
      const remote = original.startsWith("//") ? `https:${original}` : original;
      image.setAttribute("data-email-src", remote);
      image.setAttribute("src", emailImageProxyURL(remote));
      image.removeAttribute("srcset");
      return;
    }
    if (/^cid:/i.test(original)) {
      image.setAttribute("data-email-cid", original);
      image.classList.add("is-unresolved-cid");
    }
  });
}

function stripEditorArtifacts(html) {
  return String(html || "").replace(/\u200b/g, "");
}

function restoreEditorImageSources(html) {
  return restoreComposeImageSources(stripEditorArtifacts(html));
}

function activeEditorRange(editor) {
  const selection = window.getSelection();
  if (!selection || !editor) return null;
  if (selection.rangeCount && editor.contains(selection.getRangeAt(0).commonAncestorContainer)) {
    return selection.getRangeAt(0).cloneRange();
  }
  const remembered = richEditorSelections.get(editor);
  return remembered && editor.contains(remembered.commonAncestorContainer) ? remembered.cloneRange() : null;
}

function rememberEditorRange(editor) {
  if (!editor) return null;
  const selection = window.getSelection();
  if (!selection || !selection.rangeCount) return null;
  const range = selection.getRangeAt(0);
  if (!editor.contains(range.commonAncestorContainer)) return null;
  const copy = range.cloneRange();
  richEditorSelections.set(editor, copy);
  return copy;
}

function restoreEditorRange(editor) {
  if (!editor) return null;
  const range = activeEditorRange(editor);
  editor.focus();
  if (!range) return null;
  const selection = window.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);
  return range;
}

function styleTypingSpanAtCaret(editor, range, styles) {
  let node = range.startContainer;
  if (node.nodeType !== Node.ELEMENT_NODE) node = node.parentElement;
  let span = node && node.closest ? node.closest("span[data-a8m-typing]") : null;
  if (!span || !editor.contains(span)) {
    span = document.createElement("span");
    span.setAttribute("data-a8m-typing", "1");
    span.appendChild(document.createTextNode("\u200b"));
    const target = range.cloneRange();
    target.collapse(false);
    target.insertNode(span);
  }
  for (const [property, value] of Object.entries(styles)) {
    if (value) span.style[property] = value;
  }
  const selection = window.getSelection();
  const caret = document.createRange();
  const text = span.firstChild || span.appendChild(document.createTextNode("\u200b"));
  caret.setStart(text, Math.min(1, text.nodeValue.length));
  caret.collapse(true);
  selection.removeAllRanges();
  selection.addRange(caret);
  richEditorSelections.set(editor, caret.cloneRange());
  return span;
}

function applyRichInlineStyle(editor, styles) {
  if (!editor) return;
  let range = restoreEditorRange(editor);
  if (!range) {
    editor.focus();
    range = document.createRange();
    range.selectNodeContents(editor);
    range.collapse(false);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }
  try {
    if (range.collapsed) {
      styleTypingSpanAtCaret(editor, range, styles);
      return;
    }
    try { document.execCommand("styleWithCSS", false, true); } catch {}
    if (styles.fontFamily) document.execCommand("fontName", false, styles.fontFamily);
    if (styles.color) document.execCommand("foreColor", false, styles.color);
    if (styles.backgroundColor) document.execCommand("hiliteColor", false, styles.backgroundColor);
    // Font sizes use the legacy marker (7) and are normalised below, which is
    // reliable across Chrome, Edge and Safari even with a partial selection.
    if (styles.fontSize) {
      try { document.execCommand("styleWithCSS", false, false); } catch {}
      document.execCommand("fontSize", false, "7");
      for (const node of Array.from(editor.querySelectorAll('font[size="7"], [style*="font-size"]'))) {
        if (node.tagName === "FONT") {
          const span = document.createElement("span");
          span.style.fontSize = styles.fontSize;
          while (node.firstChild) span.appendChild(node.firstChild);
          node.replaceWith(span);
        } else if (node.style && ["xxx-large", "48px"].includes(String(node.style.fontSize || "").toLowerCase())) {
          node.style.fontSize = styles.fontSize;
        }
      }
      try { document.execCommand("styleWithCSS", false, true); } catch {}
    }
    rememberEditorRange(editor);
  } catch {}
}

function applyRichFontFamily(editor, family) {
  if (!family) return;
  applyRichInlineStyle(editor, { fontFamily: family });
  normalizeEditorFontTags(editor);
}

function applyRichFontSize(editor, pixels) {
  if (!pixels) return;
  applyRichInlineStyle(editor, { fontSize: `${pixels}px` });
}

function insertEditorHTML(editor, html) {
  if (!editor) return;
  const clean = sanitizeEditorHTML(html);
  const range = restoreEditorRange(editor);
  if (!range) {
    editor.innerHTML = clean;
  } else {
    range.deleteContents();
    const fragment = range.createContextualFragment(clean);
    range.insertNode(fragment);
    range.collapse(false);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }
  normalizeEditorImageSources(editor);
  rememberEditorRange(editor);
}

function editorClipboardHTML(event) {
  const data = event.clipboardData;
  if (!data) return "";
  const html = data.getData("text/html");
  if (html) return html;
  const text = data.getData("text/plain");
  return text ? textToEditorHTML(text) : "";
}

function insertClipboardImages(event, editor) {
  const files = Array.from(event.clipboardData?.files || []).filter((file) => String(file.type || "").startsWith("image/"));
  if (!files.length) return false;
  event.preventDefault();
  files.forEach((file) => {
    const reader = new FileReader();
    reader.onload = () => {
      const alt = String(file.name || "pasted image").replace(/"/g, "");
      insertEditorHTML(editor, `<img src="${reader.result}" alt="${esc(alt)}">`);
    };
    reader.readAsDataURL(file);
  });
  return true;
}

function handleRichEditorPaste(event, editor) {
  if (!editor || !event.clipboardData) return false;
  if (insertClipboardImages(event, editor)) return true;
  const html = event.clipboardData.getData("text/html");
  if (!html) return false;
  event.preventDefault();
  insertEditorHTML(editor, html);
  return true;
}

