async function loadAddons({ silent = false } = {}) {
  if (state.delegatedMode || state.addonsLoading) return;
  state.addonsLoading = true;
  if (!silent && !state.addonsLoaded) renderAddonsSettings();
  try {
    const data = await api("/api/addons");
    state.addons = Array.isArray(data.addons) ? data.addons : [];
    state.addonsAdmin = Boolean(data.isAdmin);
    state.addonsRequests = Array.isArray(data.requests) ? data.requests : [];
    state.addonsLoaded = true;
  } catch (error) {
    if (!silent) showError(error);
  } finally {
    state.addonsLoading = false;
    renderAddonNavBadge();
    renderAddonsSettings();
    renderReaderAddons();
  }
}

function renderAddonNavBadge() {
  const badge = document.getElementById("addonNavBadge");
  if (!badge) return;
  const count = (state.addonsRequests || []).length;
  badge.hidden = count === 0;
  badge.textContent = String(count);
}

function renderAddonsSettings() {
  ensureAddonsSettingsUi();
  const grid = document.getElementById("addonsGrid");
  if (!grid) return;
  const search = document.getElementById("addonsSearch");
  if (search && search.value !== state.addonsQuery) search.value = state.addonsQuery;
  ensureAddonOverlays();
  document.querySelectorAll("[data-addons-filter]").forEach((button) => {
    const active = button.getAttribute("data-addons-filter") === state.addonsFilter;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  renderAddonNavBadge();
  renderAddonRequests();
  renderAddonsGrid();
  const summary = document.getElementById("addonsSummary");
  if (summary) {
    const installed = (state.addons || []).filter((addon) => addon.installed).length;
    const available = (state.addons || []).filter((addon) => ["ready", "needs_connection"].includes(addon.status)).length;
    summary.textContent = state.addonsLoading && !state.addonsLoaded
      ? "Loading add-ons…"
      : `${(state.addons || []).length} add-ons · ${available} ready · ${installed} installed`;
  }
}

function addonMatchesFilter(addon) {
  const query = state.addonsQuery.trim().toLowerCase();
  if (query) {
    const haystack = `${addon.name || ""} ${addon.vendor || ""} ${addon.category || ""} ${addon.description || ""}`.toLowerCase();
    if (!haystack.includes(query)) return false;
  }
  switch (state.addonsFilter) {
    case "installed": return addon.installed;
    case "available": return ["ready", "needs_connection"].includes(addon.status);
    case "setup": return ["needs_setup", "requested", "blocked"].includes(addon.status);
    default: return true;
  }
}

function addonStatusMeta(addon) {
  switch (addon.status) {
    case "installed": return { label: "Installed", tone: "installed" };
    case "ready": return { label: "Ready to install", tone: "ready" };
    case "needs_connection": return { label: "Connect your account", tone: "attention" };
    case "needs_setup": return { label: addon.canManage ? "Workspace setup needed" : "Awaiting workspace setup", tone: "attention" };
    case "approval_required": return { label: "Admin approval required", tone: "attention" };
    case "requested": return { label: addon.requestType === "install" ? "Install approval pending" : "Request sent", tone: "neutral" };
    default: return { label: addon.tenantPolicySet ? "Disabled for workspace" : "Unavailable", tone: "neutral" };
  }
}

function addonLogoMarkup(addon, className = "addon-logo") {
  if (addon?.logo) {
    return `<img class="${esc(className)}" src="${esc(addon.logo)}" alt="${esc(addon.name || "Add-on")} logo" decoding="async">`;
  }
  return `<svg class="icon" aria-hidden="true"><use href="#${esc(addon?.icon || "i-grid")}"/></svg>`;
}

function addonAuthLabel(addon) {
  if (addon?.id === "slack") return "OAuth 2.0 or webhook";
  if (addon?.id === "salesforce" || addon?.id === "zoho") return "OAuth 2.0 (refresh token)";
  if (addon?.id === "ticktick") return "OAuth access token";
  if (addon?.id === "zoom") return "OAuth 2.0 (server-to-server)";
  if (addon?.authType === "email") return "Email address";
  if (addon?.authType === "webhook") return "Webhook";
  if (addon?.authType === "oauth2") return "OAuth 2.0";
  return "API key";
}

function addonProviderLinksMarkup(addon) {
  const links = [
    ["Website", addon.websiteUrl],
    ["Support", addon.supportUrl],
    ["Docs", addon.docsUrl],
    ["Privacy", addon.privacyUrl]
  ].filter(([, url]) => url);
  if (!links.length) return "";
  return `<div class="addon-provider-links">${links.map(([label, url]) =>
    `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}<svg class="icon" aria-hidden="true"><use href="#i-external"/></svg></a>`
  ).join("")}</div>`;
}

function addonPrimaryMarkup(addon) {
  if (addon.installed) return `<button class="addon-btn is-installed" type="button" disabled>Installed</button>`;
  if (addon.status === "ready") return `<button class="addon-btn" type="button" data-addon-primary="${esc(addon.id)}">Install</button>`;
  if (addon.status === "needs_connection") return `<button class="addon-btn" type="button" data-addon-primary="${esc(addon.id)}">Connect</button>`;
  if (addon.status === "approval_required") return `<button class="addon-btn" type="button" data-addon-request="${esc(addon.id)}">Request install</button>`;
  if (addon.status === "requested") return `<button class="addon-btn is-installed" type="button" disabled>${addon.requestType === "install" ? "Approval pending" : "Request sent"}</button>`;
  if (addon.status === "needs_setup") {
    return addon.canManage
      ? `<button class="addon-btn" type="button" data-addon-primary="${esc(addon.id)}">Set up</button>`
      : `<button class="addon-btn" type="button" data-addon-request="${esc(addon.id)}">Request setup</button>`;
  }
  if (addon.canRequest) return `<button class="addon-btn" type="button" data-addon-request="${esc(addon.id)}">Request access</button>`;
  return `<button class="addon-btn is-installed" type="button" disabled>Unavailable</button>`;
}

function addonCardMarkup(addon) {
  const status = addonStatusMeta(addon);
  const scopeLabel = addon.connectionScope === "tenant" ? "Workspace connection" : "Personal connection";
  const permissions = Array.isArray(addon.permissions) ? addon.permissions.length : 0;
  const secondary = `<span class="addon-card-links">${addon.installed ? `<button class="link-btn" type="button" data-addon-remove="${esc(addon.id)}">Remove</button>` : ""}${addon.canManage && addon.configured && addon.status !== "blocked" ? `<button class="link-btn" type="button" data-addon-setup="${esc(addon.id)}">${addon.installed ? "Reconnect" : "Update setup"}</button>` : ""}</span>`;
  const toggle = addon.canManage && (addon.tenantPolicySet || addon.connectionScope === "user")
    ? `<label class="addon-workspace-toggle" title="Enable or disable this add-on for the workspace"><input type="checkbox" data-addon-tenant-toggle="${esc(addon.id)}" ${addon.tenantEnabled ? "checked" : ""}><span>Workspace</span></label>`
    : "";
  const policy = addon.canManage
    ? `<select class="addon-policy-select" data-addon-install-policy="${esc(addon.id)}" title="Who can install this add-on" aria-label="Install policy for ${esc(addon.name)}"><option value="self_service"${addon.installPolicy !== "approval_required" ? " selected" : ""}>Self-service</option><option value="approval_required"${addon.installPolicy === "approval_required" ? " selected" : ""}>Approval required</option></select>`
    : "";
  return `<article class="addon-card" data-addon-card="${esc(addon.id)}">
    <div class="addon-card-art" style="--addon-color:${esc(addon.color || "#34557a")}">
      <span class="addon-logo-tile">${addonLogoMarkup(addon)}</span>
      <span class="addon-verified" title="First-party reviewed"><svg class="icon" aria-hidden="true"><use href="#i-check-circle"/></svg></span>
    </div>
    <div class="addon-card-copy">
      <div class="addon-card-heading"><div><h3>${esc(addon.name)}</h3><span class="addon-vendor">${esc(addon.vendor || "Alt8Mail")}</span></div><span class="addon-category">${esc(addon.category || "Add-on")}</span></div>
      <p>${esc(addon.description || "")}</p>
      <div class="addon-card-meta"><span>${esc(scopeLabel)}</span>${addon.configured && addon.connectionLabel ? `<span>${esc(addon.connectionLabel)}</span>` : ""}<span>${permissions} permission${permissions === 1 ? "" : "s"}</span>${addon.supportUrl ? `<a class="addon-support-link" href="${esc(addon.supportUrl)}" target="_blank" rel="noopener noreferrer" title="Open ${esc(addon.name)} support" aria-label="Open ${esc(addon.name)} support"><svg class="icon" aria-hidden="true"><use href="#i-external"/></svg></a>` : ""}<button class="link-btn addon-details-link" type="button" data-addon-details="${esc(addon.id)}">Details</button></div>
    </div>
    <div class="addon-card-foot">
      <span class="addon-status is-${esc(status.tone)}"><span class="addon-status-dot"></span>${esc(status.label)}</span>
      <div class="addon-card-actions">${policy}${toggle}${secondary}${addonPrimaryMarkup(addon)}</div>
    </div>
  </article>`;
}

function renderAddonsGrid() {
  const grid = document.getElementById("addonsGrid");
  const empty = document.getElementById("addonsEmpty");
  if (!grid || !empty) return;
  const addons = (state.addons || []).filter(addonMatchesFilter);
  grid.innerHTML = addons.map(addonCardMarkup).join("");
  const loading = state.addonsLoading && !state.addonsLoaded;
  empty.hidden = Boolean(addons.length) || loading;
  if (!addons.length && !loading) {
    empty.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-grid"/></svg><strong>No add-ons match this view</strong><span>Try another search or filter.</span>`;
  }
}

function renderAddonRequests() {
  const host = document.getElementById("addonsAdminRequests");
  if (!host) return;
  const requests = state.addonsRequests || [];
  if (!state.addonsAdmin || !requests.length) {
    host.innerHTML = "";
    return;
  }
  host.innerHTML = `<section class="addon-request-panel">
    <div class="addon-request-head"><div><p class="eyebrow">Admin queue</p><h3>Add-on requests</h3><p>${requests.length} teammate${requests.length === 1 ? "" : "s"} waiting for setup.</p></div><span class="addon-request-count">${requests.length}</span></div>
    <div class="addon-request-list">${requests.map((request) => `<div class="addon-request-row"><span class="avatar avatar-sm" style="--av:#34557a"><span class="avatar-initials">${esc(initialsFrom(request.userName || request.userEmail || "?"))}</span></span><div><strong>${request.addonLogo ? `<img class="addon-request-logo" src="${esc(request.addonLogo)}" alt="" loading="lazy" decoding="async">` : ""}${esc(request.addonName)} <span class="addon-request-type">${request.requestType === "install" ? "Install approval" : "Setup request"}</span></strong><span>${esc(request.userName || request.userEmail)}${request.note ? ` · ${esc(request.note)}` : ""}</span></div><div class="addon-request-actions"><button class="btn-secondary small" type="button" data-addon-request-resolve="${esc(request.id)}" data-addon-request-status="approved">Approve</button><button class="link-btn" type="button" data-addon-request-resolve="${esc(request.id)}" data-addon-request-status="denied">Deny</button></div></div>`).join("")}</div>
  </section>`;
}

function addonByID(id) {
  return (state.addons || []).find((addon) => addon.id === id) || null;
}

function handleAddonPrimary(id) {
  const addon = addonByID(id);
  if (!addon) return;
  if (addon.installed) return;
  if (addon.status === "ready") {
    installAddon(id);
    return;
  }
  if (addon.status === "needs_connection" || addon.status === "needs_setup") {
    if (addon.status === "needs_connection" || addon.canManage) openAddonSetup(id);
    else requestAddonSetup(id);
    return;
  }
  if (addon.status === "approval_required" || (addon.status === "blocked" && addon.canRequest)) requestAddonSetup(id);
}

async function installAddon(id) {
  try {
    await api(`/api/addons/${encodeURIComponent(id)}/install`, { method: "POST", body: {} });
    showToast("Add-on installed");
    await loadAddons({ silent: true });
  } catch (error) { showError(error); }
}

async function removeAddon(id) {
  const addon = addonByID(id);
  if (!addon) return;
  const confirmed = await appConfirm({
    title: `Remove ${addon.name}?`,
    message: addon.connectionScope === "user"
      ? "This removes the add-on from your reader and revokes the personal connection. You can connect it again later."
      : "This removes the add-on from your reader. The workspace connection stays available to other users.",
    confirmLabel: "Remove add-on",
    tone: "danger",
    icon: "i-grid"
  });
  if (!confirmed) return;
  try {
    await api(`/api/addons/${encodeURIComponent(id)}/install`, { method: "DELETE" });
    showToast(`${addon.name} removed`);
    await loadAddons({ silent: true });
  } catch (error) { showError(error); }
}

async function requestAddonSetup(id) {
  const addon = addonByID(id);
  if (!addon) return;
  try {
    await api(`/api/addons/${encodeURIComponent(id)}/request`, { method: "POST", body: { note: "" } });
    showToast(addon.status === "approval_required" ? `Install request sent for ${addon.name}` : `Request sent — an administrator will review ${addon.name}`);
    await loadAddons({ silent: true });
  } catch (error) { showError(error); }
}

async function resolveAddonRequest(id, status) {
  try {
    await api(`/api/addon-requests/${encodeURIComponent(id)}/resolve`, { method: "POST", body: { status } });
    showToast(status === "approved" ? "Request approved" : "Request denied");
    await loadAddons({ silent: true });
  } catch (error) { showError(error); }
}

async function setAddonWorkspaceEnabled(id, enabled, toggle) {
  const addon = addonByID(id);
  if (!addon) return false;
  if (!enabled) {
    const confirmed = await appConfirm({
      title: `Disable ${addon.name} for the workspace?`,
      message: "Users will no longer be able to install or run this add-on. Existing personal connections stay encrypted until they are removed.",
      confirmLabel: "Disable add-on",
      tone: "danger",
      icon: "i-grid"
    });
    if (!confirmed) {
      if (toggle) toggle.checked = true;
      return false;
    }
  }
  try {
    await api(`/api/addons/${encodeURIComponent(id)}/tenant`, { method: "PUT", body: { enabled } });
    showToast(enabled ? `${addon.name} enabled for the workspace` : `${addon.name} disabled for the workspace`);
    await loadAddons({ silent: true });
    return true;
  } catch (error) {
    if (toggle) toggle.checked = !enabled;
    showError(error);
    return false;
  }
}

async function setAddonInstallPolicy(id, policy, select) {
  const addon = addonByID(id);
  if (!addon) return false;
  const previous = addon.installPolicy || "self_service";
  if (policy === previous) return true;
  try {
    await api(`/api/addons/${encodeURIComponent(id)}/tenant`, { method: "PUT", body: { installPolicy: policy } });
    showToast(`${addon.name} install policy updated`);
    await loadAddons({ silent: true });
    return true;
  } catch (error) {
    if (select) select.value = previous;
    showError(error);
    return false;
  }
}

function addonOAuthMarkup(addon) {
  if (!addon.oauthAvailable || !addon.oauthMode || addon.oauthMode === "disabled") return "";
  const managed = addon.oauthMode === "managed";
  const appFields = `
    <div class="addon-oauth-app-fields">
      <label class="form-field addon-field"><span>Slack app client ID</span><input data-addon-oauth-field="clientId" type="text" autocomplete="off" spellcheck="false" placeholder="1234567890.1234567890"></label>
      <label class="form-field addon-field"><span>Client secret</span><input data-addon-oauth-field="clientSecret" type="password" autocomplete="off" placeholder="Leave blank to reuse the saved app"></label>
      <label class="form-field addon-field"><span>Signing secret</span><input data-addon-oauth-field="signingSecret" type="password" autocomplete="off" placeholder="Leave blank to keep the saved signing secret"><small>Find these on your Slack app's Basic Information page. Alt8Mail encrypts them before storing. A signing secret enables provider webhooks for this workspace.</small></label>
    </div>`;
  const byoOption = managed
    ? `<details class="addon-oauth-byo"><summary>Use your own Slack app instead</summary>${appFields}<button class="btn-secondary small addon-oauth-btn" type="button" data-addon-oauth-start="byo"><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg>Connect with your own app</button></details>`
    : appFields;
  return `<div class="addon-oauth-panel">
    <div class="addon-oauth-head">
      <span class="addon-oauth-mark"><svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg></span>
      <div><strong>Connect with Slack OAuth</strong><small>${managed ? "Alt8Mail's managed relay handles the Slack app. You only approve the workspace and channel." : "Use your own Slack app. The app secret is encrypted and the authorization code is exchanged by this server."}</small></div>
    </div>
    ${byoOption}
    <button class="btn-primary addon-oauth-btn" type="button" data-addon-oauth-start="${managed ? "managed" : "byo"}"><svg class="icon" aria-hidden="true"><use href="#i-link"/></svg>Connect with Slack</button>
  </div>
  <div class="addon-field-divider"><span>Or connect with an incoming webhook</span></div>`;
}

function openAddonSetup(id) {
  const addon = addonByID(id);
  if (!addon) return;
  ensureAddonOverlays();
  state.addonModalId = id;
  const overlay = document.getElementById("addonSetupOverlay");
  document.getElementById("addonSetupTitle").textContent = addon.installed ? `Reconnect ${addon.name}` : `Set up ${addon.name}`;
  document.getElementById("addonSetupEyebrow").textContent = addon.connectionScope === "tenant" ? "Workspace add-on" : "Personal add-on";
  document.getElementById("addonSetupSubtitle").textContent = addon.description || "";
  const icon = document.getElementById("addonSetupIcon");
  if (icon) {
    icon.style.setProperty("--addon-color", addon.color || "#34557a");
    icon.innerHTML = addonLogoMarkup(addon, "addon-setup-logo");
  }
  const error = document.getElementById("addonSetupError");
  if (error) { error.hidden = true; error.textContent = ""; }
  const links = document.getElementById("addonSetupLinks");
  if (links) links.innerHTML = addonProviderLinksMarkup(addon);
  const fields = document.getElementById("addonSetupFields");
  fields.innerHTML = addonOAuthMarkup(addon) + (addon.fields || []).map((field) => {
    const value = field.default || addon.connectionConfig?.[field.key] || "";
    if (field.type === "select") {
      return `<label class="form-field addon-field"><span>${esc(field.label)}${field.required ? " *" : ""}</span><select data-addon-field="${esc(field.key)}">${(field.options || []).map((option) => `<option value="${esc(option.value)}" ${String(value) === String(option.value) ? "selected" : ""}>${esc(option.label)}</option>`).join("")}</select>${field.help ? `<small>${esc(field.help)}</small>` : ""}</label>`;
    }
    return `<label class="form-field addon-field"><span>${esc(field.label)}${field.required ? " *" : ""}</span><input data-addon-field="${esc(field.key)}" type="${esc(field.type === "password" ? "password" : field.type === "url" ? "url" : "text")}" value="${field.secret ? "" : esc(value)}" placeholder="${esc(field.placeholder || "")}" autocomplete="off" spellcheck="false">${field.help ? `<small>${esc(field.help)}</small>` : ""}</label>`;
  }).join("");
  const permissions = document.getElementById("addonSetupPermissions");
  if (permissions) permissions.innerHTML = (addon.permissions || []).map((permission) => `<li>${esc(permission)}</li>`).join("");
  const save = document.getElementById("addonSetupSave");
  if (save) {
    save.textContent = addon.connectionScope === "user" ? "Save & install" : "Save workspace setup";
    save.disabled = false;
  }
  const disable = document.getElementById("addonSetupDisable");
  if (disable) {
    disable.hidden = !(addon.canManage && addon.tenantPolicySet && addon.tenantEnabled);
    disable.textContent = `Disable ${addon.name} for workspace`;
  }
  overlay.hidden = false;
  setTimeout(() => (fields.querySelector(".addon-oauth-btn") || fields.querySelector("input, select"))?.focus(), 40);
}

async function startAddonOAuth(mode = "", trigger = null) {
  const addon = addonByID(state.addonModalId);
  if (!addon) return;
  const button = trigger || document.querySelector("#addonSetupFields [data-addon-oauth-start]");
  const errorBox = document.getElementById("addonSetupError");
  if (errorBox) { errorBox.hidden = true; errorBox.textContent = ""; }
  const payload = {};
  if (mode) payload.mode = mode;
  if (mode === "byo" || addon.oauthMode === "byo") {
    for (const key of ["clientId", "clientSecret", "signingSecret"]) {
      const input = document.querySelector(`#addonSetupFields [data-addon-oauth-field="${key}"]`);
      payload[key] = input ? String(input.value || "").trim() : "";
    }
  }
  const label = button?.innerHTML;
  if (button) { button.disabled = true; button.textContent = "Opening Slack…"; }
  try {
    const data = await api(`/api/addons/${encodeURIComponent(addon.id)}/oauth/start`, { method: "POST", body: payload });
    if (!data?.oauthUrl) throw new Error("Slack authorization could not be started");
    window.location.href = data.oauthUrl;
  } catch (error) {
    if (errorBox) { errorBox.textContent = error.message || "Could not start Slack authorization."; errorBox.hidden = false; }
    if (button) { button.disabled = false; button.innerHTML = label || "Connect with Slack"; }
  }
}

function closeAddonSetup() {
  const overlay = document.getElementById("addonSetupOverlay");
  if (overlay) overlay.hidden = true;
  state.addonModalId = "";
  state.addonSaving = false;
}

async function submitAddonSetup() {
  if (state.addonSaving) return;
  const addon = addonByID(state.addonModalId);
  if (!addon) return;
  const fields = {};
  const errorBox = document.getElementById("addonSetupError");
  for (const field of addon.fields || []) {
    const input = document.querySelector(`#addonSetupFields [data-addon-field="${CSS.escape(field.key)}"]`);
    const value = input ? String(input.value || "").trim() : "";
    if (field.required && !value) {
      if (errorBox) { errorBox.textContent = `Enter ${field.label}.`; errorBox.hidden = false; }
      input?.focus();
      return;
    }
    fields[field.key] = value;
  }
  const save = document.getElementById("addonSetupSave");
  state.addonSaving = true;
  if (save) { save.disabled = true; save.textContent = "Saving…"; }
  try {
    await api(`/api/addons/${encodeURIComponent(addon.id)}/connect`, { method: "POST", body: fields });
    if (addon.connectionScope === "user" && !addon.installed) {
      await api(`/api/addons/${encodeURIComponent(addon.id)}/install`, { method: "POST", body: {} });
    }
    closeAddonSetup();
    showToast(addon.connectionScope === "tenant" ? `${addon.name} is ready. Users can install it from Add-ons.` : `${addon.name} connected and installed`);
    await loadAddons({ silent: true });
  } catch (error) {
    if (errorBox) { errorBox.textContent = error.message || "Could not save this add-on."; errorBox.hidden = false; }
    if (save) { save.disabled = false; save.textContent = addon.connectionScope === "user" ? "Save & install" : "Save workspace setup"; }
  } finally {
    state.addonSaving = false;
  }
}

async function disableAddonFromSetup() {
  const addon = addonByID(state.addonModalId);
  if (!addon) return;
  if (await setAddonWorkspaceEnabled(addon.id, false)) closeAddonSetup();
}

function ensureReaderAddonsButton() {
  if (document.getElementById("readerAddonsWrap")) return;
  const toolbar = document.getElementById("readerToolbar");
  if (!toolbar) return;
  const wrap = document.createElement("div");
  wrap.className = "reader-addons-wrap";
  wrap.id = "readerAddonsWrap";
  wrap.hidden = true;
  wrap.innerHTML = `<button class="tool-btn reader-addons-btn" id="readerAddonsBtn" type="button" aria-label="Add-on actions" title="Add-on actions" aria-haspopup="menu" aria-expanded="false"><svg class="icon" aria-hidden="true"><use href="#i-grid"/></svg><span class="tool-label">Add-ons</span><svg class="icon addon-menu-chevron" aria-hidden="true"><use href="#i-chevron-down"/></svg></button><div class="reader-addons-menu" id="readerAddonsMenu" role="menu" hidden></div>`;
  const spacer = toolbar.querySelector(".tool-spacer");
  toolbar.insertBefore(wrap, spacer || null);
  document.getElementById("readerAddonsBtn")?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleReaderAddonMenu();
  });
  document.getElementById("readerAddonsMenu")?.addEventListener("click", (event) => {
    const action = event.target.closest("[data-addon-reader-action]");
    if (!action) return;
    runReaderAddonAction(action.getAttribute("data-addon-id"), action.getAttribute("data-addon-reader-action"));
  });
  document.addEventListener("click", (event) => {
    if (!event.target.closest("#readerAddonsWrap")) closeReaderAddonMenu();
  });
}

function readerAddonActions() {
  return (state.addons || []).flatMap((addon) =>
    addon.installed && Array.isArray(addon.availableActions)
      ? addon.availableActions.filter((action) => action.surface === "reader").map((action) => ({ addon, action }))
      : []
  );
}

function renderReaderAddons() {
  ensureReaderAddonsButton();
  const wrap = document.getElementById("readerAddonsWrap");
  const menu = document.getElementById("readerAddonsMenu");
  if (!wrap || !menu) return;
  const thread = currentThread();
  const actions = readerAddonActions();
  const visible = Boolean(thread && actions.length && !state.delegatedMode);
  wrap.hidden = !visible;
  if (!visible) {
    closeReaderAddonMenu();
    return;
  }
  menu.innerHTML = `<div class="reader-addons-head"><span>Add-on actions</span><span>${actions.length}</span></div>${actions.map(({ addon, action }) => `<button type="button" role="menuitem" class="reader-addon-item" data-addon-reader-action="${esc(action.id)}" data-addon-id="${esc(addon.id)}"><span class="reader-addon-icon" style="--addon-color:${esc(addon.color || "#34557a")}">${addonLogoMarkup(addon, "reader-addon-logo")}</span><span><strong>${esc(action.label)}</strong><small>${esc(addon.name)} · ${esc((addon.permissions || [])[0] || "First-party add-on")}</small></span><svg class="icon reader-addon-chevron" aria-hidden="true"><use href="#i-chevron-right"/></svg></button>`).join("")}`;
}

function toggleReaderAddonMenu(force) {
  const menu = document.getElementById("readerAddonsMenu");
  const button = document.getElementById("readerAddonsBtn");
  if (!menu) return;
  const open = typeof force === "boolean" ? force : menu.hidden;
  menu.hidden = !open;
  state.addonReaderMenuOpen = open;
  button?.setAttribute("aria-expanded", open ? "true" : "false");
  document.getElementById("readerAddonsWrap")?.classList.toggle("is-open", open);
}

function closeReaderAddonMenu() {
  toggleReaderAddonMenu(false);
}

async function runReaderAddonAction(addonId, actionId) {
  const addon = addonByID(addonId);
  const thread = currentThread();
  const message = thread?.latest;
  if (!addon || !message?.id) return;
  closeReaderAddonMenu();
  try {
    const data = await api(`/api/addons/${encodeURIComponent(addonId)}/actions/${encodeURIComponent(actionId)}`, {
      method: "POST",
      body: { messageId: message.id }
    });
    if (data?.result?.translation?.text) {
      showAddonResult(`${addon.name} translation`, data.result.translation.text, `${data.result.translation.sourceLanguage || "Source"} → ${data.result.translation.targetLanguage || "target"}`);
    } else if (data?.result?.meetingUrl) {
      showAddonResult(`${addon.name} meeting created`, data.result.meetingUrl, `${data.result.startTime || "Starts in 5 minutes"} · ${data.result.duration || 30} minutes`);
    } else if (data?.result?.taskUrl) {
      showAddonResult(`${addon.name} task created`, data.result.taskUrl, "Open or copy the task link below.");
    } else if (data?.result?.contactName) {
      showToast(`Email logged to ${addon.name} for ${data.result.contactName}`);
    } else if (data?.result?.dedupKey) {
      showToast(`${addon.name} incident triggered`);
    } else if (data?.result?.taskId) {
      showToast(`Task created in ${addon.name}`);
    } else if (data?.result?.posted) {
      showToast(`Sent to ${addon.name}`);
    } else if (data?.result?.saved) {
      showToast(`Saved to ${addon.name}`);
    } else if (data?.result?.queued) {
      showToast(`Added to ${addon.name}`);
    } else {
      showToast(`${addon.name} action completed`);
    }
  } catch (error) { showError(error); }
}

function showAddonResult(title, text, meta = "") {
  ensureAddonOverlays();
  document.getElementById("addonResultTitle").textContent = title;
  document.getElementById("addonResultMeta").textContent = meta;
  document.getElementById("addonResultText").textContent = String(text || "");
  document.getElementById("addonResultOverlay").hidden = false;
}

function closeAddonResult() {
  const overlay = document.getElementById("addonResultOverlay");
  if (overlay) overlay.hidden = true;
}

function openAddonDetails(id) {
  const addon = addonByID(id);
  if (!addon) return;
  ensureAddonOverlays();
  const status = addonStatusMeta(addon);
  const icon = document.getElementById("addonDetailsIcon");
  if (icon) {
    icon.style.setProperty("--addon-color", addon.color || "#34557a");
    icon.innerHTML = addonLogoMarkup(addon, "addon-setup-logo");
  }
  document.getElementById("addonDetailsTitle").textContent = addon.name;
  document.getElementById("addonDetailsSubtitle").textContent = `${addon.vendor || "Alt8Mail"} · ${addon.category || "Add-on"}`;
  const actions = Array.isArray(addon.actions) ? addon.actions : [];
  const permissions = Array.isArray(addon.permissions) ? addon.permissions : [];
  document.getElementById("addonDetailsBody").innerHTML = `
    <p class="addon-details-tagline">${esc(addon.tagline || addon.description || "")}</p>
    ${addonProviderLinksMarkup(addon)}
    <dl class="addon-details-grid">
      <div><dt>Vendor</dt><dd>${esc(addon.vendor || "Alt8Mail")}</dd></div>
      <div><dt>Category</dt><dd>${esc(addon.category || "Add-on")}</dd></div>
      <div><dt>Connection</dt><dd>${esc(addon.connectionScope === "tenant" ? "Workspace" : "Personal")}</dd></div>
      <div><dt>Authentication</dt><dd>${esc(addonAuthLabel(addon))}</dd></div>
      <div><dt>Connector version</dt><dd>${esc(addon.connectorVersion || "1.0")}</dd></div>
      <div><dt>Status</dt><dd>${esc(status.label)}</dd></div>
    </dl>
    ${actions.length ? `<section class="addon-details-section"><h3>Reader actions</h3><ul>${actions.map((action) => `<li><strong>${esc(action.label)}</strong>${action.description ? `<span>${esc(action.description)}</span>` : ""}</li>`).join("")}</ul></section>` : ""}
    ${permissions.length ? `<section class="addon-details-section"><h3>Permissions requested</h3><ul>${permissions.map((permission) => `<li>${esc(permission)}</li>`).join("")}</ul></section>` : ""}
    <p class="addon-details-note">${esc(addon.name)} and its logo are trademarks of ${esc(addon.vendor || "the provider")}. Alt8Mail uses them only to identify this integration.</p>`;
  document.getElementById("addonDetailsOverlay").hidden = false;
}

function closeAddonDetails() {
  const overlay = document.getElementById("addonDetailsOverlay");
  if (overlay) overlay.hidden = true;
}

function maybeShowPasswordChange() {
  const overlay = document.getElementById("passwordChangeOverlay");
  if (!overlay) return;
  if (state.user && state.user.onboardingRequired) {
    overlay.hidden = true;
    return;
  }
  const required = Boolean(state.user && state.user.passwordChangeRequired);
  if (!required) {
    overlay.hidden = true;
    return;
  }
  overlay.hidden = false;
  const reason = document.getElementById("passwordChangeReason");
  const expiresAt = state.user.passwordExpiresAt ? new Date(state.user.passwordExpiresAt) : null;
  if (reason) {
    reason.textContent = expiresAt && expiresAt.getTime() < Date.now()
      ? "Your password has expired. Set a new password to restore access to your mailbox."
      : "Your organization requires a new password before you can continue. Use the password rules configured by your administrator.";
  }
  setTimeout(() => document.getElementById("passwordCurrent")?.focus(), 80);
}

async function submitPasswordChange() {
  const current = document.getElementById("passwordCurrent");
  const next = document.getElementById("passwordNew");
  const confirm = document.getElementById("passwordConfirm");
  const error = document.getElementById("passwordChangeError");
  const button = document.getElementById("passwordChangeSubmit");
  error.hidden = true;
  if (!current.value) { error.textContent = "Enter your current password."; error.hidden = false; return; }
  if (next.value.length < 8) { error.textContent = "Choose a stronger new password."; error.hidden = false; return; }
  if (next.value !== confirm.value) { error.textContent = "The new passwords do not match."; error.hidden = false; return; }
  button.disabled = true;
  button.textContent = "Saving…";
  try {
    await api("/api/password/change", { method: "POST", body: { currentPassword: current.value, newPassword: next.value } });
    current.value = ""; next.value = ""; confirm.value = "";
    state.user.passwordChangeRequired = false;
    document.getElementById("passwordChangeOverlay").hidden = true;
    await loadBootstrap({ restoreDrafts: false, quiet: true });
    showToast("Password updated");
  } catch (changeError) {
    error.textContent = changeError.message || "Could not change the password.";
    error.hidden = false;
  } finally {
    button.disabled = false;
    button.textContent = "Save new password";
  }
}

/* ============================================================
   Mandatory first-login onboarding
   ============================================================ */
function onboardingDisplayNameFallback() {
  const email = state.user?.email || "";
  const local = email.split("@")[0] || "there";
  return local.split(/[._-]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(" ") || "there";
}

function onboardingName() {
  return String(document.getElementById("onboardingName")?.value || "").trim();
}

function onboardingSelection() {
  const selected = state.onboarding || {};
  return {
    timeFormat: selected.timeFormat || state.preferences.timeFormat || "12h",
    theme: selected.theme || state.preferences.theme || "system",
    accent: selected.accent || state.preferences.accent || "blue"
  };
}

function maybeShowOnboarding() {
  if (!onboardingOverlay) return false;
  const required = Boolean(state.user && state.user.onboardingRequired);
  if (!required) {
    onboardingOverlay.hidden = true;
    document.body.classList.remove("onboarding-active");
    if (app) app.inert = false;
    return false;
  }
  if (!onboardingOverlay.hidden) return true;
  state.onboarding = {
    step: 0,
    saving: false,
    passwordChanged: false,
    timeFormat: state.preferences.timeFormat || "12h",
    theme: state.preferences.theme || "system",
    accent: state.preferences.accent || "blue"
  };
  const name = state.user.name && !/^primary$/i.test(state.user.name) && state.user.name !== state.user.email
    ? state.user.name
    : onboardingDisplayNameFallback();
  document.getElementById("onboardingName").value = name;
  document.getElementById("onboardingEmail").value = state.user.email || "";
  const zoneSelect = document.getElementById("onboardingTimeZone");
  zoneSelect.innerHTML = timeZoneOptions().map((zone) => `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`).join("");
  zoneSelect.value = state.preferences.timeZone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  const language = document.getElementById("onboardingLanguage");
  populateLanguageSelect(language);
  language.value = state.preferences.language || "en-US";
  const passwordRequired = Boolean(state.user.passwordChangeRequired);
  document.getElementById("onboardingPasswordSection").hidden = !passwordRequired;
  document.getElementById("onboardingPasswordClear").hidden = passwordRequired;
  document.getElementById("onboardingPasswordError").hidden = true;
  document.getElementById("onboardingTwoFactorBtn").disabled = false;
  document.getElementById("onboardingTwoFactorBtn").textContent = "Remind me to set this up";
  updateOnboardingAvatar();
  updateOnboardingControls();
  setOnboardingStep(0);
  onboardingOverlay.hidden = false;
  document.body.classList.add("onboarding-active");
  if (app) app.inert = true;
  setTimeout(() => document.getElementById("onboardingName")?.focus(), 120);
  return true;
}

function updateOnboardingAvatar() {
  const name = onboardingName() || onboardingDisplayNameFallback();
  document.getElementById("onboardingAvatar").textContent = initialsFrom(name);
  const finishName = document.getElementById("onboardingFinishName");
  if (finishName) finishName.textContent = name.split(/\s+/)[0] || "there";
}

function updateOnboardingControls() {
  const selection = onboardingSelection();
  $$("[data-onboarding-time-format]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-time-format") === selection.timeFormat;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  $$("[data-onboarding-theme]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-theme") === selection.theme;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  $$("[data-onboarding-accent]").forEach((button) => {
    const active = button.getAttribute("data-onboarding-accent") === selection.accent;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function setOnboardingStep(step) {
  const next = Math.max(0, Math.min(3, Number(step) || 0));
  state.onboarding.step = next;
  $$(".onboarding-step", onboardingOverlay).forEach((panel) => { panel.hidden = Number(panel.getAttribute("data-onboarding-step")) !== next; });
  $$("[data-onboarding-step-dot]", onboardingOverlay).forEach((dot) => {
    const index = Number(dot.getAttribute("data-onboarding-step-dot"));
    dot.classList.toggle("is-active", index === next);
    dot.classList.toggle("is-complete", index < next);
  });
  const labels = ["Tell us who you are", "Set your workspace defaults", "Secure the account", "Review and finish"];
  document.getElementById("onboardingProgressLabel").textContent = `Step ${next + 1} of 4`;
  document.getElementById("onboardingProgressSub").textContent = labels[next];
  document.getElementById("onboardingProgressBar").style.width = `${((next + 1) / 4) * 100}%`;
  const back = document.getElementById("onboardingBack");
  back.disabled = next === 0 || state.onboarding.saving;
  const nextButton = document.getElementById("onboardingNext");
  nextButton.textContent = next === 3 ? "Finish setup" : "Continue";
  nextButton.disabled = false;
  const error = document.getElementById("onboardingError");
  error.hidden = true;
  if (next === 3) updateOnboardingSummary();
  const focusTarget = next === 0 ? document.getElementById("onboardingName") : next === 1 ? document.getElementById("onboardingTimeZone") : next === 2 ? document.getElementById("onboardingCurrentPassword") : document.getElementById("onboardingNext");
  setTimeout(() => focusTarget?.focus(), 60);
}

function updateOnboardingSummary() {
  const name = onboardingName();
  const selection = onboardingSelection();
  const zone = document.getElementById("onboardingTimeZone").value || state.preferences.timeZone || "UTC";
  const languageSelect = document.getElementById("onboardingLanguage");
  const language = languageSelect.options[languageSelect.selectedIndex]?.textContent || selection.language || "English";
  document.getElementById("onboardingSummaryName").textContent = name || "—";
  document.getElementById("onboardingSummaryIdentity").textContent = name ? `${name} <${state.user.email}>` : state.user.email;
  document.getElementById("onboardingSummaryZone").textContent = zone.replace(/_/g, " ");
  document.getElementById("onboardingSummaryTime").textContent = selection.timeFormat === "24h" ? "24-hour" : "12-hour";
  document.getElementById("onboardingSummaryLanguage").textContent = language;
  const themeLabel = { light: "Light", dark: "Dark", system: "System" }[selection.theme] || selection.theme;
  const accentLabel = selection.accent.charAt(0).toUpperCase() + selection.accent.slice(1);
  document.getElementById("onboardingSummaryAppearance").textContent = `${themeLabel} · ${accentLabel} accent`;
  updateOnboardingAvatar();
}

function onboardingError(message) {
  const error = document.getElementById("onboardingError");
  if (!error) return;
  error.textContent = message;
  error.hidden = !message;
}

async function submitOnboardingPassword() {
  const current = document.getElementById("onboardingCurrentPassword");
  const next = document.getElementById("onboardingNewPassword");
  const confirm = document.getElementById("onboardingConfirmPassword");
  const error = document.getElementById("onboardingPasswordError");
  error.hidden = true;
  if (!state.user.passwordChangeRequired || state.onboarding.passwordChanged) return true;
  if (state.onboarding.saving) return false;
  if (!current.value) { error.textContent = "Enter your current password."; error.hidden = false; current.focus(); return false; }
  if (next.value.length < 8) { error.textContent = "Choose a new password of at least 8 characters."; error.hidden = false; next.focus(); return false; }
  if (next.value !== confirm.value) { error.textContent = "The new passwords do not match."; error.hidden = false; confirm.focus(); return false; }
  state.onboarding.saving = true;
  const button = document.getElementById("onboardingNext");
  button.disabled = true;
  button.textContent = "Updating password…";
  try {
    await api("/api/password/change", { method: "POST", body: { currentPassword: current.value, newPassword: next.value } });
    state.user.passwordChangeRequired = false;
    state.onboarding.passwordChanged = true;
    current.value = ""; next.value = ""; confirm.value = "";
    document.getElementById("onboardingPasswordSection").hidden = true;
    const clear = document.getElementById("onboardingPasswordClear");
    clear.hidden = false;
    clear.innerHTML = `<div class="onboarding-section-label"><span>Password</span><span class="onboarding-chip verified">Updated</span></div><p>Your new password is active. Keep it in a password manager and continue.</p>`;
    return true;
  } catch (changeError) {
    error.textContent = changeError.message || "Could not change the password.";
    error.hidden = false;
    return false;
  } finally {
    state.onboarding.saving = false;
    button.disabled = false;
    button.textContent = "Continue";
  }
}

async function advanceOnboarding() {
  if (state.onboarding.saving) return;
  const step = state.onboarding.step;
  if (step === 0) {
    if (!onboardingName()) { onboardingError("Enter your full name so the From line is correct."); document.getElementById("onboardingName").focus(); return; }
    setOnboardingStep(1);
    return;
  }
  if (step === 1) {
    if (!document.getElementById("onboardingTimeZone").value) { onboardingError("Choose your time zone."); return; }
    if (!document.getElementById("onboardingLanguage").value) { onboardingError("Choose your preferred language."); return; }
    setOnboardingStep(2);
    return;
  }
  if (step === 2) {
    if (!(await submitOnboardingPassword())) return;
    setOnboardingStep(3);
    return;
  }
  await finishOnboarding();
}

async function finishOnboarding() {
  if (!onboardingName()) { setOnboardingStep(0); onboardingError("Enter your full name so the From line is correct."); return; }
  const selection = onboardingSelection();
  const zone = document.getElementById("onboardingTimeZone").value;
  const language = document.getElementById("onboardingLanguage").value;
  const button = document.getElementById("onboardingNext");
  state.onboarding.saving = true;
  button.disabled = true;
  button.textContent = "Saving your workspace…";
  onboardingError("");
  try {
    const data = await api("/api/onboarding/complete", {
      method: "POST",
      body: {
        displayName: onboardingName(),
        timeZone: zone,
        timeFormat: selection.timeFormat,
        language,
        theme: selection.theme,
        accent: selection.accent
      }
    });
    if (data.user) {
      state.user.onboardingRequired = false;
      state.user.name = data.user.name || state.user.name;
      state.user.initials = data.user.initials || state.user.initials;
      state.user.passwordChangeRequired = false;
    }
    if (data.preferences) state.preferences = { ...state.preferences, ...data.preferences };
    onboardingOverlay.hidden = true;
    document.body.classList.remove("onboarding-active");
    if (app) app.inert = false;
    applyServerPreferences();
    applyPreferenceChrome();
    syncPreferencesUi();
    renderAccountChrome();
    await loadBootstrap({ restoreDrafts: false, quiet: true });
    showToast("Workspace ready — your sender name is set");
  } catch (error) {
    if (error.code === "PASSWORD_CHANGE_REQUIRED") {
      state.user.passwordChangeRequired = true;
      document.getElementById("onboardingPasswordSection").hidden = false;
      setOnboardingStep(2);
      onboardingError("Set a new password before finishing setup.");
    } else {
      onboardingError(error.message || "Could not finish setup. Try again.");
    }
  } finally {
    state.onboarding.saving = false;
    button.disabled = false;
    button.textContent = state.onboarding.step === 3 ? "Finish setup" : "Continue";
  }
}

onboardingOverlay?.addEventListener("input", (event) => {
  if (event.target.id === "onboardingName") {
    updateOnboardingAvatar();
    updateOnboardingSummary();
  }
});
onboardingOverlay?.addEventListener("click", (event) => {
  const timeFormat = event.target.closest("[data-onboarding-time-format]");
  if (timeFormat) {
    state.onboarding.timeFormat = timeFormat.getAttribute("data-onboarding-time-format");
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  const theme = event.target.closest("[data-onboarding-theme]");
  if (theme) {
    state.onboarding.theme = theme.getAttribute("data-onboarding-theme");
    setTheme(state.onboarding.theme, false);
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  const accent = event.target.closest("[data-onboarding-accent]");
  if (accent) {
    state.onboarding.accent = accent.getAttribute("data-onboarding-accent");
    setAccent(state.onboarding.accent, false);
    updateOnboardingControls();
    updateOnboardingSummary();
    return;
  }
  if (event.target.closest("#onboardingBack")) { setOnboardingStep(state.onboarding.step - 1); return; }
  if (event.target.closest("#onboardingNext")) { advanceOnboarding(); return; }
  if (event.target.closest("#onboardingTwoFactorBtn")) {
    const twoFactor = event.target.closest("#onboardingTwoFactorBtn");
    twoFactor.disabled = true;
    twoFactor.textContent = "Reminder noted — enable it in Settings → Security & privacy";
    return;
  }
});

function handleSessionExpired() {
  closeOfficeUiOnSignOut();
  if (state.delegatedMode) {
    expireDelegatedWindow("Your primary Alt8Mail session ended. This delegated mailbox has been signed out.");
    return;
  }
  if (loginScreen.hidden) {
    showLogin();
    loginError.textContent = "Your session expired. Sign in again to continue.";
    loginError.hidden = false;
  }
}

let TITLE_LOGIN = "Alt8Mail: Secure Email with AI built in - Sign-in";
let TITLE_GENERIC = "Alt8Mail: Secure, AI-Powered Email that thinks with you !";
let tenantBranding = null;
const TITLE_ACCOUNT = "Smarter conversations, AI-powered Email";

function documentTitleSubject(thread) {
  const text = String(threadSubject(thread) || "(no subject)").replace(/\s+/g, " ").trim();
  if (text.length <= 80) return text;
  return `${text.slice(0, 79).replace(/[\s·—-]+$/, "")}…`;
}

function brandName() {
  return (tenantBranding && tenantBranding.productName ? String(tenantBranding.productName).trim() : "") || "Alt8Mail";
}

function updateDocumentTitle() {
  const brand = brandName();
  let title = TITLE_GENERIC;
  if (!state.user) {
    title = loginScreen && !loginScreen.hidden ? TITLE_LOGIN : TITLE_GENERIC;
  } else if (state.task !== "mail") {
    title = `${brand}: ${state.user.email || `${brand} account`} - ${TITLE_ACCOUNT}`;
  } else if (!state.selectedThreadId && state.homeTab === "pulse") {
    title = `Pulse — ${brand}`;
  } else if (!state.selectedThreadId && state.homeTab === "search" && state.homeSearchQuery) {
    title = `Search report: ${state.homeSearchQuery.slice(0, 48)} — ${brand}`;
  } else {
    const folderLabel = (folderDef(state.folder).label || "Inbox").trim();
    const thread = state.selectedThreadId ? (viewThreadById(state.selectedThreadId) || currentThread()) : null;
    const imapOffline = state.mailboxMode === "imap" && Boolean(String(state.mailSyncError || "").trim());
    const offline = Boolean(state.offline) || imapOffline;
    if (offline) {
      title = thread
        ? `Offline · ${folderLabel} · ${documentTitleSubject(thread)} — ${brand}`
        : `Offline · ${folderLabel} — ${brand}`;
    } else {
      const unread = Math.max(0, Math.floor(Number(unreadCount(state.folder)) || 0));
      const prefix = unread > 0 ? `(${unread}) ` : "";
      title = thread
        ? `${prefix}${folderLabel} · ${documentTitleSubject(thread)} — ${brand}`
        : `${prefix}${folderLabel} — ${state.user.email || `${brand} account`} - ${brand}`;
    }
  }
  if (state.delegatedMode && state.user) title = `Delegated · ${title}`;
  if (document.title !== title) document.title = title;
}

function brandInitials(name) {
  const words = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (words.length > 1) return words.slice(0, 2).map((word) => word[0]).join("").toUpperCase();
  return String(name || "A8").slice(0, 2).toUpperCase() || "A8";
}

function applyTenantBranding(branding) {
  if (!branding || typeof branding !== "object") return;
  const name = String(branding.productName || "").trim().slice(0, 60) || "Alt8Mail";
  const supportEmail = String(branding.supportEmail || "").trim().slice(0, 200);
  const loginMessage = String(branding.loginMessage || "").trim().slice(0, 240);
  const color = /^#[0-9a-f]{6}$/i.test(String(branding.primaryColor || "")) ? branding.primaryColor : "";
  tenantBranding = { ...branding, productName: name };
  if (color) {
    document.documentElement.style.setProperty("--accent", color);
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", color);
  }
  const initials = brandInitials(name);
  document.querySelectorAll(".brand-name, .login-brand-top strong, .login-heading > .eyebrow").forEach((node) => { node.textContent = name; });
  document.querySelectorAll(".brand-mark, .login-mark, .login-watermark").forEach((node) => { node.textContent = initials; });
  document.querySelectorAll(".login-demo, .login-legal").forEach((node) => {
    if (node.textContent.includes("Alt8Mail")) node.textContent = node.textContent.replaceAll("Alt8Mail", name);
  });
  const splash = document.getElementById("bootSplash");
  if (splash) {
    splash.setAttribute("aria-label", `Opening ${name}`);
    const eyebrow = splash.querySelector(".eyebrow");
    if (eyebrow) eyebrow.textContent = name;
  }
  TITLE_GENERIC = name === "Alt8Mail" ? "Alt8Mail: Secure, AI-Powered Email that thinks with you !" : `${name}: Secure, AI-powered email`;
  TITLE_LOGIN = name === "Alt8Mail" ? "Alt8Mail: Secure Email with AI built in - Sign-in" : `${name}: Sign in`;
  let message = document.getElementById("tenantLoginMessage");
  if (loginMessage) {
    if (!message) {
      message = document.createElement("p");
      message.id = "tenantLoginMessage";
      message.className = "login-demo tenant-login-message";
      document.querySelector(".login-heading")?.appendChild(message);
    }
    message.textContent = loginMessage;
  } else if (message) {
    message.remove();
  }
  const foot = document.querySelector(".login-card-foot");
  let support = document.getElementById("tenantSupportLink");
  const safeSupport = supportEmail.replace(/[^a-zA-Z0-9@._+-]/g, "");
  if (foot && safeSupport.includes("@")) {
    if (!support) {
      support = document.createElement("a");
      support.id = "tenantSupportLink";
      support.style.marginLeft = "8px";
      support.style.color = "var(--accent-ink)";
      foot.appendChild(support);
    }
    support.href = `mailto:${safeSupport}`;
    support.textContent = safeSupport;
  } else if (support) {
    support.remove();
  }
  const legal = document.querySelector('.login-card-foot [data-i18n="login.legal"]');
  if (legal) {
    legal.removeAttribute("data-i18n");
    legal.textContent = `Protected by ${name} · TLS 1.3`;
  }
  updateDocumentTitle();
}

async function loadTenantBranding() {
  try {
    const response = await fetch("/api/branding", {
      method: "GET", credentials: "same-origin", cache: "no-store",
      headers: { Accept: "application/json" },
    });
    if (!response.ok) return;
    applyTenantBranding(await response.json());
  } catch (_) {
    // Branding is progressive enhancement; the default identity remains.
  }
}

function setOffline(offline) {
  const next = !!offline;
  if (state.offline === next) return;
  state.offline = next;
  updateDocumentTitle();
  if (offlineBanner) offlineBanner.hidden = !next;
  const dot = document.getElementById("connDot");
  const text = document.getElementById("connText");
  if (dot) dot.classList.toggle("is-offline", next);
  if (text) text.textContent = next ? "Offline" : "Connected";
  if (statusMid && next) statusMid.textContent = "Offline — showing cached shell";
  if (!next) {
    syncStatusContext();
    if (state.user) refreshMailbox({ quiet: true }).catch(() => {});
  }
}

/* ============================================================
   theme + preferences
   ============================================================ */
function effectiveTheme() {
  const explicit = document.documentElement.getAttribute("data-theme");
  if (explicit) return explicit;
  return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

function setTheme(mode, save = true) {
  if (!["light", "dark", "system"].includes(mode)) mode = "system";
  state.theme = mode;
  if (mode === "system") document.documentElement.removeAttribute("data-theme");
  else document.documentElement.setAttribute("data-theme", mode);
  if (save) {
    prefs.set("theme", mode);
    if (state.user && state.csrf) patchPreferences({ theme: mode }, null);
  }
  syncThemeUI();
}

function applyReaderLightMode() {
  const button = document.getElementById("readerLightBtn");
  const dark = effectiveTheme() === "dark";
  const active = dark && Boolean(state.readerLightMode);
  reader?.classList.toggle("is-light-message", active);
  if (button) {
    button.hidden = !dark;
    button.setAttribute("aria-pressed", active ? "true" : "false");
    button.classList.toggle("is-active", active);
    button.title = active ? "Return the message to the dark reading background" : "Read message on a light background";
  }
}

function syncThemeUI() {
  const mode = effectiveTheme();
  applyReaderLightMode();
  const themeBtn = document.getElementById("themeBtn");
  if (themeBtn) {
    const label = mode === "dark" ? "Switch to light theme" : "Switch to dark theme";
    themeBtn.setAttribute("aria-label", label);
    themeBtn.title = label;
  }
  $$("[data-set-theme]").forEach((button) => {
    const active = button.getAttribute("data-set-theme") === state.theme;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.content = mode === "dark" ? "#0b1a2b" : "#093256";
  syncOfficeEditorTheme();
}

function setAccent(key, save = true) {
  if (!ACCENTS[key]) key = "blue";
  state.accent = key;
  document.documentElement.style.setProperty("--accent", ACCENTS[key].value);
  if (save) {
    prefs.set("accent", key);
    if (state.user && state.csrf) patchPreferences({ accent: key }, null);
  }
  $$("[data-set-accent]").forEach((button) => {
    const active = button.getAttribute("data-set-accent") === key;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
}

function setDensity(mode, save = true) {
  if (mode !== "compact") mode = "comfortable";
  state.density = mode;
  app.setAttribute("data-density", mode);
  if (save) {
    prefs.set("density", mode);
    if (state.user && state.csrf) patchPreferences({ density: mode }, null);
  }
  $$("[data-set-density]").forEach((button) => {
    const active = button.getAttribute("data-set-density") === mode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  const hint = document.getElementById("densityHint");
  if (hint) hint.textContent = mode === "compact"
    ? "Two-line rows without the preview line — more conversations per screen."
    : "Three-line rows with a subject and preview line.";
}

function setPreference(key, value, save = true) {
  state[key] = !!value;
  $$(`[data-pref="${key}"]`).forEach((control) => {
    control.setAttribute("aria-checked", state[key] ? "true" : "false");
  });
  if (save) {
    prefs.set(key, state[key] ? "1" : "0");
    if (key === "notifyDesktop") {
      if (value) {
        if ("Notification" in window && Notification.permission === "default") {
          Notification.requestPermission().then((permission) => {
            if (permission === "granted" && state.notifyDesktop) registerPushSubscription({ quiet: true }).catch(() => {});
          }).catch(() => {});
        } else if ("Notification" in window && Notification.permission === "granted") {
          registerPushSubscription({ quiet: true }).catch(() => {});
        }
      } else {
        unregisterPushSubscription({ silent: true }).catch(() => {});
      }
    }
    if (state.user && state.csrf) patchPreferences({ [key]: state[key] }, "Preference saved");
  }
  if (key === "externalWarnings") {
    renderReader();
  }
}

function loadPreferences() {
  const read = (key, fallback) => {
    const value = prefs.get(key);
    return value === null ? fallback : value !== "0";
  };
  setPreference("markReadOnOpen", read("markReadOnOpen", true), false);
  setPreference("defaultReceipt", read("defaultReceipt", false), false);
  setPreference("notifyDesktop", read("notifyDesktop", true), false);
  setPreference("notifySound", read("notifySound", false), false);
  setPreference("notifyCalendar", read("notifyCalendar", true), false);
  setPreference("externalWarnings", read("externalWarnings", true), false);
  state.defaultPriority = ["low", "normal", "high"].includes(prefs.get("defaultPriority")) ? prefs.get("defaultPriority") : "normal";
  state.undoSendSeconds = Number(prefs.get("undoSendSeconds")) >= 5 && Number(prefs.get("undoSendSeconds")) <= 10 ? Number(prefs.get("undoSendSeconds")) : 8;
  const prioritySelect = document.getElementById("defaultPrioritySelect");
  if (prioritySelect) prioritySelect.value = state.defaultPriority;
  const undoSelect = document.getElementById("undoSendSelect");
  if (undoSelect) undoSelect.value = String(state.undoSendSeconds);
}

function applySavedPreferences() {
  // Pre-sign-in cache only: avoids a theme flash on the login card. Once a
  // session exists, applyServerPreferences() replaces every value from DB.
  const savedTheme = prefs.get("theme");
  if (savedTheme === "light" || savedTheme === "dark") setTheme(savedTheme, false);
  else { state.theme = "system"; syncThemeUI(); }
  setAccent(ACCENTS[prefs.get("accent")] ? prefs.get("accent") : "blue", false);
  setDensity(prefs.get("density") === "compact" ? "compact" : "comfortable", false);
  loadPreferences();
}

function applyServerPreferences() {
  const p = state.preferences || {};
  setTheme(p.theme || "system", false);
  setAccent(p.accent || "blue", false);
  setDensity(p.density || "comfortable", false);
  if (p.language) {
    prefs.set("language", p.language);
    setLocale(p.language).catch(() => {});
  }
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    setPreference(key, p[key] !== false, false);
  }
  state.defaultPriority = ["low", "normal", "high"].includes(p.defaultPriority) ? p.defaultPriority : "normal";
  state.undoSendSeconds = Number(p.undoSendSeconds) >= 5 && Number(p.undoSendSeconds) <= 10 ? Number(p.undoSendSeconds) : 8;
  const prioritySelect = document.getElementById("defaultPrioritySelect");
  if (prioritySelect) prioritySelect.value = state.defaultPriority;
  const undoSelect = document.getElementById("undoSendSelect");
  if (undoSelect) undoSelect.value = String(state.undoSendSeconds);
  // Keep the offline/login cache aligned with the authoritative DB row.
  prefs.set("theme", state.theme);
  prefs.set("accent", state.accent);
  prefs.set("density", state.density);
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    prefs.set(key, state[key] ? "1" : "0");
  }
  prefs.set("defaultPriority", state.defaultPriority);
  prefs.set("undoSendSeconds", String(state.undoSendSeconds));
}

/* ============================================================
   server-backed workspace preferences
   ============================================================ */
function timeZoneOptions() {
  let zones = [];
  try {
    zones = Intl.supportedValuesOf ? Intl.supportedValuesOf("timeZone") : [];
  } catch {}
  if (!zones.length) {
    zones = ["UTC", "America/Los_Angeles", "America/New_York", "America/Chicago", "America/Denver", "Europe/London", "Europe/Berlin", "Europe/Paris", "Asia/Dubai", "Asia/Kolkata", "Asia/Singapore", "Asia/Tokyo", "Australia/Sydney"];
  }
  const current = currentTimeZone();
  if (current && !zones.includes(current)) zones = [current, ...zones];
  return zones;
}

function syncPreferencesUi() {
  if (!state.preferences) return;
  const preferences = state.preferences;
  setTheme(preferences.theme || "system", false);
  setAccent(preferences.accent || "blue", false);
  setDensity(preferences.density || "comfortable", false);
  for (const key of ["markReadOnOpen", "defaultReceipt", "notifyDesktop", "notifySound", "notifyCalendar", "externalWarnings"]) {
    state[key] = preferences[key] !== false;
    $$(`[data-pref="${key}"]`).forEach((control) => control.setAttribute("aria-checked", state[key] ? "true" : "false"));
  }
  const externalToggle = document.getElementById("externalWarningToggle");
  if (externalToggle) externalToggle.setAttribute("aria-checked", state.externalWarnings ? "true" : "false");
  state.defaultPriority = ["low", "normal", "high"].includes(preferences.defaultPriority) ? preferences.defaultPriority : "normal";
  state.undoSendSeconds = Number(preferences.undoSendSeconds) >= 5 && Number(preferences.undoSendSeconds) <= 10 ? Number(preferences.undoSendSeconds) : 8;
  const priorityControl = document.getElementById("defaultPrioritySelect");
  if (priorityControl) priorityControl.value = state.defaultPriority;
  const undoControl = document.getElementById("undoSendSelect");
  if (undoControl) undoControl.value = String(state.undoSendSeconds);
  const composeModeControl = document.getElementById("composeModeSelect");
  if (composeModeControl) composeModeControl.value = preferences.composeMode === "plain" ? "plain" : "html";
  const composeWidthControl = document.getElementById("composeWidthSelect");
  if (composeWidthControl) composeWidthControl.value = preferences.composeWidth || "wide";
  const composePositionControl = document.getElementById("composePositionSelect");
  if (composePositionControl) composePositionControl.value = preferences.composePosition || "center";
  const inboxViewControl = document.getElementById("inboxViewSelect");
  if (inboxViewControl) inboxViewControl.value = preferences.inboxView === "individual" ? "individual" : "grouped";
  if (languageSelect) {
    populateLanguageSelect(languageSelect);
    languageSelect.value = preferences.language || "en-US";
  }
  if (dateFormatSelect) dateFormatSelect.value = preferences.dateFormat || "auto";
  if (weekStartSelect) weekStartSelect.value = preferences.weekStart || "monday";
  if (timeZoneSelect) {
    if (timeZoneSelect.options.length < 3 || !Array.from(timeZoneSelect.options).some((option) => option.value === preferences.timeZone)) {
      timeZoneSelect.innerHTML = timeZoneOptions().map((zone) => `<option value="${esc(zone)}">${esc(zone.replace(/_/g, " "))}</option>`).join("");
    }
    timeZoneSelect.value = preferences.timeZone || "UTC";
  }
  $$("[data-time-format]").forEach((button) => {
    const active = button.getAttribute("data-time-format") === (preferences.timeFormat || "12h");
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
  if (workStartInput) workStartInput.value = preferences.workStart || "09:00";
  if (workEndInput) workEndInput.value = preferences.workEnd || "17:00";
  if (workdayRow) {
    $$("[data-work-day]", workdayRow).forEach((button) => {
      const active = (preferences.workDays || []).includes(Number(button.getAttribute("data-work-day")));
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });
  }
  if (defaultFromSelect) {
    const options = aliasesForSelect().map((alias) => `<option value="${esc(alias.email)}">${esc(alias.label)} — ${esc(alias.email)}</option>`).join("");
    if (defaultFromSelect.innerHTML !== options) defaultFromSelect.innerHTML = options;
    const fallback = aliasesForSelect()[0] ? aliasesForSelect()[0].email : "";
    defaultFromSelect.value = preferences.defaultFrom || fallback;
  }
  $$("[data-server-pref]").forEach((control) => {
    const key = control.getAttribute("data-server-pref");
    control.setAttribute("aria-checked", state.preferences[key] ? "true" : "false");
  });
  renderRegionalSettings();
  const zoneHint = document.getElementById("timeZoneHint");
  if (zoneHint) zoneHint.textContent = `All timestamps and scheduled sends use ${formatTimeZoneLabel()}.`;
}

function renderRegionalSettings() {
  if (!regionalPreview) return;
  const now = new Date();
  const full = new Intl.DateTimeFormat(currentLocale(), {
    weekday: "long", year: "numeric", month: "long", day: "numeric",
    hour: "numeric", minute: "2-digit",
    hour12: state.preferences.timeFormat !== "24h",
    timeZone: currentTimeZone()
  }).format(now);
  const start = zonedWallTimeToUtc(dateKeyInZone(now), state.preferences.workStart || "09:00");
  const end = zonedWallTimeToUtc(dateKeyInZone(now), state.preferences.workEnd || "17:00");
  const dayNames = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  const workDays = (state.preferences.workDays || []).map((day) => dayNames[day - 1]).join(", ");
  regionalPreview.innerHTML = `<span class="regional-preview-label">Preview in ${esc(currentTimeZone().replace(/_/g, " "))}</span>
    <strong>${esc(full)}</strong>
    <span>${esc(formatTimeZoneLabel())}</span>
    <span>Work hours ${start ? esc(formatClock(start)) : ""} – ${end ? esc(formatClock(end)) : ""} · ${esc(workDays || "No working days")}</span>
    <span>${esc(new Intl.DateTimeFormat(currentLocale(), { dateStyle: "full", timeZone: currentTimeZone() }).format(now))}</span>`;
}

async function patchPreferences(patch, message = "Preferences saved") {
  try {
    const data = await api("/api/preferences", { method: "PATCH", body: patch });
    state.preferences = { ...state.preferences, ...data.preferences };
    if (state.user) state.user.preferences = state.preferences;
    applyPreferenceChrome();
    syncPreferencesUi();
    rerenderAfterPreferenceChange();
    if (message) showToast(message);
    return true;
  } catch (error) {
    showError(error);
    syncPreferencesUi();
    return false;
  }
}

function rerenderAfterPreferenceChange() {
  if (state.task === "mail") {
    renderFolders();
    renderList();
    renderReader({ preserveScroll: true });
    syncStatusRange();
  } else if (state.task === "tasks") {
    renderTasks();
  } else if (state.task === "files") {
    renderFiles();
  } else if (state.task === "calendar") {
    renderCalendar();
  } else if (state.task === "settings") {
    renderRegionalSettings();
    renderAuditIfVisible();
  }
  if (!detailsOverlay.hidden) closeDetails();
}

function renderAuditIfVisible() {
  if (state.task === "settings" && state.settingsTab === "audit") renderAudit();
}

/* ============================================================
   toast
   ============================================================ */
function hideToast() {
  clearTimeout(toastTimer);
  clearInterval(toastInterval);
  toastInterval = null;
  toastEl.classList.remove("is-visible");
}

function showToast(message, actionLabel, action, options = {}) {
  clearTimeout(toastTimer);
  clearInterval(toastInterval);
  toastInterval = null;
  toastEl.innerHTML = "";
  const text = document.createElement("span");
  text.className = "toast-text";
  text.textContent = message;
  toastEl.appendChild(text);
  if (options.countdownAt) {
    const countdown = document.createElement("span");
    countdown.className = "toast-countdown";
    const update = () => {
      const remaining = Date.parse(options.countdownAt) - Date.now();
      countdown.textContent = remaining > 0 ? formatCountdown(remaining) : "sent";
      if (remaining <= 0 && toastInterval) {
        clearInterval(toastInterval);
        toastInterval = null;
        text.textContent = options.sentMessage || "Message sent";
        toastEl.classList.remove("is-undo-send");
        if (typeof options.onExpire === "function") options.onExpire();
      }
    };
    update();
    toastInterval = setInterval(update, 250);
    toastEl.appendChild(countdown);
    toastEl.classList.add("is-undo-send");
  }
  if (actionLabel && typeof action === "function") {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "toast-action";
    button.textContent = actionLabel;
    button.addEventListener("click", async () => {
      button.disabled = true;
      try { await action(); } catch (error) { showToast(error.message || "That action failed"); }
      hideToast();
    }, { once: true });
    toastEl.appendChild(button);
  }
  toastEl.classList.add("is-visible");
  const duration = options.duration != null ? options.duration : (actionLabel ? 10000 : 3200);
  toastTimer = setTimeout(hideToast, duration);
}

function showError(error) {
  const detail = error && error.details && error.details.errors ? ` ${error.details.errors.join(" · ")}` : "";
  showToast((error && error.message ? error.message : "Something went wrong") + detail);
}

/* ============================================================
   auth / boot
   ============================================================ */
const AUTH_SPLASH_HOLD_MS = 5000;
const LOGOUT_SPLASH_MS = 6000;
let bootSplashHideTimer = null;
let logoutInProgress = false;

function hideBootSplash() {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.classList.add("is-hiding");
  bootSplashHideTimer = setTimeout(() => { bootSplash.hidden = true; }, 380);
}

function showBootSplash(note = "Restoring your secure session and mailbox…") {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.hidden = false;
  bootSplash.classList.remove("is-hiding", "is-logout");
  bootSplash.setAttribute("aria-label", "Opening Alt8Mail");
  const heading = bootSplash.querySelector("h1");
  if (heading) heading.textContent = "Opening your workspace";
  const copy = bootSplash.querySelector("p:not(.eyebrow)");
  if (copy) copy.textContent = note;
  // Restart the progress animation when the splash is shown a second time.
  void bootSplash.offsetWidth;
}

function showLogoutSplash() {
  if (!bootSplash) return;
  clearTimeout(bootSplashHideTimer);
  bootSplash.hidden = false;
  bootSplash.classList.remove("is-hiding");
  bootSplash.classList.add("is-logout");
  bootSplash.setAttribute("aria-label", `Closing ${brandName()}`);
  const heading = bootSplash.querySelector("h1");
  if (heading) heading.textContent = "Closing your workspace.";
  const copy = bootSplash.querySelector("p:not(.eyebrow)");
  if (copy) copy.textContent = "Your session is ending. Signing out of your inbox...";
  void bootSplash.offsetWidth;
}

function clearThemeAccentForLogout() {
  // The login card must not inherit the previous account's accent. Remove the
  // pre-sign-in cache and any legacy accent cookie, then restore the default.
  try {
    for (const key of Object.keys(localStorage)) {
      if (/accent/i.test(key)) localStorage.removeItem(key);
    }
  } catch {}
  try {
    for (const entry of document.cookie.split(";")) {
      const name = entry.split("=")[0].trim();
      if (name && /accent/i.test(name)) {
        document.cookie = `${name}=; Max-Age=0; path=/; SameSite=Lax`;
      }
    }
  } catch {}
  state.accent = "blue";
  document.documentElement.style.setProperty("--accent", ACCENTS.blue.value);
  if (tenantBranding) applyTenantBranding(tenantBranding);
  $$("[data-set-accent]").forEach((button) => {
    const active = button.getAttribute("data-set-accent") === "blue";
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-checked", active ? "true" : "false");
  });
}

function resetLoginButtons() {
  loginBusy = false;
  if (loginSubmit) { loginSubmit.disabled = false; loginSubmit.textContent = t("login.signIn"); }
  if (ssoBtn) { ssoBtn.disabled = false; ssoBtn.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg><span data-i18n="login.sso">${esc(t("login.sso"))}</span>`; }
  if (twoFactorSubmit) { twoFactorSubmit.disabled = false; twoFactorSubmit.textContent = "Verify and sign in"; }
  if (usePasskeyBtn) usePasskeyBtn.disabled = false;
}

function showLogin() {
  document.querySelector(".delegated-closed-card")?.remove();
  closeAddonSetup();
  closeAddonResult();
  closeReaderAddonMenu();
  composeSessions.slice().forEach((session) => removeComposeSessionUi(session.id));
  composeSessions = [];
  state.user = null;
  avatarFailures.clear();
  threadIdAliases.clear();
  if (aiAttachmentPicker) settleAiAttachmentPicker([]);
  state.pendingMailRemoval.clear();
  state.notifications = [];
  state.dismissedNotifications = new Set();
  state.aiReader = null;
  activeComposeId = null;
  updateComposeDock();
  hideNotify();
  closeNoticeCenter();
  closeComposeAttach();
  hideToast();
  closeMenus();
  closeHelp();
  closeDetails();
  closeEventDialog();
  closeStatusPop();
  closeDrawer();
  document.body.classList.remove("composing", "drawer-open", "search-open", "reader-open", "person-open");
  loginScreen.hidden = false;
  app.hidden = true;
  loginError.hidden = true;
  loginHint.hidden = true;
  loginForm.hidden = false;
  twoFactorForm.hidden = true;
  const enrollment = document.getElementById("enrollmentForm");
  if (enrollment) enrollment.hidden = true;
  twoFactorChallenge = null;
  state.enrollmentChallenge = null;
  hidePasskeyPrompt();
  loginPassword.type = "password";
  const toggle = document.getElementById("passwordToggle");
  if (toggle) toggle.textContent = "Show";
  resetLoginButtons();
  loginScreen.scrollTop = 0;
  setTimeout(() => { if (loginEmail && !isMobile()) loginEmail.focus(); }, 60);
  stopOutboxPolling();
  const passwordOverlay = document.getElementById("passwordChangeOverlay");
  if (passwordOverlay) passwordOverlay.hidden = true;
  if (onboardingOverlay) onboardingOverlay.hidden = true;
  if (signatureEditorOverlay) signatureEditorOverlay.hidden = true;
  if (signaturePickerOverlay) signaturePickerOverlay.hidden = true;
  if (spellcheckOverlay) spellcheckOverlay.hidden = true;
  if (identityEditorOverlay) identityEditorOverlay.hidden = true;
  if (folderEditorOverlay) folderEditorOverlay.hidden = true;
  if (folderMenu) folderMenu.hidden = true;
  state.folderEditor = null;
  state.signatureEditor = null;
  state.identityEditor = null;
  state.spellcheck = null;
  state.imageOverrides = new Set();
  document.body.classList.remove("onboarding-active");
  if (app) app.inert = false;
  if (state.pendingSends.length && state.user) {
    // A signed-out tab cannot cancel; data remains in the server queue.
  }
  updateDocumentTitle();
  hideBootSplash();
}

async function finishSignIn(data, { holdSplashMs = 0 } = {}) {
  const splashStartedAt = Date.now();
  if (holdSplashMs > 0) showBootSplash("Authentication confirmed. Opening your secure workspace…");
  state.csrf = data.csrf || state.csrf;
  loginScreen.hidden = true;
  app.hidden = false;
  loginForm.hidden = false;
  twoFactorForm.hidden = true;
  const enrollmentForm = document.getElementById("enrollmentForm");
  if (enrollmentForm) enrollmentForm.hidden = true;
  twoFactorChallenge = null;
  state.enrollmentChallenge = null;
  hidePasskeyPrompt();
  resetLoginButtons();
  await loadBootstrap({ restoreDrafts: true });
  loadCatchUp().catch(() => {});
  restoreNavigationFromLocation();
  requestAnimationFrame(layoutComposeSessions);
  if (holdSplashMs > 0) {
    const copy = bootSplash?.querySelector("p:not(.eyebrow)");
    if (copy) copy.textContent = "Your mailbox is ready. Opening your inbox…";
    const remaining = holdSplashMs - (Date.now() - splashStartedAt);
    if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
  }
  hideBootSplash();
}

function finishAuthenticatedSignIn(data) {
  return finishSignIn(data, { holdSplashMs: AUTH_SPLASH_HOLD_MS }).catch((error) => {
    hideBootSplash();
    throw error;
  });
}

async function submitLogin() {
  if (loginBusy) return;
  const email = loginEmail.value.trim();
  const password = loginPassword.value;
  loginError.hidden = true;
  loginHint.hidden = true;
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    loginError.textContent = t("login.invalidEmail");
    loginError.hidden = false;
    loginEmail.focus();
    return;
  }
  if (!password) {
    loginError.textContent = t("login.passwordRequired");
    loginError.hidden = false;
    loginPassword.focus();
    return;
  }
  loginBusy = true;
  loginSubmit.disabled = true;
  loginSubmit.textContent = t("login.signingIn");
  ssoBtn.disabled = true;
  try {
    const remember = document.getElementById("rememberMe").checked;
    const data = await api("/api/session", {
      method: "POST",
      skipAuth: true,
      body: { email, password, method: "password", remember }
    });
    if (data.twoFactorRequired) {
      resetLoginButtons();
      showTwoFactorChallenge(data, remember);
      return;
    }
    if (data.enrollmentRequired) {
      resetLoginButtons();
      showEnrollmentChallenge(data, remember);
      return;
    }
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    loginError.textContent = error.message;
    loginError.hidden = false;
    resetLoginButtons();
  }
}

async function submitSso() {
  if (loginBusy) return;
  loginBusy = true;
  loginError.hidden = true;
  loginSubmit.disabled = true;
  ssoBtn.disabled = true;
  ssoBtn.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-shield-check"/></svg>Connecting to SSO…';
  try {
    const data = await api("/api/session", {
      method: "POST",
      skipAuth: true,
      body: { email: loginEmail.value.trim(), method: "sso", remember: document.getElementById("rememberMe").checked }
    });
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    loginError.textContent = error.message;
    loginError.hidden = false;
    resetLoginButtons();
  }
}

function showTwoFactorChallenge(data, remember) {
  twoFactorChallenge = { ...data, remember };
  state.twoFactor = data;
  loginForm.hidden = true;
  twoFactorForm.hidden = false;
  loginError.hidden = true;
  loginHint.hidden = true;
  twoFactorError.hidden = true;
  const user = data.user || {};
  const avatarEl = document.getElementById("twoFactorAvatar");
  if (avatarEl) {
    avatarEl.textContent = user.initials || initialsFrom(user.name || "");
    avatarEl.style.setProperty("--av", user.color || "#34557a");
  }
  document.getElementById("twoFactorName").textContent = user.name || "Alt8Mail account";
  document.getElementById("twoFactorEmail").textContent = user.email || loginEmail.value.trim();
  const passkey = (data.passkeys || [])[0];
  const passkeyPanel = document.getElementById("passkeyPanel");
  const canPasskey = Boolean(data.methods && data.methods.passkey);
  passkeyPanel.hidden = !canPasskey;
  if (canPasskey) {
    document.getElementById("passkeyName").textContent = passkey ? passkey.name : "Registered passkey";
  }
  const canAuthenticator = Boolean(data.methods && data.methods.authenticator);
  const canRecovery = Boolean(data.methods && data.methods.recovery);
  const demo = canAuthenticator && data.demoCode ? data.demoCode : "";
  twoFactorDemo.hidden = !demo;
  if (demo) document.getElementById("twoFactorDemoCode").textContent = demo;
  document.getElementById("recoveryModeBtn").hidden = !canRecovery;
  document.getElementById("otpModeBtn").hidden = !canAuthenticator;
  $$("#otpInputs input").forEach((input) => { input.value = ""; input.disabled = !canAuthenticator; });
  document.getElementById("recoveryCode").value = "";
  document.getElementById("trustDevice").checked = false;
  setTwoFactorMode(canAuthenticator ? "otp" : "recovery");
  twoFactorForm.classList.remove("is-shaking");
  requestAnimationFrame(() => {
    const first = canAuthenticator ? document.getElementById("otp0") : document.getElementById("recoveryCode");
    if (first) first.focus();
  });
}

function setTwoFactorMode(mode) {
  state.twoFactorMode = mode === "recovery" ? "recovery" : "otp";
  const recovery = state.twoFactorMode === "recovery";
  document.getElementById("otpBlock").hidden = recovery;
  document.getElementById("recoveryBlock").hidden = !recovery;
  twoFactorSubmit.textContent = recovery ? "Verify recovery code" : "Verify and sign in";
  setTimeout(() => {
    const target = recovery ? document.getElementById("recoveryCode") : document.getElementById("otp0");
    if (target) target.focus();
  }, 40);
}

function otpCodeValue() {
  return $$("#otpInputs input").map((input) => input.value.replace(/\D/g, "")).join("");
}

function fillOtp(code) {
  const digits = String(code || "").replace(/\D/g, "").slice(0, 6).split("");
  $$("#otpInputs input").forEach((input, index) => { input.value = digits[index] || ""; });
  const target = $$("#otpInputs input").find((input) => !input.value) || document.getElementById("otp5");
  if (target) target.focus();
}

function hideTwoFactor() {
  twoFactorChallenge = null;
  twoFactorForm.hidden = true;
  loginForm.hidden = false;
  hidePasskeyPrompt();
  const first = document.getElementById("loginPassword");
  if (first) setTimeout(() => first.focus(), 40);
}

async function showPasskeyPrompt() {
  if (!twoFactorChallenge) return;
  if (!window.PublicKeyCredential || !navigator.credentials) {
    twoFactorError.textContent = "This browser does not support passkeys.";
    twoFactorError.hidden = false;
    return;
  }
  const profile = passkeyDeviceProfile();
  const passkey = (twoFactorChallenge.passkeys || [])[0];
  document.getElementById("passkeyPromptText").textContent = passkey
    ? `Confirm “${passkey.name}” to finish signing in.`
    : "Confirm with your device to finish signing in.";
  const deviceName = document.getElementById("passkeyPromptDeviceName");
  const deviceHint = document.getElementById("passkeyPromptDeviceHint");
  if (deviceName) deviceName.textContent = passkey ? passkey.name : profile.label;
  if (deviceHint) deviceHint.textContent = `${profile.biometric} · stays on this device`;
  passkeyPromptStatus.innerHTML = '<span class="passkey-spinner" aria-hidden="true"></span>Waiting for your device…';
  passkeyOverlay.hidden = false;
  twoFactorError.hidden = true;
  usePasskeyBtn.disabled = true;
  const controller = new AbortController();
  passkeyPromptAbort = controller;
  clearTimeout(passkeyTimer);
  passkeyTimer = setTimeout(() => {
    if (passkeyOverlay.hidden) return;
    passkeyPromptStatus.innerHTML = '<span class="passkey-spinner" aria-hidden="true"></span>Still waiting — look for a prompt behind this window.';
  }, 12000);
  try {
    const begin = await api("/api/session/2fa/webauthn/begin", {
      method: "POST", skipAuth: true,
      body: { challengeId: twoFactorChallenge.challengeId }
    });
    const publicKey = prepareAssertionOptions(begin.publicKey);
    const credential = await navigator.credentials.get({ publicKey, signal: controller.signal });
    const trust = document.getElementById("trustDevice").checked;
    const data = await api(`/api/session/2fa/webauthn/finish?flow=${encodeURIComponent(begin.flowId)}&trustDevice=${trust ? "1" : "0"}`, {
      method: "POST", skipAuth: true, body: serializeWebAuthnCredential(credential)
    });
    clearTimeout(passkeyTimer);
    passkeyTimer = null;
    passkeyPromptAbort = null;
    usePasskeyBtn.disabled = false;
    hidePasskeyPrompt(false);
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    const cancelled = (error && error.name === "AbortError") || passkeyOverlay.hidden;
    hidePasskeyPrompt(false);
    usePasskeyBtn.disabled = false;
    if (cancelled) return;
    twoFactorError.textContent = webAuthnErrorMessage(error, "login").message;
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    resetLoginButtons();
  }
}

function hidePasskeyPrompt(abortRequest = true) {
  clearTimeout(passkeyTimer);
  passkeyTimer = null;
  const controller = passkeyPromptAbort;
  passkeyPromptAbort = null;
  if (passkeyOverlay) passkeyOverlay.hidden = true;
  if (abortRequest && controller) {
    try { controller.abort(); } catch {}
  }
  usePasskeyBtn.disabled = false;
}

async function submitTwoFactor(event) {
  if (event) event.preventDefault();
  if (!twoFactorChallenge) return;
  const method = state.twoFactorMode === "recovery" ? "recovery" : "totp";
  const code = method === "recovery" ? document.getElementById("recoveryCode").value.trim() : otpCodeValue();
  if (method === "totp" && code.length !== 6) {
    twoFactorError.textContent = "Enter the six-digit code from your authenticator app.";
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    return;
  }
  if (method === "recovery" && !code) {
    twoFactorError.textContent = "Enter one of your recovery codes.";
    twoFactorError.hidden = false;
    return;
  }
  await verifyTwoFactor(method, code);
}

async function verifyTwoFactor(method, code) {
  if (!twoFactorChallenge) return;
  twoFactorError.hidden = true;
  twoFactorSubmit.disabled = true;
  twoFactorSubmit.textContent = "Checking code…";
  usePasskeyBtn.disabled = true;
  try {
    const data = await api("/api/session/2fa", {
      method: "POST",
      skipAuth: true,
      body: {
        challengeId: twoFactorChallenge.challengeId,
        method,
        code,
        trustDevice: document.getElementById("trustDevice").checked
      }
    });
    hidePasskeyPrompt();
    state.csrf = data.csrf;
    await finishAuthenticatedSignIn(data);
  } catch (error) {
    hidePasskeyPrompt();
    twoFactorError.textContent = error.message + (error.details && error.details.attemptsRemaining != null ? ` ${error.details.attemptsRemaining} attempt${error.details.attemptsRemaining === 1 ? "" : "s"} remaining.` : "");
    twoFactorError.hidden = false;
    twoFactorForm.classList.add("is-shaking");
    setTimeout(() => twoFactorForm.classList.remove("is-shaking"), 350);
    resetLoginButtons();
    if (state.twoFactorMode === "otp") fillOtp("");
  }
}

/* ---------- WebAuthn and first-time enrollment ---------- */
function decodeWebAuthnValue(value) {
  const text = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = text + "=".repeat((4 - text.length % 4) % 4);
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes.buffer;
}

function encodeWebAuthnValue(buffer) {
  const bytes = new Uint8Array(buffer || new ArrayBuffer(0));
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function prepareCreationOptions(publicKey) {
  const options = JSON.parse(JSON.stringify(publicKey || {}));
  options.challenge = decodeWebAuthnValue(options.challenge);
  if (options.user && options.user.id) options.user.id = decodeWebAuthnValue(options.user.id);
  if (Array.isArray(options.excludeCredentials)) {
    options.excludeCredentials = options.excludeCredentials.map((entry) => ({ ...entry, id: decodeWebAuthnValue(entry.id) }));
  }
  return options;
}

function prepareAssertionOptions(publicKey) {
  const options = JSON.parse(JSON.stringify(publicKey || {}));
  options.challenge = decodeWebAuthnValue(options.challenge);
  if (Array.isArray(options.allowCredentials)) {
    options.allowCredentials = options.allowCredentials.map((entry) => ({ ...entry, id: decodeWebAuthnValue(entry.id) }));
  }
  return options;
}

function serializeWebAuthnCredential(credential) {
  if (credential && typeof credential.toJSON === "function") return credential.toJSON();
  const response = credential.response;
  const result = {
    id: credential.id,
    rawId: encodeWebAuthnValue(credential.rawId),
    type: credential.type,
    clientExtensionResults: typeof credential.getClientExtensionResults === "function" ? credential.getClientExtensionResults() : {},
    response: {}
  };
  if (response.attestationObject) {
    result.response = {
      clientDataJSON: encodeWebAuthnValue(response.clientDataJSON),
      attestationObject: encodeWebAuthnValue(response.attestationObject),
      transports: typeof response.getTransports === "function" ? response.getTransports() : []
    };
  } else {
    result.response = {
      clientDataJSON: encodeWebAuthnValue(response.clientDataJSON),
      authenticatorData: encodeWebAuthnValue(response.authenticatorData),
      signature: encodeWebAuthnValue(response.signature),
      userHandle: response.userHandle ? encodeWebAuthnValue(response.userHandle) : null
    };
  }
  return result;
}

function showEnrollmentChallenge(data, remember) {
  state.enrollmentChallenge = { ...data, remember };
  loginForm.hidden = true;
  twoFactorForm.hidden = true;
  const form = document.getElementById("enrollmentForm");
  form.hidden = false;
  document.getElementById("enrollmentError").hidden = true;
  document.getElementById("enrollmentTotpBlock").hidden = true;
  const user = data.user || {};
  document.getElementById("enrollmentAvatar").textContent = user.initials || initialsFrom(user.name || "");
  document.getElementById("enrollmentAvatar").style.setProperty("--av", user.color || "#34557a");
  document.getElementById("enrollmentName").textContent = user.name || "Alt8Mail account";
  document.getElementById("enrollmentEmail").textContent = user.email || loginEmail.value.trim();
  requestAnimationFrame(() => document.getElementById("enrollmentTotpBtn").focus());
}

function cancelEnrollment() {
  state.enrollmentChallenge = null;
  document.getElementById("enrollmentForm").hidden = true;
  document.getElementById("loginForm").hidden = false;
  document.getElementById("enrollmentTotpBlock").hidden = true;
  resetLoginButtons();
}

async function beginEnrollmentTOTP() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  const button = document.getElementById("enrollmentTotpBtn");
  button.disabled = true;
  try {
    const data = await api("/api/enrollment/totp/begin", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken } });
    document.getElementById("enrollmentTotpSecret").textContent = data.secret;
    document.getElementById("enrollmentTotpBlock").hidden = false;
    const qrHost = document.getElementById("enrollmentQrHost");
    if (qrHost) {
      qrHost.innerHTML = "";
      requestAnimationFrame(() => renderTotpQr(qrHost, data.otpauth, 320));
    }
    document.getElementById("enrollmentTotpCode").value = "";
    document.getElementById("enrollmentTotpCode").focus();
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.message;
    document.getElementById("enrollmentError").hidden = false;
  } finally { button.disabled = false; }
}

async function verifyEnrollmentTOTP() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  const code = document.getElementById("enrollmentTotpCode").value.replace(/\D/g, "");
  if (code.length !== 6) {
    document.getElementById("enrollmentError").textContent = "Enter the six-digit code from your authenticator app.";
    document.getElementById("enrollmentError").hidden = false;
    return;
  }
  const button = document.getElementById("enrollmentTotpVerify");
  button.disabled = true;
  button.textContent = "Verifying…";
  try {
    const data = await api("/api/enrollment/totp/finish", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken, code } });
    await completeEnrollment(data);
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.message;
    document.getElementById("enrollmentError").hidden = false;
  } finally {
    button.disabled = false;
    button.textContent = "Verify and continue";
  }
}

async function beginEnrollmentPasskey() {
  const challenge = state.enrollmentChallenge;
  if (!challenge) return;
  if (!window.PublicKeyCredential || !navigator.credentials) {
    document.getElementById("enrollmentError").textContent = "This browser does not support passkeys.";
    document.getElementById("enrollmentError").hidden = false;
    return;
  }
  const button = document.getElementById("enrollmentPasskeyBtn");
  button.disabled = true;
  try {
    const begin = await api("/api/enrollment/webauthn/begin", { method: "POST", skipAuth: true, body: { token: challenge.enrollmentToken } });
    const credential = await navigator.credentials.create({ publicKey: prepareCreationOptions(begin.publicKey) });
    if (!credential) throw new Error("Passkey creation was cancelled");
    const data = await api(`/api/enrollment/webauthn/finish?flow=${encodeURIComponent(begin.flowId)}`, {
      method: "POST", skipAuth: true, body: serializeWebAuthnCredential(credential)
    });
    await completeEnrollment(data);
  } catch (error) {
    document.getElementById("enrollmentError").textContent = error.name === "NotAllowedError" ? "Passkey creation was cancelled or timed out." : (error.message || "Passkey enrollment failed.");
    document.getElementById("enrollmentError").hidden = false;
  } finally { button.disabled = false; }
}

async function completeEnrollment(data) {
  state.enrollmentChallenge = null;
  document.getElementById("enrollmentForm").hidden = true;
  state.csrf = data.csrf;
  await finishAuthenticatedSignIn(data);
  if (Array.isArray(data.recoveryCodes) && data.recoveryCodes.length) {
    showRecoveryCodes(data.recoveryCodes, "Save these recovery codes now. They are shown only once.");
  }
}

/* ---------- authenticator setup ---------- */
const TOTP_PROVIDERS = {
  google: {
    label: "Google Authenticator",
    tip: "Open Google Authenticator, tap <strong>+</strong>, then choose <strong>Scan a QR code</strong>.",
    keyHelp: "Open Google Authenticator, tap <strong>+</strong> and choose <strong>Enter a setup key</strong>. Paste the key and keep <strong>Time based</strong> selected.",
    downloads: [
      { label: "Google Play", href: "https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" },
      { label: "App Store", href: "https://apps.apple.com/app/google-authenticator/id388497605" }
    ]
  },
  microsoft: {
    label: "Microsoft Authenticator",
    tip: "In Microsoft Authenticator, tap <strong>+</strong> → <strong>Other account</strong> → <strong>Scan a QR code</strong>.",
    keyHelp: "In Microsoft Authenticator choose <strong>Other account</strong> → <strong>Enter code manually</strong>. Paste the key; Microsoft labels it “secret key”.",
    downloads: [
      { label: "Microsoft", href: "https://www.microsoft.com/en-us/security/mobile-authenticator-app" },
      { label: "Google Play", href: "https://play.google.com/store/apps/details?id=com.azure.authenticator" },
      { label: "App Store", href: "https://apps.apple.com/app/microsoft-authenticator/id983156458" }
    ]
  },
  authy: {
    label: "Authy",
    tip: "Open Authy, tap <strong>+</strong>, choose <strong>Add Account</strong>, then <strong>Scan QR Code</strong>.",
    keyHelp: "In Authy choose <strong>Add Account</strong> → <strong>Enter key manually</strong>. Paste the key and keep the timer at 30 seconds.",
    downloads: [
      { label: "authy.com", href: "https://authy.com/download/" },
      { label: "Google Play", href: "https://play.google.com/store/apps/details?id=com.authy.authy" },
      { label: "App Store", href: "https://apps.apple.com/app/authy/id494168017" }
    ]
  }
};

function totpSetupInputs() {
  return $$("#totpSetupCodeInputs input");
}

function totpSetupCodeValue() {
  return totpSetupInputs().map((input) => (input.value || "").replace(/\D/g, "")).join("").slice(0, 6);
}

function totpGroupedSecret(secret) {
  const raw = String(secret || "").replace(/\s+/g, "").toUpperCase();
  return raw.match(/.{1,4}/g)?.join(" ") || "";
}

function maskedTotpSecret(secret) {
  return totpGroupedSecret(secret).replace(/[A-Z0-9]/g, "•");
}

function renderTotpQr(host, uri, size = 360) {
  if (!host) return false;
  host.innerHTML = "";
  if (!uri) {
    host.innerHTML = '<div class="totp-qr-fallback"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 8v5"/><circle cx="12" cy="17" r=".9" fill="currentColor" stroke="none"/><path d="M10.3 3.8 2.9 17a2 2 0 0 0 1.7 3h14.8a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg><strong>No QR code</strong><span>Use the setup key below instead.</span></div>';
    return false;
  }
  if (!window.QRCode) {
    host.innerHTML = '<div class="totp-qr-fallback"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 8v5"/><circle cx="12" cy="17" r=".9" fill="currentColor" stroke="none"/><path d="M10.3 3.8 2.9 17a2 2 0 0 0 1.7 3h14.8a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg><strong>QR preview unavailable</strong><span>Use the setup key below in your authenticator app.</span></div>';
    return false;
  }
  try {
    new window.QRCode(host, {
      text: uri,
      width: size,
      height: size,
      correctLevel: window.QRCode.CorrectLevel.M,
      colorDark: "#0b1a2a",
      colorLight: "#ffffff"
    });
    return true;
  } catch (error) {
    host.innerHTML = '<div class="totp-qr-fallback"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 8v5"/><circle cx="12" cy="17" r=".9" fill="currentColor" stroke="none"/><path d="M10.3 3.8 2.9 17a2 2 0 0 0 1.7 3h14.8a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg><strong>QR preview couldn’t load</strong><span>Use the setup key below instead.</span></div>';
    return false;
  }
}

function renderTotpSecret() {
  const secretEl = document.getElementById("totpSetupSecret");
  if (!secretEl) return;
  const secret = (totpSetupData && totpSetupData.secret) || secretEl.dataset.rawSecret || "";
  secretEl.textContent = totpSecretVisible ? totpGroupedSecret(secret) : maskedTotpSecret(secret);
  secretEl.classList.toggle("is-masked", !totpSecretVisible);
  const reveal = document.getElementById("totpRevealSecret");
  if (reveal) {
    reveal.textContent = totpSecretVisible ? "Hide" : "Show";
    reveal.setAttribute("aria-pressed", totpSecretVisible ? "true" : "false");
  }
}

function selectTotpProvider(id) {
  const provider = TOTP_PROVIDERS[id] ? id : "google";
  totpProviderId = provider;
  $$("#totpProviderList .totp-provider").forEach((card) => {
    const selected = card.dataset.totpProvider === provider;
    card.classList.toggle("is-selected", selected);
    card.setAttribute("aria-checked", selected ? "true" : "false");
    card.tabIndex = selected ? 0 : -1;
  });
  const config = TOTP_PROVIDERS[provider];
  const tip = document.getElementById("totpProviderTip");
  if (tip) tip.innerHTML = config.tip;
  const keyHelp = document.getElementById("totpKeyHelp");
  if (keyHelp) keyHelp.innerHTML = config.keyHelp;
  const downloads = document.getElementById("totpProviderDownloads");
  if (downloads) {
    downloads.innerHTML = config.downloads.map((link) => `<a class="totp-download-link" href="${esc(link.href)}" target="_blank" rel="noopener noreferrer"><svg class="icon" aria-hidden="true"><use href="#i-download"/></svg><span>${esc(link.label)}</span><svg class="icon" aria-hidden="true"><use href="#i-external"/></svg></a>`).join("");
  }
}

function setTotpSetupStep(step) {
  const verifying = step === "verify";
  $$("[data-totp-step]").forEach((element) => {
    const isVerify = element.dataset.totpStep === "verify";
    element.classList.toggle("is-current", verifying ? isVerify : !isVerify);
    element.classList.toggle("is-done", verifying && !isVerify);
  });
}

function toggleTotpKeyPanel(force) {
  const panel = document.getElementById("totpKeyPanel");
  const toggle = document.getElementById("totpKeyToggle");
  if (!panel || !toggle) return;
  const open = typeof force === "boolean" ? force : panel.hidden;
  panel.hidden = !open;
  toggle.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) renderTotpSecret();
}

function updateTotpSetupState() {
  const inputs = totpSetupInputs();
  const code = totpSetupCodeValue();
  inputs.forEach((input) => input.classList.toggle("is-filled", Boolean(input.value)));
  const verify = document.getElementById("totpSetupVerify");
  if (verify) {
    verify.disabled = totpSetupSubmitting || code.length !== 6;
    if (!totpSetupSubmitting) verify.textContent = "Verify and enable";
  }
  const actionHint = document.getElementById("totpSetupActionHint");
  if (actionHint && !totpSetupSubmitting) {
    if (code.length === 6) actionHint.textContent = "Ready — verify to finish setup";
    else if (code.length) actionHint.textContent = `${6 - code.length} digit${6 - code.length === 1 ? "" : "s"} to go`;
    else actionHint.textContent = "Scan the QR code to begin";
  }
  const codeHint = document.getElementById("totpSetupCodeHint");
  if (codeHint && !totpSetupSubmitting) codeHint.textContent = "Codes refresh automatically. Wait for the next code if this one has expired.";
}

function fillTotpSetupCode(code, focus = true) {
  const digits = String(code || "").replace(/\D/g, "").slice(0, 6).split("");
  const inputs = totpSetupInputs();
  inputs.forEach((input, index) => { input.value = digits[index] || ""; });
  if (focus) {
    const target = inputs.find((input) => !input.value) || inputs[inputs.length - 1];
    if (target) target.focus();
  }
  updateTotpSetupState();
}

function resetTotpSetupCode() {
  fillTotpSetupCode("", false);
}

function scheduleTotpSetupVerify(delay = 320) {
  clearTimeout(totpSetupAutoTimer);
  totpSetupAutoTimer = null;
  if (totpSetupAutoTriggered || totpSetupSubmitting) return;
  if (totpSetupCodeValue().length !== 6) return;
  totpSetupAutoTriggered = true;
  totpSetupAutoTimer = setTimeout(() => {
    totpSetupAutoTimer = null;
    if (!totpSetupSubmitting && totpSetupCodeValue().length === 6) verifyTotpSetup();
  }, delay);
}

async function copyTotpSecret(button) {
  const secretEl = document.getElementById("totpSetupSecret");
  const secret = (totpSetupData && totpSetupData.secret) || secretEl?.dataset.rawSecret || "";
  if (!secret) return;
  const ok = await copyTextToClipboard(secret);
  if (!button) return;
  const original = button.innerHTML;
  button.innerHTML = ok
    ? '<svg class="icon" aria-hidden="true"><use href="#i-check"/></svg><span>Copied</span>'
    : '<svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg><span>Copy failed</span>';
  button.classList.toggle("is-copied", ok);
  setTimeout(() => {
    if (button.isConnected) {
      button.innerHTML = original;
      button.classList.remove("is-copied");
    }
  }, 1800);
}

function bindTotpSetupInputs() {
  const inputs = totpSetupInputs();
  if (!inputs.length) return;
  inputs.forEach((input, index) => {
    input.addEventListener("input", () => {
      const digits = (input.value || "").replace(/\D/g, "");
      if (digits.length > 1) {
        totpSetupAutoTriggered = false;
        fillTotpSetupCode(digits);
        scheduleTotpSetupVerify();
        return;
      }
      input.value = digits.slice(-1);
      if (input.value && index < inputs.length - 1) inputs[index + 1].focus();
      setTotpSetupStep("verify");
      totpSetupAutoTriggered = false;
      updateTotpSetupState();
      scheduleTotpSetupVerify();
    });
    input.addEventListener("keydown", (event) => {
      if (event.key === "Backspace" && !input.value && index > 0) {
        inputs[index - 1].focus();
        inputs[index - 1].value = "";
        totpSetupAutoTriggered = false;
        updateTotpSetupState();
        event.preventDefault();
      } else if (event.key === "ArrowLeft" && index > 0) {
        inputs[index - 1].focus();
      } else if (event.key === "ArrowRight" && index < inputs.length - 1) {
        inputs[index + 1].focus();
      } else if (event.key === "Enter" && totpSetupCodeValue().length === 6) {
        event.preventDefault();
        verifyTotpSetup();
      }
    });
    input.addEventListener("focus", () => setTotpSetupStep("verify"));
  });
  document.getElementById("totpSetupCodeInputs")?.addEventListener("paste", (event) => {
    event.preventDefault();
    const text = (event.clipboardData || window.clipboardData)?.getData("text") || "";
    totpSetupAutoTriggered = false;
    fillTotpSetupCode(text);
    setTotpSetupStep("verify");
    scheduleTotpSetupVerify(180);
  });
}

function bindTotpProviderChooser() {
  const cards = $$("#totpProviderList .totp-provider");
  if (!cards.length) return;
  const choose = (card) => {
    selectTotpProvider(card.dataset.totpProvider);
    card.focus();
  };
  cards.forEach((card, index) => {
    card.addEventListener("click", () => selectTotpProvider(card.dataset.totpProvider));
    card.addEventListener("keydown", (event) => {
      if (event.key === " " || event.key === "Enter") {
        event.preventDefault();
        choose(card);
      } else if (event.key === "ArrowDown" || event.key === "ArrowRight") {
        event.preventDefault();
        const next = cards[(index + 1) % cards.length];
        next.tabIndex = 0;
        choose(next);
      } else if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
        event.preventDefault();
        const previous = cards[(index - 1 + cards.length) % cards.length];
        previous.tabIndex = 0;
        choose(previous);
      }
    });
  });
}

function closeTotpSetup() {
  clearTimeout(totpSetupAutoTimer);
  totpSetupAutoTimer = null;
  if (totpSetupOverlay) totpSetupOverlay.hidden = true;
  totpSetupSubmitting = false;
  totpSetupAutoTriggered = false;
  totpSetupData = null;
  const secretEl = document.getElementById("totpSetupSecret");
  if (secretEl) {
    secretEl.dataset.rawSecret = "";
    secretEl.textContent = "•••• •••• •••• ••••";
    secretEl.classList.add("is-masked");
  }
  const qrHost = document.getElementById("totpQrHost");
  if (qrHost) qrHost.replaceChildren();
  toggleTotpKeyPanel(false);
}

async function startTotpSetup() {
  hideToast();
  const error = document.getElementById("totpSetupError");
  const trigger = document.getElementById("setupTotpBtn");
  if (error) error.hidden = true;
  totpSecretVisible = false;
  totpSetupAutoTriggered = false;
  totpSetupSubmitting = false;
  clearTimeout(totpSetupAutoTimer);
  totpSetupAutoTimer = null;
  setTotpSetupStep("scan");
  toggleTotpKeyPanel(false);
  resetTotpSetupCode();
  const clearSecretEl = document.getElementById("totpSetupSecret");
  if (clearSecretEl) {
    clearSecretEl.dataset.rawSecret = "";
    clearSecretEl.textContent = "•••• •••• •••• ••••";
  }
  renderTotpSecret();
  selectTotpProvider(totpProviderId);
  const verify = document.getElementById("totpSetupVerify");
  if (verify) { verify.disabled = true; verify.textContent = "Verify and enable"; }
  const actionHint = document.getElementById("totpSetupActionHint");
  if (actionHint) actionHint.textContent = "Scan the QR code to begin";
  const qrHost = document.getElementById("totpQrHost");
  if (qrHost) qrHost.innerHTML = '<div class="totp-qr-placeholder"><span class="passkey-spinner" aria-hidden="true"></span><span>Preparing QR code…</span></div>';
  if (trigger) { trigger.disabled = true; trigger.textContent = "Starting…"; }
  try {
    const data = await api("/api/security/2fa/totp/begin", { method: "POST", body: {} });
    totpSetupData = data;
    const secretEl = document.getElementById("totpSetupSecret");
    if (secretEl) secretEl.dataset.rawSecret = data.secret || "";
    renderTotpSecret();
    if (totpSetupOverlay) {
      totpSetupOverlay.hidden = false;
      const body = totpSetupOverlay.querySelector(".security-dialog-body");
      if (body) body.scrollTop = 0;
    }
    requestAnimationFrame(() => {
      renderTotpQr(qrHost, data.otpauth, 360);
      updateTotpSetupState();
      if (window.innerWidth > 720 && window.matchMedia("(pointer: fine)").matches) document.getElementById("totpSetupOtp0")?.focus();
    });
  } catch (err) {
    showError(err);
  } finally {
    if (trigger) { trigger.disabled = false; trigger.textContent = "Set up"; }
  }
}

async function verifyTotpSetup() {
  if (totpSetupSubmitting) return;
  const code = totpSetupCodeValue();
  const error = document.getElementById("totpSetupError");
  if (code.length !== 6) {
    if (error) { error.textContent = "Enter the six-digit code from your authenticator app."; error.hidden = false; }
    updateTotpSetupState();
    return;
  }
  const button = document.getElementById("totpSetupVerify");
  const actionHint = document.getElementById("totpSetupActionHint");
  const codeHint = document.getElementById("totpSetupCodeHint");
  totpSetupSubmitting = true;
  clearTimeout(totpSetupAutoTimer);
  totpSetupAutoTimer = null;
  if (error) error.hidden = true;
  if (button) { button.disabled = true; button.innerHTML = '<span class="passkey-spinner" aria-hidden="true"></span>Checking…'; }
  if (actionHint) actionHint.textContent = "Checking your code…";
  if (codeHint) codeHint.textContent = "Verifying with the Alt8Mail server…";
  try {
    const data = await api("/api/security/2fa/totp/finish", { method: "POST", skipAuth: true, body: { code } });
    state.security = data.security || state.security;
    closeTotpSetup();
    renderSecuritySettings();
    if (Array.isArray(data.codes) && data.codes.length) showRecoveryCodes(data.codes, "Save these recovery codes now. They are shown only once.");
    else showToast("Authenticator enabled");
  } catch (err) {
    if (error) {
      error.textContent = err.message || "That code did not match. Check your app and try again.";
      error.hidden = false;
    }
    totpSetupAutoTriggered = false;
    resetTotpSetupCode();
    setTotpSetupStep("verify");
    document.getElementById("totpSetupOtp0")?.focus();
    const dialog = totpSetupOverlay?.querySelector(".totp-setup-dialog");
    if (dialog) {
      dialog.classList.add("is-shaking");
      setTimeout(() => dialog.classList.remove("is-shaking"), 350);
    }
    if (actionHint) actionHint.textContent = "That code didn’t match — try the next one";
  } finally {
    totpSetupSubmitting = false;
    if (button) button.textContent = "Verify and enable";
    updateTotpSetupState();
  }
}

/* ---------- authenticator removal ---------- */
function openDisableTotp() {
  hideToast();
  const error = document.getElementById("totpDisableError");
  const password = document.getElementById("totpDisablePassword");
  const button = document.getElementById("totpDisableConfirm");
  if (error) error.hidden = true;
  if (password) password.value = "";
  if (button) { button.disabled = false; button.textContent = "Remove authenticator"; }
  if (totpDisableOverlay) totpDisableOverlay.hidden = false;
  setTimeout(() => password?.focus(), 40);
}

function closeTotpDisable() {
  if (totpDisableOverlay) totpDisableOverlay.hidden = true;
  const password = document.getElementById("totpDisablePassword");
  if (password) password.value = "";
  const error = document.getElementById("totpDisableError");
  if (error) error.hidden = true;
}

async function disableTotp(event) {
  if (event) event.preventDefault();
  const passwordEl = document.getElementById("totpDisablePassword");
  const error = document.getElementById("totpDisableError");
  const button = document.getElementById("totpDisableConfirm");
  const password = passwordEl ? passwordEl.value : "";
  if (!password) {
    if (error) { error.textContent = "Enter your current account password."; error.hidden = false; }
    passwordEl?.focus();
    return;
  }
  if (button) { button.disabled = true; button.innerHTML = '<span class="passkey-spinner" aria-hidden="true"></span>Removing…'; }
  if (error) error.hidden = true;
  try {
    const data = await api("/api/security/2fa/totp/disable", { method: "POST", skipAuth: true, body: { password } });
    state.security = data.security || state.security;
    closeTotpDisable();
    renderSecuritySettings();
    showToast("Authenticator removed");
  } catch (err) {
    if (error) { error.textContent = err.message || "Could not remove the authenticator."; error.hidden = false; }
    passwordEl?.select();
  } finally {
    if (button) { button.disabled = false; button.textContent = "Remove authenticator"; }
  }
}

/* ---------- passkey setup ---------- */
function passkeyDeviceProfile() {
  const userAgent = navigator.userAgent || "";
  const os = /Windows/i.test(userAgent) ? "Windows"
    : /Android/i.test(userAgent) ? "Android"
    : /iPhone|iPad|iPod/i.test(userAgent) ? "iOS"
    : /Mac OS X|Macintosh/i.test(userAgent) ? "macOS"
    : /Linux/i.test(userAgent) ? "Linux"
    : "This device";
  const browser = /Edg\//i.test(userAgent) ? "Edge"
    : /Firefox\//i.test(userAgent) ? "Firefox"
    : /Chrome\//i.test(userAgent) ? "Chrome"
    : /Safari\//i.test(userAgent) ? "Safari"
    : "Browser";
  const biometric = os === "Windows" ? "Windows Hello"
    : os === "macOS" ? "Touch ID"
    : os === "iOS" ? "Face ID or Touch ID"
    : os === "Android" ? "your screen lock"
    : "your device screen lock";
  return { os, browser, biometric, label: os === "This device" ? "This device" : `${os} · ${browser}` };
}

function webAuthnErrorMessage(error, action = "create") {
  const name = (error && error.name) || "";
  if (name === "NotAllowedError") {
    return action === "create"
      ? { title: "The passkey prompt was dismissed", message: "Your browser or device cancelled the request, or it timed out. Try again and allow the prompt to use your fingerprint, face, PIN or security key." }
      : { title: "Passkey verification was cancelled", message: "The request timed out or was dismissed. Choose the passkey option again and allow your device to confirm." };
  }
  if (name === "InvalidStateError") {
    return { title: "This passkey is already registered", message: "That device already has a passkey for Alt8Mail. Try a different device, or remove the existing passkey first." };
  }
  if (name === "SecurityError") {
    return { title: "A secure connection is required", message: "Passkeys only work over HTTPS. Open Alt8Mail with a secure address and try again." };
  }
  if (name === "NotSupportedError" || name === "ConstraintError") {
    return { title: "This device can’t create that passkey", message: "The browser or security key doesn’t support the selected option. Try “Security key or phone”, or use a current browser on a device with a screen lock." };
  }
  if (name === "AbortError") {
    return { title: "Passkey request cancelled", message: "Nothing was changed. You can try again whenever you’re ready." };
  }
  return {
    title: action === "create" ? "Couldn’t add the passkey" : "Couldn’t verify the passkey",
    message: (error && error.message) || "Something went wrong. Please try again."
  };
}

async function detectPasskeyCapabilities() {
  const profile = passkeyDeviceProfile();
  const supported = Boolean(window.PublicKeyCredential && navigator.credentials && typeof navigator.credentials.create === "function" && typeof navigator.credentials.get === "function");
  const secure = typeof window.isSecureContext === "boolean" ? window.isSecureContext : location.protocol === "https:";
  let platform = false;
  if (supported) {
    try {
      platform = typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === "function"
        ? await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()
        : false;
    } catch { platform = false; }
  }
  return { supported, secure, platform, profile };
}

function syncPasskeyMethodSelection() {
  $$("#passkeyMethodGrid .passkey-method").forEach((label) => {
    const input = label.querySelector("input");
    label.classList.toggle("is-selected", Boolean(input && input.checked));
    label.classList.toggle("is-disabled", Boolean(input && input.disabled));
  });
}

function updatePasskeySetupCreateState() {
  const create = document.getElementById("passkeySetupCreate");
  if (!create) return;
  create.disabled = !passkeySetupCaps || !passkeySetupCaps.supported || !passkeySetupCaps.secure;
}

function renderPasskeySupport(caps) {
  const support = document.getElementById("passkeySupport");
  const icon = support?.querySelector(".passkey-support-icon");
  const title = document.getElementById("passkeySupportTitle");
  const detail = document.getElementById("passkeySupportDetail");
  const badge = document.getElementById("passkeySupportBadge");
  const platformMethod = document.getElementById("passkeyMethodPlatform");
  const platformInput = platformMethod?.querySelector("input");
  const platformHint = document.getElementById("passkeyPlatformMethodHint");
  const platformBadge = document.getElementById("passkeyPlatformBadge");
  const hint = document.getElementById("passkeySetupActionHint");
  if (!support || !icon || !title || !detail || !badge) return;
  const profile = caps.profile;
  let state = "ready";
  if (!caps.supported) state = "blocked";
  else if (!caps.secure) state = "blocked";
  else if (!caps.platform) state = "partial";
  support.dataset.state = state;
  if (state === "blocked" && !caps.supported) {
    title.textContent = "Passkeys aren’t available in this browser";
    detail.textContent = "Use a current version of Chrome, Edge, Safari or Firefox. This browser can’t create a WebAuthn passkey.";
    badge.textContent = "Unavailable";
    icon.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>';
  } else if (state === "blocked") {
    title.textContent = "A secure connection is required";
    detail.textContent = "Open Alt8Mail over HTTPS (or localhost) to create a passkey. Passkeys never work over an insecure connection.";
    badge.textContent = "HTTPS needed";
    icon.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg>';
  } else if (state === "partial") {
    title.textContent = "Built-in authenticator not detected";
    detail.textContent = `You can still add a security key, phone or tablet. ${profile.os} didn’t report a built-in fingerprint, face or PIN authenticator to this browser.`;
    badge.textContent = "Security key";
    icon.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-key"/></svg>';
  } else {
    title.textContent = `${profile.biometric} is ready`;
    detail.textContent = `${profile.os} can confirm with your fingerprint, face or PIN. Your biometric data stays on your device.`;
    badge.textContent = "Ready";
    icon.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-check"/></svg>';
  }
  const platformUsable = Boolean(caps.supported && caps.secure && caps.platform);
  if (platformInput) {
    platformInput.disabled = !platformUsable;
    if (!platformUsable && platformInput.checked) {
      const cross = document.querySelector('#passkeyMethodGrid input[value="cross-platform"]');
      if (cross) cross.checked = true;
    }
  }
  if (platformHint) platformHint.textContent = platformUsable ? profile.biometric : "Not detected on this device";
  if (platformBadge) {
    platformBadge.textContent = platformUsable ? "Ready" : "Not detected";
    platformBadge.classList.toggle("is-ready", platformUsable);
  }
  syncPasskeyMethodSelection();
  if (hint) {
    hint.textContent = caps.supported && caps.secure
      ? "Your passkey is added to this Alt8Mail account"
      : "Passkeys can’t be created in this browser";
  }
  updatePasskeySetupCreateState();
}

function openPasskeySetup() {
  if (!passkeySetupOverlay) return;
  hideToast();
  const profile = passkeyDeviceProfile();
  passkeySetupCaps = null;
  passkeySetupCheckSeq += 1;
  const checkSeq = passkeySetupCheckSeq;
  passkeySetupAbort = null;
  const dialog = passkeySetupOverlay.querySelector(".passkey-setup-dialog");
  dialog?.classList.remove("is-busy");
  const waiting = document.getElementById("passkeySetupWaiting");
  if (waiting) waiting.hidden = true;
  const error = document.getElementById("passkeySetupError");
  if (error) error.hidden = true;
  const name = document.getElementById("passkeySetupName");
  if (name) name.value = profile.label;
  const support = document.getElementById("passkeySupport");
  if (support) support.dataset.state = "checking";
  const supportIcon = support?.querySelector(".passkey-support-icon");
  if (supportIcon) supportIcon.innerHTML = '<span class="passkey-spinner" aria-hidden="true"></span>';
  const supportTitle = document.getElementById("passkeySupportTitle");
  const supportDetail = document.getElementById("passkeySupportDetail");
  const supportBadge = document.getElementById("passkeySupportBadge");
  if (supportTitle) supportTitle.textContent = "Checking this device…";
  if (supportDetail) supportDetail.textContent = "Looking for a built-in authenticator and a secure connection.";
  if (supportBadge) supportBadge.textContent = "Checking";
  const platformHint = document.getElementById("passkeyPlatformMethodHint");
  if (platformHint) platformHint.textContent = profile.biometric;
  const platformBadge = document.getElementById("passkeyPlatformBadge");
  if (platformBadge) { platformBadge.textContent = "Checking…"; platformBadge.classList.remove("is-ready"); }
  const platformInput = document.querySelector('#passkeyMethodGrid input[value="platform"]');
  if (platformInput) { platformInput.checked = true; platformInput.disabled = true; }
  syncPasskeyMethodSelection();
  const create = document.getElementById("passkeySetupCreate");
  if (create) create.disabled = true;
  const hint = document.getElementById("passkeySetupActionHint");
  if (hint) hint.textContent = "Checking what this device supports…";
  passkeySetupOverlay.hidden = false;
  setTimeout(() => { if (!passkeySetupOverlay.hidden && window.innerWidth > 720 && window.matchMedia("(pointer: fine)").matches) name?.focus(); }, 60);
  detectPasskeyCapabilities().then((caps) => {
    if (checkSeq !== passkeySetupCheckSeq || passkeySetupOverlay.hidden) return;
    passkeySetupCaps = caps;
    renderPasskeySupport(caps);
  }).catch(() => {
    if (checkSeq !== passkeySetupCheckSeq || passkeySetupOverlay.hidden) return;
    passkeySetupCaps = {
      supported: Boolean(window.PublicKeyCredential && navigator.credentials),
      secure: typeof window.isSecureContext === "boolean" ? window.isSecureContext : location.protocol === "https:",
      platform: false,
      profile
    };
    renderPasskeySupport(passkeySetupCaps);
  });
}

function closePasskeySetup() {
  if (!passkeySetupOverlay) return;
  passkeySetupCheckSeq += 1;
  const controller = passkeySetupAbort;
  passkeySetupAbort = null;
  if (controller) { try { controller.abort(); } catch {} }
  passkeySetupOverlay.hidden = true;
  passkeySetupOverlay.querySelector(".passkey-setup-dialog")?.classList.remove("is-busy");
  const waiting = document.getElementById("passkeySetupWaiting");
  if (waiting) waiting.hidden = true;
  passkeySetupCaps = null;
}

async function createPasskeyFromSetup(event) {
  if (event) event.preventDefault();
  if (!passkeySetupOverlay || passkeySetupOverlay.hidden || passkeySetupAbort) return;
  if (!passkeySetupCaps || !passkeySetupCaps.supported || !passkeySetupCaps.secure) return;
  const profile = passkeySetupCaps.profile;
  const nameEl = document.getElementById("passkeySetupName");
  const name = nameEl ? nameEl.value.trim().slice(0, 80) : "";
  const selected = document.querySelector('#passkeyMethodGrid input[name="passkeyAttachment"]:checked');
  let attachment = selected ? selected.value : "cross-platform";
  if (attachment === "platform" && !passkeySetupCaps.platform) attachment = "cross-platform";
  const dialog = passkeySetupOverlay.querySelector(".passkey-setup-dialog");
  const error = document.getElementById("passkeySetupError");
  const waiting = document.getElementById("passkeySetupWaiting");
  const waitingText = document.getElementById("passkeySetupWaitingText");
  const errorTitle = document.getElementById("passkeySetupErrorTitle");
  const errorText = document.getElementById("passkeySetupErrorText");
  if (error) error.hidden = true;
  if (waitingText) {
    waitingText.textContent = attachment === "platform"
      ? `Use ${profile.biometric} to confirm your passkey.`
      : "Insert your security key, or follow the prompt on your phone or tablet.";
  }
  if (waiting) waiting.hidden = false;
  dialog?.classList.add("is-busy");
  const controller = new AbortController();
  passkeySetupAbort = controller;
  try {
    const begin = await api("/api/security/webauthn/register/begin", { method: "POST", body: {} });
    const options = prepareCreationOptions(begin.publicKey);
    options.authenticatorSelection = { ...(options.authenticatorSelection || {}), authenticatorAttachment: attachment };
    const credential = await navigator.credentials.create({ publicKey: options, signal: controller.signal });
    if (!credential) throw new Error("Passkey creation was cancelled");
    const query = new URLSearchParams({ flow: begin.flowId });
    if (name) query.set("name", name);
    const data = await api(`/api/security/webauthn/register/finish?${query.toString()}`, {
      method: "POST", body: serializeWebAuthnCredential(credential)
    });
    passkeySetupAbort = null;
    passkeySetupCheckSeq += 1;
    passkeySetupOverlay.hidden = true;
    dialog?.classList.remove("is-busy");
    if (waiting) waiting.hidden = true;
    state.security = data.security || state.security;
    renderSecuritySettings();
    if (Array.isArray(data.codes) && data.codes.length) showRecoveryCodes(data.codes, "Save these recovery codes now. They are shown only once.");
    else showToast("Passkey added");
  } catch (err) {
    passkeySetupAbort = null;
    dialog?.classList.remove("is-busy");
    if (waiting) waiting.hidden = true;
    if ((err && err.name === "AbortError") || passkeySetupOverlay.hidden) return;
    const friendly = webAuthnErrorMessage(err, "create");
    if (errorTitle) errorTitle.textContent = friendly.title;
    if (errorText) errorText.textContent = friendly.message + (err && err.name ? ` (${err.name})` : "");
    if (error) error.hidden = false;
    updatePasskeySetupCreateState();
  }
}

async function removePasskey(id) {
  if (!(await appConfirm({ title: "Remove this passkey?", message: "You will no longer be able to sign in with this passkey. Other sign-in methods remain available.", confirmLabel: "Remove passkey", tone: "danger" }))) return;
  try {
    const data = await api(`/api/security/webauthn/${encodeURIComponent(id)}`, { method: "DELETE", body: {} });
    state.security = data.security || state.security;
    renderSecuritySettings();
    showToast("Passkey removed");
  } catch (err) { showError(err); }
}

async function toggleEnrollmentPolicy() {
  const toggle = document.getElementById("enrollmentPolicyToggle");
  const next = toggle.getAttribute("aria-checked") !== "true";
  toggle.setAttribute("aria-checked", next ? "true" : "false");
  try {
    await api("/api/security/policy", { method: "PATCH", body: { enrollmentRequired: next } });
    if (state.security && state.security.twoFactor) state.security.twoFactor.enrollmentRequired = next;
    showToast(next ? "Enrollment required at next sign-in" : "First-time enrollment disabled");
  } catch (err) {
    toggle.setAttribute("aria-checked", next ? "false" : "true");
    showError(err);
  }
}

function showRecoveryCodes(codes, note) {
  hideToast();
  const list = document.getElementById("recoveryCodeList");
  if (list) list.innerHTML = codes.map((code) => `<code>${esc(code)}</code>`).join("");
  const title = document.getElementById("recoveryTitle");
  if (title) title.textContent = "Recovery codes";
  recoveryOverlay.hidden = false;
}

async function logout() {
  if (state.delegatedMode) {
    closeDelegatedWindow();
    return;
  }
  if (logoutInProgress) return;
  closeOfficeUiOnSignOut();
  logoutInProgress = true;
  const startedAt = Date.now();
  broadcastPrimarySignOut();
  showLogoutSplash();
  try {
    // Persist the open/minimized compose state before the session is revoked so
    // the next sign-in, on this or another computer, restores it exactly.
    try { await persistComposeSessions(); } catch {}
    try { await unregisterPushSubscription({ silent: true }); } catch {}
    try { await api("/api/session", { method: "DELETE" }); } catch {}
  } finally {
    state.user = null;
    state.organizationName = "";
    state.csrf = null;
    state.messages = [];
    state.mailPages = {};
    state.folderCounts = {};
    state.folderUnread = {};
    state.knownInboxIds = null;
    state.knownSnoozeDueIds = new Set();
    state.knownAccountUnread = new Map();
    state.knownAccountLatest = new Map();
    state.accountPingQueue = [];
    state.accountPingCurrent = null;
    clearTimeout(state.accountPingTimer);
    state.accountPingTimer = null;
    state.push = { enabled: false, publicKey: "", subscribed: false, includeSender: true, includeSubject: true };
    state.pushLocal = false;
    state.pushBusy = false;
    state.pushAutoChecked = false;
    state.pushError = "";
    try { state.calendarRealtime?.close(); } catch {}
    state.calendarRealtime = null;
    try { state.mailRealtime?.close(); } catch {}
    state.mailRealtime = null;
    clearTimeout(state.mailRealtimeTimer);
    state.mailRealtimeTimer = null;
    state.calendarDockDismissed = new Set();
    document.getElementById("calendarProposalDock")?.remove();
    state.people = [];
    state.aliases = [];
    state.sieve = null;
    state.quota = null;
    state.outbound = null;
    state.pendingSends = [];
    state.selectedThreadId = null;
    state.selectedIds.clear();
    state.collapsedMailGroups = new Set();
    state.homeTab = "home";
    state.homeTabsRestored = false;
    state.homeSearchQuery = "";
    state.homeSearchData = null;
    state.homeSearchLoading = false;
    state.pulseData = null;
    state.pulseYear = null;
    state.stickyNotes.clear();
    state.stickyNoteLoading.clear();
    state.stickyNotePromises.clear();
    state.stickyEditorOwner = "";
    state.stickyEditorNoteId = "";
    state.stickyEditorCanEdit = true;
    state.stickyEditorLinks = [];
    state.stickyAttachKind = "";
    state.stickyAttachItems = [];
    state.stickyAttachQuery = "";
    state.stickyAttachLoading = false;
    state.stickyAttachSeq += 1;
    clearTimeout(state.stickyAttachTimer);
    state.notesDeskOwner = "";
    state.notesDeskArchive = false;
    state.notesDeskQuery = "";
    state.notesDeskRemote = null;
    state.notesDeskRemoteQuery = "";
    state.notesDeskRemoteArchive = false;
    state.notesDeskRemoteLoading = false;
    state.notesDeskRemoteSeq += 1;
    state.notesDeskMailboxes = [];
    state.notesDeskCanEdit = true;
    state.notesDeskTeamCount = 0;
    clearTimeout(state.notesDeskTimer);
    state.noteSearchResults = [];
    state.noteSearchQuery = "";
    state.noteSearchLoading = false;
    state.noteSearchSeq += 1;
    clearInterval(state.uploadMobilePoll);
    state.uploadMobilePoll = null;
    state.uploadManagerOpen = false;
    state.uploadManagerMinimized = false;
    state.uploadQueue = [];
    state.uploadWorkerBusy = false;
    state.uploadMobileSession = null;
    state.uploadMobileSeen = new Map();
    state.uploadMobileQrData = "";
    state.uploadMobileQrSession = "";
    state.uploadUrlValue = "";
    const uploadManager = document.getElementById("uploadManager");
    if (uploadManager) uploadManager.hidden = true;
    try {
      sessionStorage.removeItem(HOME_TABS_KEY);
      Object.keys(sessionStorage).filter((key) => key.startsWith("a8m.sticky.")).forEach((key) => sessionStorage.removeItem(key));
    } catch {}
    rebuildIndex();
    clearThemeAccentForLogout();
    if (window.location.hash) window.history.replaceState(null, "", window.location.pathname + window.location.search);
    const remaining = LOGOUT_SPLASH_MS - (Date.now() - startedAt);
    if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
    showLogin();
    logoutInProgress = false;
  }
}

async function loadBootstrap({ restoreDrafts = false, quiet = false } = {}) {
  const params = new URLSearchParams({
    folder: state.folder || "inbox",
    filter: state.filter || "all",
    limit: "50"
  });
  const data = await api(`/api/bootstrap?${params.toString()}`);
  applyBootstrap(data, { restoreDrafts, quiet });
  if (!quiet) statusMid.textContent = "Synced just now";
}

function applyBootstrap(data, { restoreDrafts = false, quiet = false } = {}) {
  const previousThread = state.selectedThreadId;
  const firstUserLoad = !state.user;
  state.user = data.user;
  state.organizationName = data.organizationName || "";
  state.delegatedMailboxes = Array.isArray(data.delegatedMailboxes) ? data.delegatedMailboxes : [];
  if (data.sessionKind === "delegated" || data.delegated === true) {
    state.delegatedMode = true;
    if (!state.delegatedSession) {
      state.delegatedSession = { token: "", csrf: data.csrf || state.csrf || "", mailbox: { email: data.user?.email || "" }, canSend: data.delegatedCanSend !== false };
    } else {
      state.delegatedSession.canSend = data.delegatedCanSend !== false;
    }
  }
  if (firstUserLoad) {
    restoreHomeTabsState();
  }
  state.mailboxMode = data.mailboxMode || "demo";
  state.mailSyncError = String((data.mailSync && data.mailSync.lastError) || "").trim();
  state.accounts = Array.isArray(data.accounts) ? data.accounts : [];
  state.activeAccount = data.activeAccount || state.accounts.find((account) => account.id === data.activeAccountId) || null;
  state.activeAccountId = data.activeAccountId || state.activeAccount?.id || "";
  hydrateAccountUnreadCounts();
  const nativeAliases = data.aliases || [];
  const connectedAliases = [];
  const aliasEmails = new Set(nativeAliases.map((alias) => normalizeEmail(alias.email)));
  for (const account of state.accounts) {
    if (account.isNative || account.status === "disabled") continue;
    const email = normalizeEmail(account.email);
    if (!email || aliasEmails.has(email)) continue;
    aliasEmails.add(email);
    connectedAliases.push({
      id: `account:${account.id}`,
      email: account.email,
      label: account.displayName || account.email,
      kind: "connected",
      canSend: account.status === "active",
      status: "verified",
      source: "account",
      accountId: account.id
    });
  }
  state.aliases = [...nativeAliases, ...connectedAliases];
  state.identities = data.identities || state.identities || [];
  state.signatures = data.signatures || state.signatures || [];
  state.labels = data.labels || state.labels || [];
  state.ai = data.ai || { enabled: false };
  applyThreadMeta(data.threadMeta || []);
  state.serverNotifications = data.serverNotifications || [];
  applyUnsubscribeActions(data.unsubscribeActions || []);
  startNotificationRefresh();
  state.push = data.push || state.push || { enabled: false, publicKey: "", subscribed: false };
  state.mailClient = data.mailClient || state.mailClient || null;
  state.recentAudit = data.recentAudit || [];
  renderMailClientSetup();
  if (firstUserLoad) loadDismissedNotifications();
  state.folders = data.folders || [];
  ensureSubscriptionsFolder();
  ensurePhase3SettingsUi();
  state.people = data.people || [];
  state.messages = data.messages || [];
  state.mailPages = {};
  state.folderCounts = data.folderCounts || {};
  state.folderUnread = data.folderUnread || {};
  if (data.mailPage && data.mailPage.folder) {
    const key = mailPageKey(data.mailPage.folder, data.mailPage.filter || "all");
    const limit = Number(data.mailPage.limit) || 50;
    state.mailPages[key] = {
      ...data.mailPage,
      limit,
      loaded: true,
      loading: false,
      nextOffset: (Number(data.mailPage.offset) || 0) + limit
    };
  } else {
    // The standalone Node reference template predates server-side paging and
    // returns the complete mailbox document. Treat that response as one page.
    const key = mailPageKey(state.folder, "all");
    const total = state.messages.filter((message) => state.folder === "starred"
      ? message.starred && message.folder !== "spam" && message.folder !== "trash"
      : state.folder === "subscriptions" ? message.folder === "subscriptions" && !message.delegateOwnerId
      : message.folder === state.folder).length;
    state.mailPages[key] = {
      folder: state.folder, filter: "all", offset: 0, limit: Math.max(total, 50),
      total, totalMessages: total, hasMore: false, loaded: true, loading: false, nextOffset: Math.max(total, 50)
    };
  }
  state.calendarEvents = data.calendarEvents || [];
  state.capabilities = data.capabilities || [];
  state.calendars = data.calendars || [];
  state.calendarSubscriptions = data.calendarSubscriptions || [];
  renderCalendarProposalDock();
  state.addressBooks = data.addressBooks || [];
  state.fileFolders = data.fileFolders || [];
  if (data.storageQuota) state.storageQuota = data.storageQuota;
  if (state.calendars.length && !state.calendars.some((calendar) => calendar.id === state.calendarActiveId)) {
    state.calendarActiveId = state.calendars.find((calendar) => calendar.isDefault)?.id || state.calendars[0].id;
  }
  state.sieve = data.sieve || null;
  state.quota = data.quota || null;
  state.outbound = data.outbound || null;
  state.pendingSends = data.pendingSends || [];
  state.tasks = data.tasks || [];
  state.files = data.files || [];
  state.storageProviders = data.storageProviders || [];
  state.defaultStorage = data.defaultStorage || state.defaultStorage || "a8m";
  state.tenantPolicy = data.tenantPolicy || null;
  if (state.activeAccountId === "all" && !unifiedAccountsAvailable()) {
    const native = nativeMailAccount();
    if (native) {
      state.activeAccountId = native.id;
      state.activeAccount = native;
      try { localStorage.setItem(activeAccountStorageKey(), native.id); } catch {}
    }
  }
  ensureStickySettingsUi();
  const stickyNewMenu = document.querySelector('[data-new="sticky"]');
  if (stickyNewMenu) stickyNewMenu.hidden = !tenantFeatureEnabled("stickyNotes");
  if (firstUserLoad) ensureStickyNote(stickyNoteOwnerId());
  state.attachmentMaxBytes = data.attachmentMaxBytes || 8 * 1024 * 1024;
  state.preferences = { ...DEFAULT_PREFERENCES, ...(data.user && data.user.preferences ? data.user.preferences : {}) };
  state.security = data.user && data.user.security ? data.user.security : null;
  state.csrf = data.csrf || state.csrf;
  applyServerPreferences();
  if (!state.folders.some((folder) => folder.id === state.folder)) state.folder = "inbox";
  if (!state.contactEmail && state.people.length) state.contactEmail = state.people[0].email;
  applyPreferenceChrome();
  rebuildIndex();
  renderAccountChrome();
  renderAccountSwitcher();
  renderConnectedAccounts();
  applyConnectedAccountSettingsScope();
  if (firstUserLoad && !state.accountRestoreAttempted && !state.delegatedMode) {
    state.accountRestoreAttempted = true;
    let stored = "";
    let requestedAccount = "";
    try {
      const params = new URLSearchParams(location.search);
      requestedAccount = String(params.get("account") || "").trim();
      if (requestedAccount) {
        params.delete("account");
        const query = params.toString();
        history.replaceState({}, "", `${location.pathname}${query ? `?${query}` : ""}${location.hash || ""}`);
      }
      stored = localStorage.getItem(activeAccountStorageKey()) || "";
    } catch {}
    if (requestedAccount) stored = requestedAccount;
    const validAccount = (id) => id === "all"
      ? unifiedAccountsAvailable()
      : state.accounts.some((account) => account.id === id && (account.isNative || externalAccountsEnabled()));
    if (stored && stored !== state.activeAccountId && validAccount(stored)) {
      state.activeAccountId = stored;
      state.activeAccount = stored === "all"
        ? unifiedAccountView()
        : (state.accounts.find((account) => account.id === stored) || state.activeAccount);
      try { localStorage.setItem(activeAccountStorageKey(), stored); } catch {}
      setTimeout(() => loadBootstrap({ quiet: true }).catch(() => {}), 0);
    }
  }
  ensureDelegatedMailboxUi();
  renderDelegatedWindowChrome();
  startDelegatedHeartbeat();
  ensureAddonsSettingsUi();
  if (!state.delegatedMode) loadAddons({ silent: !state.addonsLoaded }).catch(() => {});
  if (!state.delegatedMode) loadOfficeConfig({ silent: true }).catch(() => {});
  if (firstUserLoad && !state.delegatedMode) restoreOfficeDockFromStorage();
  renderFolders();
  renderList();
  renderNotifications();
  updateAiReaderUi();
  syncSelectionUi();
  updateQuotaUi();
  updateOutboundUi();
  updatePendingUi();
  updateScheduledUi();
  startOutboxPolling();
  startCalendarRealtime();
  syncPreferencesUi();
  renderSignatureLibrary();
  if (["account", "security", "regional", "autoreply", "storage"].includes(state.settingsTab)) renderSettingsDynamic();
  if (state.task === "settings" && ["rules", "audit"].includes(state.settingsTab)) renderSettingsDynamic();
  if (!quiet && previousThread && !threadById(previousThread)) state.selectedThreadId = null;
  renderReader();
  if (state.task === "tasks") renderTasks();
  if (state.task === "people") renderPeople();
  if (state.task === "files") renderFiles();
  const inboxIds = state.messages.filter((message) => message.folder === "inbox").map((message) => message.id);
  if (!state.knownInboxIds) {
    // If the initial page was not INBOX, leave this unknown so the first
    // background poll can seed it without firing a burst of false notifications.
    state.knownInboxIds = state.mailPages[mailPageKey("inbox", "all")] ? new Set(inboxIds) : null;
  } else {
    inboxIds.forEach((id) => state.knownInboxIds.add(id));
  }
  startMailMonitor();
  startMailRealtime();
  syncPushUi();
  if (firstUserLoad) maybeAutoRegisterPush();
  const dataAction = document.getElementById("resetData");
  const dataNote = document.querySelector(".about-actions .about-note");
  if (dataAction && state.mailboxMode === "imap") {
    dataAction.classList.remove("danger-btn");
    dataAction.innerHTML = '<svg class="icon" aria-hidden="true"><use href="#i-refresh"/></svg>Resync from Dovecot';
    if (dataNote) dataNote.textContent = "Live Dovecot mailbox · IMAP sync and Postfix submission are enabled.";
  }
  syncStatusRange();
  syncStatusContext();
  syncCommandBar();
  if (restoreDrafts) restoreDraftSessions();
  state.knownPendingIds = new Set(state.pendingSends.map((item) => item.id));
  const onboardingShown = maybeShowOnboarding();
  if (!onboardingShown) maybeShowPasswordChange();
  updateDocumentTitle();
}

function applyPreferenceChrome() {
  const language = state.preferences.language || "en-US";
  document.documentElement.lang = language;
  const zoneHint = document.getElementById("timeZoneHint");
  if (zoneHint) zoneHint.textContent = `All timestamps and scheduled sends use ${formatTimeZoneLabel()}.`;
}

function startMailMonitor() {
  if (state.mailMonitorTimer) return;
  state.mailMonitorTimer = setInterval(() => {
    pollNewMail().catch(() => {});
    pollAccountSummaries().catch(() => {});
    checkCalendarReminders().catch(() => {});
  }, 15000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      pollNewMail().catch(() => {});
      pollAccountSummaries().catch(() => {});
    }
  });
  startMailRealtime();
  pollNewMail().catch(() => {});
  pollAccountSummaries().catch(() => {});
}

function startMailRealtime() {
  if (state.mailRealtime || state.delegatedMode || typeof EventSource === "undefined" ||
      !(state.capabilities || []).includes("mail-realtime")) return;
  try {
    const source = new EventSource("/api/mail/stream");
    state.mailRealtime = source;
    source.addEventListener("mail", () => {
      clearTimeout(state.mailRealtimeTimer);
      state.mailRealtimeTimer = setTimeout(() => {
        state.mailRealtimeTimer = null;
        pollNewMail().catch(() => {});
        pollAccountSummaries().catch(() => {});
      }, 250);
    });
  } catch {}
}

async function pollNewMail() {
  if (!state.user) return;
  const data = await api("/api/messages?folder=inbox");
  if (!state.knownInboxIds) {
    state.knownInboxIds = new Set((data.messages || []).map((message) => message.id));
    return;
  }
  const known = state.knownInboxIds;
  const incoming = data.messages || [];
  const recentCutoff = Date.now() - 10 * 60 * 1000;
  const fresh = incoming.filter((message) =>
    !known.has(message.id) && (Date.parse(message.date) || 0) > recentCutoff
  );
  // A paged response can include older siblings of a newly loaded thread. Mark
  // every returned id as seen; only recent unseen messages trigger a toast.
  incoming.forEach((message) => known.add(message.id));
  state.knownInboxIds = known;
  const dueNow = incoming.filter((message) => message.unread && message.snoozedUntil && (Date.parse(message.snoozedUntil) || 0) <= Date.now());
  const dueIds = new Set(dueNow.map((message) => message.id));
  const freshDue = dueNow.filter((message) => !state.knownSnoozeDueIds.has(message.id));
  state.knownSnoozeDueIds = dueIds;
  if (freshDue.length && !fresh.length) {
    await refreshMailbox({ quiet: true });
    renderNotifications();
  }
  if (!fresh.length) return;
  showNewMailNotification(fresh[0], fresh.length);
  await refreshMailbox({ quiet: true });
  renderNotifications();
}

async function pollAccountSummaries() {
  if (!state.user || state.delegatedMode || !externalAccountsEnabled()) return;
  if (!(state.accounts || []).some((account) => !account.isNative)) return;
  const data = await api("/api/accounts/summary");
  for (const summary of data.accounts || []) {
    const account = (state.accounts || []).find((item) => item.id === summary.id);
    if (!account) continue;
    const next = Math.max(0, Number(summary.unreadCount) || 0);
    const previous = state.knownAccountUnread.get(account.id);
    const latestId = summary.latestUnread?.id || "";
    const knownLatest = state.knownAccountLatest.get(account.id) || "";
    const grew = previous !== undefined && next > previous;
    const changedLatest = next > 0 && Boolean(knownLatest) && Boolean(latestId) &&
      latestId !== knownLatest && next >= (previous ?? 0);
    account.unreadCount = next;
    if (summary.latestUnread) account.latestUnread = summary.latestUnread;
    if (grew || changedLatest) {
      maybeQueueAccountPing(account, Math.max(1, next - (previous ?? 0)), summary.latestUnread);
    }
    state.knownAccountUnread.set(account.id, next);
    state.knownAccountLatest.set(account.id, latestId);
  }
  if (state.activeAccount) {
    if (state.activeAccount.isUnified) {
      state.activeAccount.unreadCount = accountUnreadTotal();
    } else {
      const live = (state.accounts || []).find((item) => item.id === state.activeAccount.id);
      if (live) state.activeAccount.unreadCount = live.unreadCount;
    }
  }
  renderAccountSwitcher();
}

function showBrowserNotification(title, body, tag = "a8m-new-mail") {
  if (!state.notifyDesktop || !("Notification" in window) || Notification.permission !== "granted") return false;
  try {
    const notification = new Notification(title, { body, tag, icon: "/icons/icon-192.png", badge: "/icons/icon-192.png" });
    notification.onclick = () => { window.focus(); notification.close(); };
    return true;
  } catch { return false; }
}

function playNotificationTone() {
  try {
    const AudioCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtor) return;
    const context = new AudioCtor();
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = "sine";
    oscillator.frequency.setValueAtTime(880, context.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(660, context.currentTime + 0.16);
    gain.gain.setValueAtTime(0.0001, context.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.08, context.currentTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + 0.22);
    oscillator.connect(gain).connect(context.destination);
    oscillator.start();
    oscillator.stop(context.currentTime + 0.24);
    oscillator.onended = () => context.close();
  } catch {}
}

function showNewMailNotification(message, count) {
  const subject = message.subject || "(no subject)";
  const sender = message.from ? (message.from.name || message.from.email) : "New sender";
  const body = count > 1 ? `${count} new messages · ${sender}: ${subject}` : `${sender}: ${subject}`;
  if (state.notifySound) playNotificationTone();
  if (!showBrowserNotification(t("notify.newMail"), body, "a8m-new-mail")) {
    showToast(`New mail from ${sender}: ${subject}`, "Open", () => { setTask("mail"); setFolder("inbox"); });
  }
}

/* ============================================================
   background push notifications
   ============================================================ */
function pushSupported() {
  return Boolean(window.isSecureContext) && "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
}

function pushKeyBytes(base64String) {
  const value = String(base64String || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = value + "=".repeat((4 - (value.length % 4)) % 4);
  const raw = atob(padded);
  return Uint8Array.from(raw, (character) => character.charCodeAt(0));
}

async function pushServiceWorker() {
  if (!pushSupported()) return null;
  return Promise.race([
    navigator.serviceWorker.ready,
    new Promise((_, reject) => setTimeout(() => reject(new Error("The service worker is not ready")), 8000))
  ]);
}

function pushSubscriptionMatchesKey(subscription) {
  try {
    const existing = subscription.options && subscription.options.applicationServerKey;
    if (!existing) return false;
    const current = pushKeyBytes(state.push && state.push.publicKey);
    const installed = new Uint8Array(existing);
    if (installed.length !== current.length) return false;
    return installed.every((byte, index) => byte === current[index]);
  } catch {
    return false;
  }
}

async function refreshPushLocalState() {
  let local = false;
  if (pushSupported() && state.push && state.push.enabled) {
    try {
      const registration = await pushServiceWorker();
      const subscription = registration ? await registration.pushManager.getSubscription() : null;
      local = Boolean(subscription && pushSubscriptionMatchesKey(subscription));
    } catch {}
  }
  state.pushLocal = local;
  syncPushUi();
  return local;
}

function syncPushUi() {
  const enableButton = document.getElementById("pushEnableBtn");
  if (!enableButton) return;
  const testButton = document.getElementById("pushTestBtn");
  const disableButton = document.getElementById("pushDisableBtn");
  const statusText = document.getElementById("pushStatusText");
  const statusBadge = document.getElementById("pushStatusBadge");
  const hint = document.getElementById("pushHint");
  const config = state.push || {};
  const supported = pushSupported();
  const configured = supported && Boolean(config.enabled && config.publicKey);
  const permission = "Notification" in window ? Notification.permission : "denied";
  const active = configured && Boolean(state.pushLocal);
  let status = "Checking this browser…";
  let badge = "Checking";
  let note = "Alerts arrive through your operating system, so they still appear when the Alt8Mail tab is closed.";
  if (!supported) {
    status = window.isSecureContext
      ? "This browser does not support background push notifications."
      : "Background push requires HTTPS with a valid certificate.";
    badge = "Unsupported";
    note = window.isSecureContext
      ? "Install Alt8Mail as an app or use a browser with Service Worker and Push API support."
      : "Open Alt8Mail over HTTPS, then reload this page.";
  } else if (!configured) {
    status = "Browser push is not enabled by your organization.";
    badge = "Off";
    note = "In-app notifications and sounds continue to work while Alt8Mail is open.";
  } else if (permission === "denied") {
    status = "Notifications are blocked for this site in your browser settings.";
    badge = "Blocked";
    note = "Allow notifications for this site, then reload Alt8Mail to enable background delivery.";
  } else if (active) {
    status = "Active on this browser. Alerts arrive even when the tab is closed.";
    badge = "Active";
    note = config.includeSender !== false || config.includeSubject !== false
      ? "Notifications can include the sender and subject, according to your organization’s push settings."
      : "Your organization hides sender and subject details in push notifications.";
  } else {
    status = "Available. Enable background delivery on this device.";
    badge = "Available";
  }
  if (state.pushError) {
    status = state.pushError;
    badge = "Issue";
    note = "Fix the browser or server condition above, then try again.";
  }
  if (statusText) statusText.textContent = status;
  if (statusBadge) statusBadge.textContent = badge;
  if (hint) hint.textContent = note;
  enableButton.hidden = active;
  enableButton.disabled = !configured || permission === "denied" || state.pushBusy;
  enableButton.textContent = state.pushBusy ? "Enabling…" : "Enable on this device";
  if (testButton) {
    testButton.hidden = !active;
    testButton.disabled = state.pushBusy;
  }
  if (disableButton) {
    disableButton.hidden = !active;
    disableButton.disabled = state.pushBusy;
  }
}

async function maybeAutoRegisterPush() {
  if (state.pushAutoChecked) return;
  state.pushAutoChecked = true;
  if (!pushSupported() || !state.notifyDesktop) return;
  if (!state.push || !state.push.enabled || !state.push.publicKey) return;
  if (Notification.permission !== "granted") return;
  await registerPushSubscription({ quiet: true });
}

function pushErrorMessage(error) {
  const code = error && error.code;
  if (code === "PUSH_OWNED") return "This browser is already registered to another Alt8Mail account. Disable push in that account, then try again.";
  if (code === "PUSH_DISABLED") return "Browser push is no longer enabled by your organization.";
  if (code === "PUSH_KEY") return "The server’s push signing key is unavailable. Ask an administrator to check Web push in System Control.";
  if (code === "PUSH_NO_SUBSCRIPTION") return "The server has no subscription for this browser yet. Enable background delivery again.";
  if (code === "PUSH_DELIVERY") return error.message || "The browser push gateway rejected the notification.";
  if (error && error.name === "NotAllowedError") return "Notifications are blocked for this site in your browser settings.";
  if (error && error.message) return error.message;
  return "Background notifications could not be enabled on this device.";
}

async function registerPushSubscription({ prompt = false, quiet = false, manageBusy = true } = {}) {
  if (!pushSupported()) {
    if (!quiet) showToast("This browser does not support background push notifications");
    syncPushUi();
    return false;
  }
  const config = state.push || {};
  if (!config.enabled || !config.publicKey) {
    state.pushError = "Browser push is not enabled by your organization.";
    if (!quiet) showToast("Browser push is not enabled by your organization");
    syncPushUi();
    return false;
  }
  if (manageBusy) {
    if (state.pushBusy) return false;
    state.pushBusy = true;
    syncPushUi();
  }
  try {
    let permission = Notification.permission;
    if (permission === "default" && prompt) permission = await Notification.requestPermission();
    if (permission !== "granted") {
      state.pushError = "Notifications are blocked for this site in your browser settings.";
      if (!quiet) showToast("Allow notifications in your browser to enable background alerts");
      return false;
    }
    const registration = await pushServiceWorker();
    if (!registration) throw new Error("The service worker is not ready");
    let subscription = await registration.pushManager.getSubscription();
    if (subscription && !pushSubscriptionMatchesKey(subscription)) {
      try { await subscription.unsubscribe(); } catch {}
      subscription = null;
    }
    if (!subscription) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: pushKeyBytes(config.publicKey)
      });
    }
    const submit = () => api("/api/push/subscribe", { method: "POST", body: subscription.toJSON() });
    try {
      await submit();
    } catch (error) {
      if (!error || error.code !== "PUSH_OWNED") throw error;
      // The push service endpoint is still tied to a previous Alt8Mail account.
      // Drop it and obtain a fresh endpoint before retrying once.
      try { await subscription.unsubscribe(); } catch {}
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: pushKeyBytes(config.publicKey)
      });
      await submit();
    }
    state.pushError = "";
    state.pushLocal = true;
    state.push = { ...config, subscribed: true };
    if (!quiet) showToast("Background notifications enabled on this device");
    return true;
  } catch (error) {
    state.pushLocal = false;
    state.pushError = pushErrorMessage(error);
    if (!quiet) showError(error);
    return false;
  } finally {
    if (manageBusy) {
      state.pushBusy = false;
      syncPushUi();
    }
  }
}

async function unregisterPushSubscription({ silent = false } = {}) {
  if (!pushSupported()) {
    state.pushLocal = false;
    syncPushUi();
    return false;
  }
  try {
    const registration = await pushServiceWorker();
    const subscription = registration ? await registration.pushManager.getSubscription() : null;
    if (subscription) {
      await api("/api/push/subscribe", { method: "DELETE", body: { endpoint: subscription.endpoint } }).catch(() => {});
      await subscription.unsubscribe().catch(() => {});
    }
    state.pushLocal = false;
    state.pushError = "";
    if (state.push) state.push = { ...state.push, subscribed: false };
    if (!silent) showToast("Background notifications disabled on this device");
    return true;
  } catch (error) {
    if (!silent) showError(error);
    return false;
  } finally {
    syncPushUi();
  }
}

async function sendPushTestNotification() {
  if (state.pushBusy) return;
  state.pushBusy = true;
  state.pushError = "";
  syncPushUi();
  try {
    // Make sure the server still has this browser's current endpoint. The
    // subscription can be rotated or removed while the page stays open.
    if (state.pushLocal) {
      const registered = await registerPushSubscription({ quiet: true, manageBusy: false });
      if (!registered) {
        showToast(state.pushError || "This browser is no longer registered for push");
        return;
      }
    }
    const result = await api("/api/push/test", { method: "POST" });
    const sent = Number(result && result.sent) || 0;
    const failed = Number(result && result.failed) || 0;
    const lastError = result && result.lastError ? String(result.lastError) : "";
    if (sent > 0) {
      const extra = failed > 0 ? ` ${failed} other browser${failed === 1 ? "" : "s"} failed.` : "";
      showToast(`Test notification sent to ${sent} browser${sent === 1 ? "" : "s"}.${extra}`);
    } else {
      state.pushError = lastError
        ? `The push gateway rejected the test: ${lastError}`
        : "No subscribed browser was available for the test";
      showToast(state.pushError);
    }
  } catch (error) {
    state.pushError = pushErrorMessage(error);
    showError(error);
  } finally {
    state.pushBusy = false;
    syncPushUi();
  }
}

async function refreshPushConfig() {
  if (!state.user) return;
  try {
    const data = await api("/api/push/config");
    if (data) state.push = { ...(state.push || {}), ...data };
    await refreshPushLocalState();
    if (data && data.enabled && state.notifyDesktop && pushSupported() && !data.subscribed && Notification.permission === "granted") {
      registerPushSubscription({ quiet: true }).catch(() => {});
    }
  } catch {}
}

async function checkCalendarReminders() {
  if (!state.notifyCalendar || document.visibilityState !== "visible") return;
  const now = Date.now();
  const today = dateKey(new Date());
  const tomorrow = addDaysToKey(today, 1);
  for (const event of calendarOccurrences(today, tomorrow, { all: true })) {
    if (event.allDay || event.status === "cancelled" || event.myStatus === "declined") continue;
    const minutes = Number.isFinite(Number(event.reminderMinutes)) ? Number(event.reminderMinutes) : 15;
    if (minutes <= 0) continue;
    const key = `${event.id}|${event.occurrenceDate}|${minutes}`;
    if (state.remindedEventIds.has(key)) continue;
    const start = zonedWallTimeToUtc(event.occurrenceDate, event.start);
    if (!start) continue;
    const diff = start.getTime() - now;
    if (diff <= 0 || diff > minutes * 60 * 1000) continue;
    state.remindedEventIds.add(key);
    const label = minutes >= 60 && minutes % 60 === 0 ? `${minutes / 60} hour${minutes === 60 ? "" : "s"}` : `${minutes} minutes`;
    const body = `${event.start} · ${event.where || "Calendar"}`;
    if (!showBrowserNotification(`Event in ${label}`, `${event.title} — ${body}`, "a8m-calendar-" + key)) {
      showToast(`Starting in ${label}: ${event.title} · ${body}`);
    }
  }
}

async function refreshMailbox({ quiet = true } = {}) {
  const params = new URLSearchParams({
    folder: state.folder || "inbox",
    filter: state.filter || "all",
    limit: "50"
  });
  const data = await api(`/api/bootstrap?${params.toString()}`);
  applyBootstrap(data, { restoreDrafts: false });
  if (!quiet) showToast("Mailbox is up to date");
}

/* ============================================================
   derived data
   ============================================================ */
function rebuildIndex() {
  state.index = new MailIndex(state.messages);
}

function mailPageKey(folder = state.folder, filter = state.filter) {
  return `${folder}\u0000${filter}`;
}

function currentMailPage() {
  return state.mailPages[mailPageKey()] || null;
}

function mergeMailMessages(messages) {
  if (!messages || !messages.length) return;
  const byId = new Map(state.messages.map((message) => [message.id, message]));
  for (const message of messages) {
    if (message && message.id) byId.set(message.id, message);
  }
  state.messages = Array.from(byId.values());
  rebuildIndex();
}

function loadMailPage(folder = state.folder, filter = state.filter) {
  const key = mailPageKey(folder, filter);
  const existing = state.mailPages[key];
  if (existing?.loading && existing.promise) return existing.promise;
  if (existing?.loaded && !existing.hasMore) return Promise.resolve(existing);
  const offset = existing?.loaded ? existing.nextOffset : 0;
  const token = (existing?.token || 0) + 1;
  const record = {
    ...(existing || {}), folder, filter, token, loading: true, promise: null
  };
  state.mailPages[key] = record;
  const params = new URLSearchParams({
    folder, filter, limit: "50", offset: String(offset || 0)
  });
  const promise = api(`/api/messages?${params.toString()}`).then((data) => {
    const current = state.mailPages[key];
    if (!current || current.token !== token) return null;
    mergeMailMessages(data.messages || []);
    const limit = Number(data.limit) || 50;
    const total = Number.isFinite(Number(data.total)) ? Number(data.total) : (data.messages || []).length;
    const totalMessages = Number.isFinite(Number(data.totalMessages)) ? Number(data.totalMessages) : total;
    const page = {
      folder, filter, loaded: true, loading: false, token,
      limit, total, totalMessages, hasMore: Boolean(data.hasMore),
      nextOffset: offset + limit
    };
    state.mailPages[key] = page;
    if (data.folderCounts) state.folderCounts = { ...state.folderCounts, ...data.folderCounts };
    if (data.folderUnread) state.folderUnread = { ...state.folderUnread, ...data.folderUnread };
    return data;
  }).catch((error) => {
    const current = state.mailPages[key];
    if (current?.token === token) current.loading = false;
    throw error;
  });
  record.promise = promise;
  return promise;
}

function loadMoreMailPage() {
  const page = currentMailPage();
  if (!page || page.loading || !page.hasMore) return Promise.resolve();
  return loadMailPage(state.folder, state.filter)
    .then((data) => {
      if (!data) return;
      renderList({ preserveScroll: true, appendOnly: true });
      renderFolders();
      syncSelectionUi();
      syncCommandBar();
    })
    .catch((error) => {
      showToast(error.message || "Could not load more messages", "error");
    });
}

function adjustFolderUnread(folderId, delta) {
  if (!folderId || !delta) return;
  const current = Number(state.folderUnread[folderId] || 0);
  state.folderUnread[folderId] = Math.max(0, current + delta);
  updateDocumentTitle();
}

function adjustSubscriptionUnread(message, delta) {
  if (!message?.unsubscribe) return;
  adjustFolderUnread("subscriptions", delta);
}

function messageById(messageId) {
  return state.messages.find((message) => message.id === messageId) || null;
}

function selectionIdForMessage(message) {
  if (!message) return null;
  return inboxViewIndividual() ? message.id : (message.threadId || message.id);
}

// The URL must always carry the opaque conversation ID, even when the Inbox
// is showing individual messages. In individual view the selected row is a
// message ID, so translate it back to its thread before writing the hash.
function threadUrlIdForSelection(selectionId = state.selectedThreadId) {
  const selection = String(selectionId || "");
  if (!selection) return "";
  const message = messageById(selection);
  if (message && message.threadId) return message.threadId;
  const thread = viewThreadById(selection) || threadById(selection);
  return (thread && (thread.latest?.threadId || thread.id)) || "";
}

// Resolve a hash/deep-link target into the ID used by the current view. Grouped
// view selects threads; individual view selects messages but keeps thread IDs
// in the address bar.
function selectionIdForRoute(target) {
  const canonical = canonicalThreadId(target);
  const message = messageById(target) || messageById(canonical);
  if (message) return inboxViewIndividual() ? message.id : selectionIdForMessage(message);
  const thread = threadById(canonical);
  return thread ? thread.id : canonical;
}

function viewThreadById(threadId) {
  if (!threadId) return null;
  return state.viewThreads.find((thread) => thread.id === threadId) || null;
}

function threadById(threadId) {
  if (!threadId) return null;
  if (inboxViewIndividual()) {
    const direct = state.messages.find((message) => message.id === threadId);
    if (direct) return individualThreadFor(direct);
    const siblings = state.messages
      .filter((message) => (message.threadId || message.id) === threadId)
      .sort((a, b) => (Date.parse(a.date) || 0) - (Date.parse(b.date) || 0));
    if (siblings.length) return individualThreadFor(siblings[siblings.length - 1]);
  }
  return buildThreads(
    state.messages.filter((message) => (message.threadId || message.id) === threadId),
    state.messages
  )[0] || null;
}

async function ensureThreadLoaded(target) {
  if (!target) return false;
  if (threadById(target) || messageById(target)) return true;
  try {
    const data = await api(`/api/messages?thread=${encodeURIComponent(target)}`);
    mergeMailMessages(data.messages || []);
    const canonical = String(data.thread || "").trim();
    if (canonical && canonical !== target) threadIdAliases.set(String(target), canonical);
    renderList();
    return Boolean(threadById(target) || messageById(target) || (canonical && threadById(canonical)));
  } catch {
    return false;
  }
}

function canonicalThreadId(id) {
  const key = String(id || "");
  return threadIdAliases.get(key) || key;
}

function folderDef(folderId) {
  return state.folders.find((folder) => folder.id === folderId) || { id: folderId, label: FOLDER_LABELS[folderId] || folderId, icon: "i-folder" };
}

function ensureSubscriptionsFolder() {
  if (!Array.isArray(state.folders)) state.folders = [];
  if (state.activeAccount && state.activeAccount.kind === "external") return;
  if (state.folders.some((folder) => folder.id === "subscriptions")) return;
  state.folders.push({
    id: "subscriptions", label: "Subscriptions", icon: "i-mail", section: "favorites",
    order: 2, badgeMode: "unread", system: true, virtual: true,
    description: "Newsletters and mailing lists with a one-click unsubscribe option."
  });
}

function applyUnsubscribeActions(list) {
  state.unsubscribeActions = new Map();
  for (const action of Array.isArray(list) ? list : []) {
    const sender = normalizeEmail(action?.senderEmail);
    if (sender) state.unsubscribeActions.set(sender, action);
  }
}

function unsubscribeActionFor(message) {
  return state.unsubscribeActions.get(normalizeEmail(message?.from?.email || message?.fromEmail)) || null;
}

function readingTimeForMessage(message) {
  const fromServer = Number(message?.readingMinutes);
  if (Number.isFinite(fromServer) && fromServer >= 0) return Math.round(fromServer);
  const text = message?.bodyText || stripHtml(message?.bodyHtml || "");
  const words = (String(text).trim().match(/\S+/g) || []).length;
  return words ? Math.max(1, Math.ceil(words / 220)) : 0;
}

function readingTimeLabel(minutes) {
  const value = Number(minutes) || 0;
  if (value <= 0) return "";
  return value === 1 ? "1 min read" : `${value} min read`;
}

function threadReadingMinutes(thread) {
  return (thread?.messages || []).reduce((sum, message) => sum + readingTimeForMessage(message), 0);
}

const REACTION_QUICK = ["👍", "❤️", "😂", "🎉", "👀", "✅"];
const REACTION_SEMANTIC = {
  "👍": "acknowledgement", "❤️": "appreciation", "😂": "humour", "🎉": "celebration",
  "👀": "attention", "✅": "approval", "🙏": "gratitude", "🤔": "needs thought",
  "🚀": "excitement", "💯": "strong agreement"
};
let reactionMenu = null;
let reactionMenuMessage = null;
let reactionMenuSendMode = "private";

function reactionRecentEmojis() {
  try {
    const list = JSON.parse(localStorage.getItem("a8m.reaction.recent") || "[]");
    return Array.isArray(list) ? list.filter((emoji) => typeof emoji === "string").slice(0, 12) : [];
  } catch { return []; }
}

function rememberReactionEmoji(emoji) {
  const list = reactionRecentEmojis().filter((item) => item !== emoji);
  list.unshift(emoji);
  try { localStorage.setItem("a8m.reaction.recent", JSON.stringify(list.slice(0, 12))); } catch {}
}

async function ensureReactionCatalog() {
  if (state.reactionCatalog) return state.reactionCatalog;
  const data = await api("/api/reaction-catalog");
  state.reactionCatalog = data && Array.isArray(data.categories) ? data : { categories: [] };
  return state.reactionCatalog;
}

function reactionSearchMatches(item, query) {
  if (!query) return true;
  const needle = query.toLowerCase();
  return [item.emoji, item.label, item.keywords, item.semantic].some((value) => String(value || "").toLowerCase().includes(needle));
}

function reactionCatalogMarkup(query = "") {
  const catalog = state.reactionCatalog;
  if (!catalog) return `<div class="reaction-catalog-loading"><span class="passkey-spinner" aria-hidden="true"></span>Loading emoji…</div>`;
  const recent = reactionRecentEmojis();
  const groups = [];
  if (!query && recent.length) {
    groups.push(`<div class="reaction-catalog-group"><span class="reaction-catalog-label">Recently used</span><div class="reaction-catalog-grid">${recent.map((emoji) => `<button type="button" data-reaction-emoji="${esc(emoji)}" title="React ${esc(emoji)}">${esc(emoji)}</button>`).join("")}</div></div>`);
  }
  for (const category of catalog.categories || []) {
    const items = (category.emojis || []).filter((item) => reactionSearchMatches(item, query));
    if (!items.length) continue;
    groups.push(`<div class="reaction-catalog-group"><span class="reaction-catalog-label">${esc(category.name)}</span><div class="reaction-catalog-grid">${items.map((item) => `<button type="button" data-reaction-emoji="${esc(item.emoji)}" data-reaction-semantic="${esc(item.semantic || "")}" title="${esc(item.label || item.emoji)}">${esc(item.emoji)}</button>`).join("")}</div></div>`);
  }
  return groups.join("") || `<div class="reaction-catalog-empty">No emoji match “${esc(query)}”.</div>`;
}

function rawMessageId(messageId) {
  const value = String(messageId || "");
  if (!value.startsWith("dlg:")) return value;
  const parts = value.split(":");
  return parts.slice(2).join(":");
}

function reactionCacheKey(ownerId, threadId) {
  return `${ownerId || ""}:${threadId || ""}`;
}

function reactionEntryForThread(thread) {
  const latest = thread?.latest || thread?.messages?.[0];
  if (!latest) return { key: "", entry: null };
  const key = reactionCacheKey(messageOwnerId(latest), thread.id);
  return { key, entry: state.reactionCache.get(key) || null };
}

function threadReactionList(thread) {
  return reactionEntryForThread(thread).entry?.list || [];
}

function reactionsForMessage(message) {
  if (!message) return [];
  const thread = { id: message.threadId || message.id, messages: [message], latest: message };
  return threadReactionList(thread).filter((reaction) => reaction.messageId === rawMessageId(message.id));
}

function reactionHintMarkup(message) {
  const reactions = reactionsForMessage(message);
  if (!reactions.length) return "";
  const counts = new Map();
  for (const reaction of reactions) counts.set(reaction.emoji, (counts.get(reaction.emoji) || 0) + 1);
  const summary = Array.from(counts.entries()).slice(0, 2).map(([emoji, count]) => `${emoji}${count > 1 ? count : ""}`).join(" ");
  return `<span class="meta-dot" aria-hidden="true"></span><span class="thread-reaction-hint" title="Reactions on this message">${esc(summary)}</span>`;
}

function reactionAllowedForMessage(message) {
  if (!message || !tenantFeatureEnabled("reactions")) return false;
  if (message.draft || message.folder === "drafts" || message.folder === "sent" || message.folder === "spam") return false;
  if (message.unsubscribe && typeof message.unsubscribe === "object" && Object.keys(message.unsubscribe).length) return false;
  if (isSentLike(message)) return false;
  return true;
}

function threadReactionAllowed(thread) {
  if (!tenantFeatureEnabled("reactions")) return false;
  if (["sent", "drafts", "spam", "subscriptions"].includes(state.folder)) return false;
  if (!reactionAllowedForMessage(thread?.latest)) return false;
  return !(thread.messages || []).some((message) => message.unsubscribe && typeof message.unsubscribe === "object" && Object.keys(message.unsubscribe).length);
}

function reactionBarMarkup(message) {
  const reactions = reactionsForMessage(message);
  const canReact = reactionAllowedForMessage(message);
  const groups = new Map();
  for (const reaction of reactions) {
    const group = groups.get(reaction.emoji) || { emoji: reaction.emoji, count: 0, own: false, status: "" };
    group.count += 1;
    if (reaction.own) {
      group.own = true;
      group.status = reaction.status;
      group.reactionId = reaction.id;
    }
    groups.set(reaction.emoji, group);
  }
  const chips = Array.from(groups.values()).map((group) => {
    const own = group.own;
    const statusIcon = group.status === "sent" ? '<svg class="icon" aria-hidden="true"><use href="#i-send"/></svg>'
      : group.status === "private" ? '<svg class="icon" aria-hidden="true"><use href="#i-lock"/></svg>'
      : group.status === "pending" ? '<svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>'
      : "";
    const title = own
      ? group.status === "sent" ? "Your reaction was sent to the sender" : group.status === "pending" ? "Sending your reaction" : "Your private reaction"
      : "Reaction in this conversation";
    return `<span class="reaction-chip${own ? " is-own" : ""}${group.status === "failed" ? " is-failed" : ""}" title="${esc(title)}">
      <span class="reaction-emoji">${group.emoji}</span>${group.count > 1 ? `<b>${group.count}</b>` : ""}${statusIcon}
      ${own ? `<button class="reaction-remove" type="button" data-reaction-remove="${esc(message.id)}" aria-label="Remove your reaction" title="Remove your reaction">×</button>` : ""}
    </span>`;
  }).join("");
  const own = reactions.find((reaction) => reaction.own);
  let statusLine = "";
  if (own?.status === "pending") {
    statusLine = `<span class="reaction-status is-pending"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>Sending to sender · <button type="button" data-reaction-remove="${esc(message.id)}">Undo</button></span>`;
  } else if (own?.status === "failed") {
    statusLine = `<span class="reaction-status is-failed">${esc(own.error || "Could not send")} · <button type="button" data-reaction-remove="${esc(message.id)}">Undo</button></span>`;
  }
  return `<div class="reaction-bar" data-reaction-bar="${esc(message.id)}">
    ${chips}
    ${canReact ? `<button class="reaction-add" type="button" data-reaction-open="${esc(message.id)}" aria-label="Add a reaction" title="Add a reaction"><span class="reaction-smile" aria-hidden="true">☺</span><span>React</span></button>` : ""}
    ${statusLine}
  </div>`;
}

function threadReactionSummaryMarkup(thread) {
  const reactions = threadReactionList(thread);
  if (!reactions.length) return "";
  const counts = new Map();
  for (const reaction of reactions) counts.set(reaction.emoji, (counts.get(reaction.emoji) || 0) + 1);
  const summary = Array.from(counts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([emoji, count]) => `${emoji}${count > 1 ? ` ${count}` : ""}`).join(" · ");
  return `<span class="thread-meta-chip reaction-summary" title="Visible reactions in this conversation">${esc(summary)}</span>`;
}

function ensureThreadReactions(thread, { force = false } = {}) {
  if (!thread || thread.latest?.draft) return;
  const latest = thread.latest || thread.messages?.[0];
  if (!latest) return;
  const ownerId = messageOwnerId(latest);
  const key = reactionCacheKey(ownerId, thread.id);
  const existing = state.reactionCache.get(key);
  if (existing?.loading) return;
  if (!force && existing && Date.now() - (existing.loadedAt || 0) < 15000) return;
  state.reactionCache.set(key, { ...(existing || {}), loading: true });
  api(`/api/reactions?threadId=${encodeURIComponent(thread.id)}&ownerId=${encodeURIComponent(ownerId)}`)
    .then((data) => {
      state.reactionCache.set(key, { list: Array.isArray(data.reactions) ? data.reactions : [], loadedAt: Date.now(), loading: false });
      const current = currentThread();
      if (current && current.id === thread.id) renderReader({ preserveScroll: true });
    })
    .catch(() => {
      state.reactionCache.delete(key);
    });
}

function reactionCachePut(message, reaction) {
  const ownerId = messageOwnerId(message);
  const threadId = message.threadId || message.id;
  const key = reactionCacheKey(ownerId, threadId);
  const entry = state.reactionCache.get(key) || { list: [], loadedAt: Date.now(), loading: false };
  const list = (entry.list || []).filter((item) => !(item.own && item.messageId === rawMessageId(message.id)));
  if (reaction) list.push(reaction);
  state.reactionCache.set(key, { list, loadedAt: Date.now(), loading: false });
}

function reactionCacheRemove(message) {
  const ownerId = messageOwnerId(message);
  const threadId = message.threadId || message.id;
  const key = reactionCacheKey(ownerId, threadId);
  const entry = state.reactionCache.get(key);
  if (!entry) return;
  state.reactionCache.set(key, {
    ...entry,
    list: (entry.list || []).filter((item) => !(item.own && item.messageId === rawMessageId(message.id))),
    loadedAt: Date.now()
  });
}

async function applyReaction(message, emoji, visibility, semantic = "") {
  const data = await api(`/api/messages/${encodeURIComponent(message.id)}/reaction`, {
    method: "POST",
    body: { emoji, visibility, semantic: semantic || REACTION_SEMANTIC[emoji] || "" }
  });
  if (data.reaction) reactionCachePut(message, data.reaction);
  renderReader({ preserveScroll: true });
  if (visibility === "sent") {
    showToast("Reaction will be sent to the sender.", "Undo", () => removeReaction(message, { silent: false }));
    const thread = { id: message.threadId || message.id, messages: [message], latest: message };
    setTimeout(() => {
      const entry = reactionEntryForThread(thread).entry;
      if (entry) entry.loadedAt = 0;
      if (currentThread()?.id === thread.id) ensureThreadReactions(thread, { force: true });
    }, 11000);
  } else {
    showToast("Private reaction added.");
  }
}

async function removeReaction(message, { silent = false } = {}) {
  const data = await api(`/api/messages/${encodeURIComponent(message.id)}/reaction`, { method: "DELETE", body: {} });
  reactionCacheRemove(message);
  renderReader({ preserveScroll: true });
  if (!silent) {
    if (data.wasSent) showToast("Reaction removed. The sender already received the email.");
    else if (data.pending) showToast("Reaction cancelled before it was sent.");
    else showToast("Reaction removed.");
  }
}

function closeReactionMenu() {
  reactionMenu?.remove();
  reactionMenu = null;
  reactionMenuMessage = null;
  reactionMenuSendMode = "private";
}

function positionReactionMenu(menu, rect) {
  const width = Math.min(380, window.innerWidth - 24);
  const left = Math.min(window.innerWidth - width - 12, Math.max(12, rect.left || 12));
  let top = (rect.bottom || rect.top || 12) + 6;
  if (top + menu.offsetHeight > window.innerHeight - 12) top = Math.max(12, (rect.top || 12) - menu.offsetHeight - 6);
  menu.style.width = `${width}px`;
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function openReactionConfirm(message, emoji, semantic) {
  if (!message) return;
  document.getElementById("reactionConfirmOverlay")?.remove();
  const senderName = message.from?.name || message.from?.email || "the sender";
  const reactorName = state.user?.name || state.user?.email || "You";
  const organization = state.organizationName || "your organization";
  const overlay = document.createElement("div");
  overlay.className = "overlay reaction-confirm-overlay";
  overlay.id = "reactionConfirmOverlay";
  overlay.innerHTML = `<div class="dialog reaction-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="reactionConfirmTitle">
    <div class="reaction-confirm-emoji" aria-hidden="true">${esc(emoji)}</div>
    <h2 id="reactionConfirmTitle">Send this reaction?</h2>
    <p><strong>${esc(senderName)}</strong> will receive a short email from ${esc(reactorName)} at ${esc(organization)}.</p>
    <div class="reaction-confirm-preview"><span aria-hidden="true">${esc(emoji)}</span><div><b>${esc(reactorName)} from ${esc(organization)}</b><small>reacted via Alt8Mail</small></div></div>
    <div class="reaction-confirm-actions"><button class="btn-secondary" type="button" data-reaction-confirm-cancel>Cancel</button><button class="btn-secondary" type="button" data-reaction-confirm-private>Keep private</button><button class="btn-primary" type="button" data-reaction-confirm-send>Send reaction</button></div>
  </div>`;
  document.body.appendChild(overlay);
  const onKey = (event) => { if (event.key === "Escape") close(); };
  const close = () => {
    document.removeEventListener("keydown", onKey);
    overlay.remove();
  };
  overlay.addEventListener("click", (event) => { if (event.target === overlay) close(); });
  overlay.querySelector("[data-reaction-confirm-cancel]")?.addEventListener("click", close);
  overlay.querySelector("[data-reaction-confirm-private]")?.addEventListener("click", () => { close(); applyReaction(message, emoji, "private", semantic).catch(showError); });
  overlay.querySelector("[data-reaction-confirm-send]")?.addEventListener("click", (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    close();
    applyReaction(message, emoji, "sent", semantic).catch(showError);
  });
  document.addEventListener("keydown", onKey);
  setTimeout(() => overlay.querySelector("[data-reaction-confirm-send]")?.focus(), 50);
}

function openReactionMenu(button, message) {
  closeReactionMenu();
  if (!reactionAllowedForMessage(message)) {
    showToast("Reactions are unavailable for this message");
    return;
  }
  const readOnlyDelegate = Boolean(message.delegateOwnerId) && message.delegateCanSend !== true;
  const senderName = message.from?.name || message.from?.email || "the sender";
  const menu = document.createElement("div");
  menu.className = "reaction-menu";
  menu.setAttribute("role", "dialog");
  menu.setAttribute("aria-label", "React to this message");
  reactionMenuSendMode = "private";
  menu.innerHTML = `<div class="reaction-menu-head"><div><strong>React</strong><small>${esc(senderName)}</small></div><button class="icon-btn" type="button" data-reaction-close aria-label="Close reactions"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button></div>
    <div class="reaction-quick" role="group" aria-label="Quick reactions">${REACTION_QUICK.map((emoji) => `<button type="button" data-reaction-emoji="${emoji}" data-reaction-semantic="${esc(REACTION_SEMANTIC[emoji] || "")}" title="React ${emoji}">${emoji}</button>`).join("")}</div>
    <div class="reaction-mode" role="group" aria-label="Reaction visibility"><button type="button" class="is-active" data-reaction-mode="private">Private</button><button type="button" data-reaction-mode="sent" ${readOnlyDelegate ? "disabled" : ""}>Send to sender</button></div>
    <label class="reaction-search"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><input type="search" data-reaction-search placeholder="Search emoji" autocomplete="off" aria-label="Search emoji"></label>
    <div class="reaction-catalog" data-reaction-catalog><div class="reaction-catalog-loading"><span class="passkey-spinner" aria-hidden="true"></span>Loading emoji…</div></div>
    <div class="reaction-suggestions" data-reaction-suggestions><span class="reaction-suggestions-loading">Finding the right response…</span></div>
    <p class="reaction-menu-note">Private reactions stay in your mailbox. Sending emails ${esc(senderName)} a short reaction from ${esc(state.organizationName || "your organization")}.</p>`;
  document.body.appendChild(menu);
  reactionMenu = menu;
  reactionMenuMessage = message;
  positionReactionMenu(menu, button.getBoundingClientRect());
  menu.querySelector("[data-reaction-close]")?.focus();
  menu.querySelector("[data-reaction-search]")?.addEventListener("input", (event) => {
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = reactionCatalogMarkup(event.target.value.trim());
  });
  menu.querySelectorAll("[data-reaction-mode]").forEach((modeButton) => modeButton.addEventListener("click", () => {
    reactionMenuSendMode = modeButton.getAttribute("data-reaction-mode") === "sent" ? "sent" : "private";
    menu.querySelectorAll("[data-reaction-mode]").forEach((item) => item.classList.toggle("is-active", item === modeButton));
  }));
  ensureReactionCatalog().then(() => {
    if (reactionMenu !== menu) return;
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = reactionCatalogMarkup();
  }).catch(() => {
    const container = menu.querySelector("[data-reaction-catalog]");
    if (container) container.innerHTML = `<div class="reaction-catalog-empty">Emoji catalog unavailable.</div>`;
  });
  api("/api/ai/reactions", { method: "POST", body: { messageId: message.id } })
    .then((data) => {
      if (reactionMenu !== menu) return;
      const container = menu.querySelector("[data-reaction-suggestions]");
      const suggestions = Array.isArray(data.suggestions) ? data.suggestions : [];
      if (!container) return;
      if (!suggestions.length) {
        container.innerHTML = `<span class="reaction-suggestions-empty">Quick reactions are ready above.</span>`;
        return;
      }
      container.innerHTML = `<span class="reaction-suggestions-label">${data.ai ? "Suggested by AI" : "Semantic suggestions"}</span><div class="reaction-suggestions-row">${suggestions.map((item) => `<button type="button" data-reaction-emoji="${esc(item.emoji)}" data-reaction-semantic="${esc(item.semantic || "")}" title="${esc(item.reason || item.label || "")}"><span>${item.emoji}</span><span>${esc(item.label || item.semantic || item.emoji)}</span></button>`).join("")}</div>`;
    })
    .catch(() => {
      const container = menu.querySelector("[data-reaction-suggestions]");
      if (container) container.innerHTML = `<span class="reaction-suggestions-empty">Quick reactions are ready above.</span>`;
    });
}

function threadMetaKey(ownerId, threadId) {
  return `${ownerId || ""}:${threadId || ""}`;
}

function messageOwnerId(message) {
  return message?.delegateOwnerId || state.user?.id || "";
}

function threadMetaForMessage(message) {
  if (!message) return null;
  const threadId = message.threadId || message.id || "";
  return state.threadMeta.get(threadMetaKey(messageOwnerId(message), threadId)) || null;
}

function threadMetaForThread(thread) {
  return thread ? threadMetaForMessage(thread.latest || thread.messages?.[0]) : null;
}

function applyThreadMeta(list) {
  state.threadMeta = new Map();
  for (const item of Array.isArray(list) ? list : []) {
    if (!item?.ownerId || !item?.threadId) continue;
    state.threadMeta.set(threadMetaKey(item.ownerId, item.threadId), item);
  }
}

function threadIsClosed(message) {
  return threadMetaForMessage(message)?.closed === true;
}

function scopeMessages() {
  let messages;
  if (state.query) {
    state.searchParsed = state.searchParsed || parseQuery(state.query);
    state.searchMatched = state.searchResults || [];
    messages = state.searchMatched;
  } else {
    state.searchParsed = null;
    state.searchMatched = [];
    state.searchResults = [];
    state.searchErrors = [];
    state.searchLoading = false;
    const snoozeActive = (message) => Boolean(message.snoozedUntil) && Date.parse(message.snoozedUntil) > Date.now();
    if (state.folder === "starred") {
      messages = state.messages.filter((message) => message.starred && message.folder !== "spam" && message.folder !== "trash" && !message.ignored && !snoozeActive(message));
    } else if (state.folder === "snoozed") {
      messages = state.messages.filter((message) => !message.ignored && snoozeActive(message));
    } else if (state.folder === "subscriptions") {
      messages = state.messages.filter((message) => !message.ignored && !snoozeActive(message) && message.folder === "subscriptions" && !message.delegateOwnerId);
    } else {
      messages = state.messages.filter((message) => message.folder === state.folder && !message.ignored && !snoozeActive(message));
    }
  }
  if (!state.query) {
    const closedView = state.filter === "closed";
    messages = messages.filter((message) => threadIsClosed(message) === closedView);
  }
  if (state.filter === "unread") messages = messages.filter((message) => message.unread);
  if (state.filter === "starred") messages = messages.filter((message) => message.starred);
  if (state.filter === "flagged") messages = messages.filter((message) => message.flagged);
  if (state.filter === "attachments") messages = messages.filter((message) => (message.attachments || []).length);
  if (state.filter === "toMe") messages = messages.filter((message) => messageIsAddressedToMe(message));
  if (state.filter === "mentions") messages = messages.filter((message) => messageMentionsMe(message));
  if (state.filter === "calendar") messages = messages.filter((message) => messageHasCalendarInvite(message));
  if (state.pendingMailRemoval.size) {
    messages = messages.filter((message) => !state.pendingMailRemoval.has(message.id));
  }
  return messages;
}

function messageIsAddressedToMe(message) {
  const me = normalizeEmail(state.user?.email);
  if (!me) return false;
  return ["to", "cc", "bcc"].some((field) => (Array.isArray(message[field]) ? message[field] : []).some((person) => normalizeEmail(person?.email) === me));
}

function messageMentionsMe(message) {
  const me = normalizeEmail(state.user?.email);
  if (!me) return false;
  const local = me.split("@")[0];
  const haystack = `${message.bodyText || ""} ${message.bodyHtml || ""} ${message.snippet || ""}`.toLowerCase();
  return haystack.includes(`@${me}`) || (local.length > 2 && haystack.includes(`@${local}`));
}

function isCalendarAttachment(file) {
  const mime = String(file?.mime || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  return mime.startsWith("text/calendar") || mime === "application/ics" ||
    mime === "application/calendar" || name.endsWith(".ics");
}

function messageHasCalendarInvite(message) {
  if (message.event && typeof message.event === "object") return true;
  return (message.attachments || []).some(isCalendarAttachment);
}

function inboxViewIndividual() {
  return state.preferences?.inboxView === "individual";
}

function individualThreadFor(message) {
  const sender = message.from && message.from.email ? message.from : null;
  const recipient = Array.isArray(message.to) && message.to.length ? message.to[0] : message.to;
  const person = sender || (recipient && recipient.email ? recipient : null);
  return {
    id: message.id,
    messages: [message],
    latest: message,
    subject: message.subject || "(no subject)",
    participants: person ? [person] : [],
    unreadCount: message.unread ? 1 : 0,
    starred: Boolean(message.starred),
    flagged: Boolean(message.flagged),
    pinned: Boolean(message.pinned),
    hasAttachments: (message.attachments || []).length > 0,
    folderSet: [message.folder],
    date: message.date,
    count: 1,
    individual: true,
    repliedAt: message.repliedAt || "",
    forwardedAt: message.forwardedAt || "",
    replyCount: Number(message.replyCount) || 0,
    forwardCount: Number(message.forwardCount) || 0,
    snoozeReturned: Boolean(message.unread && message.snoozedUntil && (Date.parse(message.snoozedUntil) || 0) <= Date.now()),
    snoozeReturnAt: Boolean(message.unread && message.snoozedUntil && (Date.parse(message.snoozedUntil) || 0) <= Date.now()) ? message.snoozedUntil : ""
  };
}

function viewUnit(count) {
  return inboxViewIndividual()
    ? (count === 1 ? "message" : "messages")
    : (count === 1 ? "conversation" : "conversations");
}

function pinnedFirstThreads(threads) {
  const pinned = [];
  const returnedSnoozes = [];
  const other = [];
  for (const thread of threads) {
    if (thread.pinned) pinned.push(thread);
    else if (thread.snoozeReturned) returnedSnoozes.push(thread);
    else other.push(thread);
  }
  pinned.sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0));
  returnedSnoozes.sort((a, b) => (Date.parse(b.snoozeReturnAt) || 0) - (Date.parse(a.snoozeReturnAt) || 0));
  return pinned.concat(returnedSnoozes, other);
}

function computeView() {
  const scope = scopeMessages();
  let threads;
  if (inboxViewIndividual()) {
    threads = scope.slice().sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0)).map(individualThreadFor);
    if (!state.sortDesc) threads = threads.slice().reverse();
  } else {
    threads = buildThreads(scope, state.messages);
    if (!state.sortDesc) threads = threads.slice().reverse();
  }
  // Pinned conversations are a reading priority, not a date order. Keep them
  // above the normal list in both newest-first and oldest-first modes.
  threads = pinnedFirstThreads(threads);
  state.viewScope = scope;
  state.viewThreads = threads;
  return threads;
}

function scopeSet() {
  return new Set(state.viewScope.map((message) => message.id));
}

function threadScopeMessages(thread) {
  const set = scopeSet();
  return thread.messages.filter((message) => set.has(message.id));
}

function representativeMessage(thread) {
  if (state.folder === "sent" && !state.query) {
    const sent = thread.messages.filter((message) => message.folder === "sent");
    if (sent.length) return sent[sent.length - 1];
  }
  if (state.folder === "drafts" && !state.query) {
    const drafts = thread.messages.filter((message) => message.folder === "drafts");
    if (drafts.length) return drafts[drafts.length - 1];
  }
  if (state.query) {
    const inScope = threadScopeMessages(thread);
    if (inScope.length) return inScope[inScope.length - 1];
  }
  return thread.latest;
}

function isSentLike(message) {
  return message.folder === "sent";
}

function threadRowDisplay(thread) {
  const rep = representativeMessage(thread);
  const outgoing = isSentLike(rep);
  const person = (outgoing || rep.draft)
    ? (Array.isArray(rep.to) && rep.to.length ? rep.to[0] : rep.from)
    : rep.from;
  let label;
  if (rep.draft) label = `Draft to ${recipientLabel(rep)}`;
  else if (outgoing) label = `To: ${recipientLabel(rep)}`;
  else label = rep.from ? rep.from.name : "Unknown sender";
  return { rep, person, label, outgoing };
}

function currentThread() {
  return threadById(state.selectedThreadId);
}

function currentMessage() {
  const thread = currentThread();
  if (!thread) return null;
  return thread.latest;
}

function actionMessageIds(threads) {
  const ids = new Set();
  const includeAllFolders = Boolean(state.query) || state.folder === "starred";
  for (const thread of threads) {
    for (const message of thread.messages) {
      if (includeAllFolders) {
        if (message.folder !== "drafts" || state.folder === "drafts" || state.query) ids.add(message.id);
      } else if (state.folder === "snoozed") {
        if (message.snoozedUntil && Date.parse(message.snoozedUntil) > Date.now()) ids.add(message.id);
      } else if (message.folder === state.folder) {
        ids.add(message.id);
      }
    }
  }
  return Array.from(ids);
}

function selectedThreads() {
  return state.viewThreads.filter((thread) => state.selectedIds.has(thread.id));
}

