function ensurePhase3SettingsUi() {
  const accountPanel = document.querySelector('[data-settings-panel="account"]');
  if (accountPanel && !document.getElementById("yearReviewBlock")) {
    const markup = `<div class="settings-block" id="yearReviewBlock">
      <div class="settings-block-head"><h3>Year in review</h3><p>Your personal email story: volume, contacts, focus time and reactions.</p></div>
      <div class="year-review-teaser"><span class="year-review-mark" aria-hidden="true">Aa</span><div><strong>See your year in email</strong><span>A private, personal recap built from your mailbox.</span></div><button class="btn-secondary" id="openYearReview" type="button">Open year in review</button></div>
    </div>`;
    const firstBlock = accountPanel.querySelector(".settings-block");
    if (firstBlock) firstBlock.insertAdjacentHTML("afterend", markup);
    else accountPanel.insertAdjacentHTML("beforeend", markup);
    document.getElementById("openYearReview")?.addEventListener("click", () => openYearReview());
  }
  const rulesPanel = document.querySelector('[data-settings-panel="rules"]');
  if (rulesPanel && tenantFeatureEnabled("reactions") && !document.getElementById("reactionRulesBlock")) {
    rulesPanel.insertAdjacentHTML("beforeend", `<div class="settings-block" id="reactionRulesBlock">
      <div class="settings-block-head"><h3>Reaction rules</h3><p>Automatically add a private reaction when new mail matches a sender or subject. Rules never send email.</p></div>
      <div class="reaction-rule-list" id="reactionRuleList"><div class="settings-note">Loading reaction rules…</div></div>
      <div class="settings-actions"><button class="btn-secondary" id="addReactionRuleBtn" type="button">New reaction rule</button><span class="settings-note">Private reactions are visible only to you.</span></div>
    </div>`);
    document.getElementById("addReactionRuleBtn")?.addEventListener("click", () => openReactionRuleEditor());
    loadReactionRules().catch(() => {});
  }
  ensureYearReviewOverlay();
  ensureReactionRuleOverlay();
}

function ensureYearReviewOverlay() {
  if (document.getElementById("yearReviewOverlay")) return;
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay year-review-overlay" id="yearReviewOverlay" hidden>
    <div class="dialog year-review-dialog" role="dialog" aria-modal="true" aria-labelledby="yearReviewTitle">
      <div class="dialog-head">
        <div class="dialog-title-wrap"><span class="dialog-icon"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg></span>
          <div><h2 id="yearReviewTitle">Your year in email</h2><p>Private to you · based on messages in this mailbox</p></div></div>
        <button class="icon-btn" type="button" data-year-review-close aria-label="Close year in review"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
      </div>
      <div class="dialog-body" id="yearReviewBody"></div>
    </div>
  </div>`);
}

function ensureReactionRuleOverlay() {
  if (document.getElementById("reactionRuleOverlay")) return;
  const options = ["👍", "❤️", "😂", "🎉", "👀", "✅", "🙏", "🤔", "🚀", "💯"]
    .map((emoji) => `<option value="${emoji}">${emoji} ${REACTION_SEMANTIC[emoji] || ""}</option>`).join("");
  document.body.insertAdjacentHTML("beforeend", `<div class="overlay" id="reactionRuleOverlay" hidden>
    <div class="dialog reaction-rule-dialog" role="dialog" aria-modal="true" aria-labelledby="reactionRuleTitle">
      <div class="dialog-head">
        <div class="dialog-title-wrap"><span class="dialog-icon"><svg class="icon" aria-hidden="true"><use href="#i-sparkles"/></svg></span>
          <div><h2 id="reactionRuleTitle">New reaction rule</h2><p>React privately when new mail matches.</p></div></div>
        <button class="icon-btn" type="button" data-reaction-rule-close aria-label="Close rule editor"><svg class="icon" aria-hidden="true"><use href="#i-close"/></svg></button>
      </div>
      <div class="dialog-body">
        <label class="form-field"><span>Rule name</span><input id="reactionRuleName" type="text" maxlength="120" placeholder="Thank the customer success team"></label>
        <div class="reaction-rule-grid">
          <label class="form-field"><span>Sender contains</span><input id="reactionRuleSender" type="text" maxlength="160" placeholder="alerts@example.com"></label>
          <label class="form-field"><span>Subject contains</span><input id="reactionRuleSubject" type="text" maxlength="160" placeholder="weekly report"></label>
        </div>
        <div class="reaction-rule-grid">
          <label class="form-field"><span>Reaction</span><select id="reactionRuleEmoji">${options}</select></label>
          <label class="form-field reaction-rule-enabled"><span>Apply automatically</span><input id="reactionRuleEnabled" type="checkbox" checked></label>
        </div>
        <p class="settings-note">At least one condition is required. Rules apply to new mail that arrives after the rule is created, and only add private reactions.</p>
      </div>
      <div class="dialog-actions"><button class="btn-secondary" type="button" data-reaction-rule-close>Cancel</button><button class="btn-primary" id="reactionRuleSave" type="button">Save rule</button></div>
    </div>
  </div>`);
  document.getElementById("reactionRuleSave")?.addEventListener("click", saveReactionRule);
}

async function loadReactionRules() {
  const data = await api("/api/reaction-rules");
  state.reactionRules = Array.isArray(data.rules) ? data.rules : [];
  renderReactionRules();
}

function renderReactionRules() {
  const list = document.getElementById("reactionRuleList");
  if (!list) return;
  if (!state.reactionRules.length) {
    list.innerHTML = `<div class="settings-note">No reaction rules yet. Create one to add a private reaction when matching mail arrives.</div>`;
    return;
  }
  list.innerHTML = state.reactionRules.map((rule) => {
    const conditions = [];
    if (rule.senderContains) conditions.push(`from ${rule.senderContains}`);
    if (rule.subjectContains) conditions.push(`subject ${rule.subjectContains}`);
    return `<div class="reaction-rule-row">
      <span class="reaction-rule-emoji" aria-hidden="true">${esc(rule.emoji)}</span>
      <div class="reaction-rule-copy"><strong>${esc(rule.name || "Reaction rule")}</strong><span>${esc(conditions.join(" · ") || "Any new message")}</span></div>
      <button class="reaction-rule-toggle${rule.enabled ? " is-on" : ""}" type="button" role="switch" aria-checked="${rule.enabled ? "true" : "false"}" data-reaction-rule-toggle="${esc(rule.id)}">${rule.enabled ? "On" : "Off"}</button>
      <button class="icon-btn" type="button" data-reaction-rule-edit="${esc(rule.id)}" aria-label="Edit reaction rule" title="Edit"><svg class="icon" aria-hidden="true"><use href="#i-pencil"/></svg></button>
      <button class="icon-btn" type="button" data-reaction-rule-delete="${esc(rule.id)}" aria-label="Delete reaction rule" title="Delete"><svg class="icon" aria-hidden="true"><use href="#i-trash"/></svg></button>
    </div>`;
  }).join("");
}

function openReactionRuleEditor(ruleId = "") {
  ensureReactionRuleOverlay();
  const rule = state.reactionRules.find((item) => item.id === ruleId) || null;
  state.reactionRuleEditing = rule;
  document.getElementById("reactionRuleTitle").textContent = rule ? "Edit reaction rule" : "New reaction rule";
  document.getElementById("reactionRuleName").value = rule?.name || "";
  document.getElementById("reactionRuleSender").value = rule?.senderContains || "";
  document.getElementById("reactionRuleSubject").value = rule?.subjectContains || "";
  document.getElementById("reactionRuleEmoji").value = rule?.emoji || "👍";
  document.getElementById("reactionRuleEnabled").checked = rule ? rule.enabled !== false : true;
  document.getElementById("reactionRuleOverlay").hidden = false;
  setTimeout(() => document.getElementById("reactionRuleName")?.focus(), 40);
}

function closeReactionRuleEditor() {
  const overlay = document.getElementById("reactionRuleOverlay");
  if (overlay) overlay.hidden = true;
  state.reactionRuleEditing = null;
}

async function saveReactionRule() {
  const name = document.getElementById("reactionRuleName")?.value.trim() || "";
  const senderContains = document.getElementById("reactionRuleSender")?.value.trim() || "";
  const subjectContains = document.getElementById("reactionRuleSubject")?.value.trim() || "";
  const emoji = document.getElementById("reactionRuleEmoji")?.value || "👍";
  const enabled = Boolean(document.getElementById("reactionRuleEnabled")?.checked);
  if (!senderContains && !subjectContains) {
    showToast("Add a sender or subject condition.");
    return;
  }
  const button = document.getElementById("reactionRuleSave");
  if (button) button.disabled = true;
  try {
    const rule = state.reactionRuleEditing;
    if (rule) {
      await api(`/api/reaction-rules/${encodeURIComponent(rule.id)}`, { method: "PATCH", body: { name, senderContains, subjectContains, emoji, enabled } });
    } else {
      await api("/api/reaction-rules", { method: "POST", body: { name, senderContains, subjectContains, emoji, enabled } });
    }
    closeReactionRuleEditor();
    await loadReactionRules();
    showToast("Reaction rule saved.");
  } catch (error) {
    showError(error);
  } finally {
    if (button) button.disabled = false;
  }
}

async function toggleReactionRule(ruleId) {
  const rule = state.reactionRules.find((item) => item.id === ruleId);
  if (!rule) return;
  try {
    await api(`/api/reaction-rules/${encodeURIComponent(ruleId)}`, { method: "PATCH", body: { enabled: !rule.enabled } });
    await loadReactionRules();
  } catch (error) {
    showError(error);
  }
}

async function deleteReactionRule(ruleId) {
  const rule = state.reactionRules.find((item) => item.id === ruleId);
  if (!rule) return;
  const ok = await appConfirm({
    title: "Delete reaction rule?",
    message: `“${rule.name || "Reaction rule"}” will stop adding reactions to new mail. Existing reactions stay in place.`,
    confirmLabel: "Delete rule",
    tone: "danger",
    icon: "i-trash"
  });
  if (!ok) return;
  try {
    await api(`/api/reaction-rules/${encodeURIComponent(ruleId)}`, { method: "DELETE", body: {} });
    await loadReactionRules();
    showToast("Reaction rule deleted.");
  } catch (error) {
    showError(error);
  }
}

async function openYearReview(year = null) {
  ensureYearReviewOverlay();
  const overlay = document.getElementById("yearReviewOverlay");
  const body = document.getElementById("yearReviewBody");
  overlay.hidden = false;
  body.innerHTML = `<div class="year-review-loading">Building your year…</div>`;
  const target = year || state.yearReviewYear || new Date().getFullYear();
  try {
    const data = await api(`/api/yearly-review?year=${encodeURIComponent(target)}`);
    state.yearReview = data;
    state.yearReviewYear = data.year;
    renderYearReview(data);
  } catch (error) {
    body.innerHTML = `<div class="year-review-loading">${esc(error.message || "Could not build your year in review.")}</div>`;
  }
}

function yearNumber(value) {
  return new Intl.NumberFormat(currentLocale()).format(Number(value) || 0);
}

function yearReadingLabel(minutes) {
  const value = Number(minutes) || 0;
  if (value < 60) return `${value} min`;
  return `${(value / 60).toFixed(1)} hours`;
}

function renderYearReview(data) {
  const body = document.getElementById("yearReviewBody");
  if (!body) return;
  const totals = data.totals || {};
  const maxMonth = Math.max(1, ...(data.monthly || []).map((item) => Number(item.count) || 0));
  const years = Array.isArray(data.years) ? data.years : [data.year];
  const monthBars = (data.monthly || []).map((item) => {
    const count = Number(item.count) || 0;
    const percent = Math.max(count ? 4 : 1, Math.round((count / maxMonth) * 100));
    return `<div class="year-month${count ? "" : " is-empty"}" title="${esc(item.label)}: ${yearNumber(count)} messages" aria-label="${esc(item.label)}: ${yearNumber(count)} messages"><span class="year-month-bar" style="height:${percent}%"></span><small>${esc(String(item.label || "").slice(0, 3))}</small></div>`;
  }).join("");
  const contacts = (items, empty) => items?.length
    ? items.map((item, index) => `<div class="year-contact"><span class="year-contact-rank">${index + 1}</span><div><strong>${esc(item.name || item.email)}</strong><span>${esc(item.email)}</span></div><b>${yearNumber(item.count)}</b></div>`).join("")
    : `<div class="year-review-empty">${esc(empty)}</div>`;
  const reactionTop = (data.reactions?.top || []).map((item) => `<span class="year-reaction"><span>${esc(item.emoji)}</span><b>${yearNumber(item.count)}</b><small>${esc(item.semantic || "")}</small></span>`).join("");
  body.innerHTML = `<div class="year-review-top">
      <div><span class="year-review-kicker">Alt8Mail personal recap</span><h3>${esc(data.year)} in your inbox</h3><p>${esc((data.highlights || [])[0] || "Your year in email.")}</p></div>
      <label class="year-review-year"><span>Year</span><select data-year-review-year>${years.map((value) => `<option value="${value}"${Number(value) === Number(data.year) ? " selected" : ""}>${value}</option>`).join("")}</select></label>
    </div>
    <div class="year-review-stats">
      <div class="year-stat"><span>Messages</span><strong>${yearNumber(totals.messages)}</strong><small>${yearNumber(totals.threads)} conversations</small></div>
      <div class="year-stat"><span>Sent</span><strong>${yearNumber(totals.sent)}</strong><small>${yearNumber(totals.received)} received</small></div>
      <div class="year-stat"><span>Reading time</span><strong>${esc(yearReadingLabel(totals.readingMinutes))}</strong><small>about ${yearNumber(totals.newsletters)} newsletters</small></div>
      <div class="year-stat"><span>Reactions</span><strong>${yearNumber(data.reactions?.given || 0)}</strong><small>${yearNumber(data.reactions?.received || 0)} received</small></div>
    </div>
    <div class="year-review-chart"><div class="year-review-section-head"><div><h3>When your mailbox moved</h3><p>Messages by month</p></div><span>Busiest: ${esc(data.busiestMonth?.label || "—")} · ${yearNumber(data.busiestMonth?.count || 0)}</span></div>
      <div class="year-months" role="img" aria-label="Monthly message volume">${monthBars}</div>
      <div class="year-review-foot"><span>Busiest day: ${esc(data.busiestDay?.date ? formatDateOnly(data.busiestDay.date) : "—")}</span><span>Busiest hour: ${esc(Number.isFinite(Number(data.busiestHour?.hour)) ? `${data.busiestHour.hour}:00` : "—")}</span><span>${yearNumber(totals.newsletters)} newsletters</span>${data.unsubscribed ? `<span>${yearNumber(data.unsubscribed)} ${Number(data.unsubscribed) === 1 ? "unsubscribe" : "unsubscribes"}</span>` : ""}</div>
    </div>
    <div class="year-review-columns">
      <section><div class="year-review-section-head"><div><h3>People who shaped your year</h3><p>Most frequent senders</p></div></div><div class="year-contacts">${contacts(data.topSenders, "No incoming mail in this year.")}</div></section>
      <section><div class="year-review-section-head"><div><h3>Your loudest recipients</h3><p>Most emailed contacts</p></div></div><div class="year-contacts">${contacts(data.topRecipients, "No sent mail in this year.")}</div></section>
    </div>
    <div class="year-review-columns">
      <section><div class="year-review-section-head"><div><h3>Reactions you shared</h3><p>Private and sent reactions</p></div></div><div class="year-reactions">${reactionTop || '<div class="year-review-empty">No reactions yet.</div>'}</div></section>
      <section><div class="year-review-section-head"><div><h3>Moments to remember</h3><p>Highlights from your mailbox</p></div></div><ul class="year-highlights">${(data.highlights || []).slice(1).map((item) => `<li>${esc(item)}</li>`).join("") || "<li>Your year is still taking shape.</li>"}</ul></section>
    </div>`;
  body.querySelector("[data-year-review-year]")?.addEventListener("change", (event) => openYearReview(event.target.value));
}

function renderAccountChrome() {
  const user = state.user;
  if (!user) return;
  const topAvatar = document.getElementById("accountBtn");
  if (topAvatar) {
    topAvatar.textContent = user.initials || initialsFrom(user.name);
    topAvatar.title = `${user.name} — account settings`;
  }
  const accountEmail = document.getElementById("accountEmail");
  if (accountEmail) accountEmail.textContent = user.email;
  const copyAccount = document.querySelector("[data-copy-email]");
  if (copyAccount && copyAccount.closest(".account-profile")) copyAccount.setAttribute("data-copy-email", user.email);
  const profile = $(".account-profile");
  if (profile) {
    const av = $(".avatar", profile);
    if (av) { av.textContent = user.initials || initialsFrom(user.name); av.style.setProperty("--av", user.color || "#34557a"); }
    const h3 = $(".account-profile-copy h3", profile);
    const p = $(".account-profile-copy p", profile);
    if (h3) h3.textContent = user.name;
    if (p) p.textContent = `${user.role || "Team member"} · ${user.company || "Alt8Mail"}`;
  }
}

function externalAccountsEnabled() {
  const policy = state.tenantPolicy || {};
  return Boolean(policy.mail && policy.mail.externalAccounts === true);
}

function activeAccountStorageKey() {
  return `a8m.activeAccount.${normalizeEmail(state.user?.email || "anonymous")}`;
}

function unifiedAccountsAvailable() {
  return externalAccountsEnabled() && (state.accounts || []).some((account) => !account.isNative);
}

function unifiedAccountView() {
  return {
    id: "all",
    kind: "unified",
    email: "",
    displayName: "All accounts",
    color: "#34557a",
    status: "active",
    isNative: false,
    isUnified: true,
    accountCount: (state.accounts || []).length
  };
}

function nativeMailAccount() {
  return (state.accounts || []).find((account) => account.isNative) || null;
}

function defaultComposeAccountId() {
  return state.activeAccountId === "all" ? (nativeMailAccount()?.id || "") : state.activeAccountId;
}

function accountMenuAccounts() {
  return (state.accounts || []).filter((account) => account.isNative || externalAccountsEnabled());
}

function accountMenuEntries() {
  const entries = [];
  if (unifiedAccountsAvailable()) entries.push(unifiedAccountView());
  entries.push(...accountMenuAccounts());
  return entries;
}

function accountMenuTitle(account) {
  if (!account) return "Alt8Mail";
  if (account.isUnified) return "All accounts";
  if (account.isNative) return account.displayName || state.user?.name || "Alt8Mail";
  return account.displayName || mailProviderMeta(account.provider).name || account.email || "Mail account";
}

function accountMenuSubtitle(account) {
  if (!account) return state.user?.email || "";
  if (account.isUnified) {
    const count = account.accountCount || accountMenuAccounts().length;
    return `${count} ${count === 1 ? "mailbox" : "mailboxes"} · unified inbox`;
  }
  return account.email || "";
}

function accountUnreadCount(account) {
  if (!account) return 0;
  if (account.isUnified) {
    return accountMenuAccounts().reduce((total, item) => total + Math.max(0, Number(item.unreadCount) || 0), 0);
  }
  if (account.kind === "delegated") {
    const native = (state.accounts || []).find((item) => item.isNative);
    return Math.max(0, Number(native?.unreadCount) || 0);
  }
  const live = (state.accounts || []).find((item) => item.id === account.id);
  return Math.max(0, Number((live || account).unreadCount) || 0);
}

function accountUnreadTotal() {
  return accountMenuAccounts().reduce((total, account) => total + Math.max(0, Number(account.unreadCount) || 0), 0);
}

function hydrateAccountUnreadCounts() {
  const known = state.knownAccountUnread instanceof Map ? state.knownAccountUnread : new Map();
  for (const account of state.accounts || []) {
    account.unreadCount = Math.max(0, Number(account.unreadCount) || 0);
    if (!known.has(account.id) || state.activeAccountId === "all" || state.activeAccountId === account.id) {
      known.set(account.id, account.unreadCount);
    }
  }
  state.knownAccountUnread = known;
  if (state.activeAccount) {
    if (state.activeAccount.isUnified) {
      state.activeAccount.unreadCount = accountUnreadTotal();
    } else {
      const live = (state.accounts || []).find((item) => item.id === state.activeAccount.id);
      if (live) state.activeAccount.unreadCount = live.unreadCount;
    }
  }
}

function accountMenuProviderLabel(account) {
  if (!account || account.isNative) return "Alt8Mail";
  if (account.isUnified) return "Unified";
  const meta = mailProviderMeta(account.provider);
  return meta.id === "imap" ? "IMAP" : meta.name.replace(/\s+Mail$/, "");
}

function accountMenuBadge(account) {
  if (account?.isUnified) return { label: "Combined", className: "is-unified" };
  if (account?.isNative) return { label: "Primary", className: "is-primary" };
  if (account?.status === "reauth") return { label: "Reconnect", className: "is-warning" };
  if (account?.status === "error") return { label: "Sync error", className: "is-error" };
  return { label: accountMenuProviderLabel(account), className: "" };
}

function accountMenuLogo(account, extraClass = "") {
  const extra = extraClass ? ` ${extraClass}` : "";
  if (account?.isUnified) {
    return `<span class="account-logo-unified${extra}"><svg class="icon" aria-hidden="true"><use href="#i-inbox"/></svg></span>`;
  }
  if (!account || account.isNative || !account.provider || account.provider === "alt8mail") {
    const name = account?.displayName || state.user?.name || "Alt8Mail";
    const color = account?.color || state.user?.color || "#34557a";
    const initials = initialsFrom(name || account?.email || "A8") || "A8";
    return `<span class="avatar avatar-md account-avatar${extra}" style="--av:${esc(color)}" aria-hidden="true"><span class="avatar-initials">${esc(initials)}</span></span>`;
  }
  return `<img class="account-provider-img${extra}" src="${mailProviderLogo(account.provider)}" alt="" loading="lazy">`;
}

function renderAccountMenuList() {
  const list = document.getElementById("accountMenuList");
  if (!list) return;
  const query = state.accountMenuQuery.trim().toLowerCase();
  const matches = accountMenuEntries().filter((account) => {
    if (!query) return true;
    return `${accountMenuTitle(account)} ${accountMenuSubtitle(account)} ${accountMenuProviderLabel(account)}`
      .toLowerCase().includes(query);
  });
  if (!matches.length) {
    list.innerHTML = `<div class="account-pop-empty"><svg class="icon" aria-hidden="true"><use href="#i-search"/></svg><strong>No mailbox found</strong><span>Try a name or email address.</span></div>`;
    return;
  }
  list.innerHTML = matches.map((account) => {
    const selected = account.id === state.activeAccountId;
    const badge = accountMenuBadge(account);
    const unread = accountUnreadCount(account);
    const unreadLabel = unread > 99 ? "99+" : String(unread);
    return `<button class="account-row${selected ? " is-selected" : ""}" type="button" role="option" aria-selected="${selected}" data-account-menu-id="${esc(account.id)}">
      <span class="account-row-logo">${accountMenuLogo(account)}</span>
      <span class="account-row-copy"><strong>${esc(accountMenuTitle(account))}</strong><span>${esc(accountMenuSubtitle(account))}</span></span>
      <span class="account-row-badge ${badge.className}">${esc(badge.label)}</span>
      <span class="account-row-unread${unread > 0 ? " has-unread" : ""}" title="${unread} unread message${unread === 1 ? "" : "s"}"><svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><span>${unreadLabel}</span></span>
      <span class="account-row-check" aria-hidden="true"><svg class="icon"><use href="#i-check"/></svg></span>
    </button>`;
  }).join("");
}

function renderAccountSwitcher() {
  const menu = document.getElementById("accountMenu");
  const trigger = document.getElementById("accountMenuBtn");
  const triggerLogo = document.getElementById("accountTriggerLogo");
  const triggerName = document.getElementById("accountTriggerName");
  const triggerEmail = document.getElementById("accountTriggerEmail");
  const triggerStatus = document.getElementById("accountTriggerStatus");
  const triggerUnread = document.getElementById("accountTriggerUnread");
  const triggerUnreadCount = document.getElementById("accountTriggerUnreadCount");
  const count = document.getElementById("accountMenuCount");
  const searchWrap = document.getElementById("accountSearchWrap");
  const addPop = document.getElementById("accountPopAddBtn");
  const note = document.getElementById("accountMenuNote");
  if (!menu || !trigger) return;
  const accounts = accountMenuAccounts();
  const active = state.delegatedMode
    ? {
      id: "delegated",
      kind: "delegated",
      provider: "alt8mail",
      email: state.user?.email || state.delegatedSession?.mailbox?.email || "",
      displayName: state.user?.name || "Delegated mailbox",
      color: state.user?.color,
      status: "active",
      isNative: true,
      isUnified: false
    }
    : state.activeAccount
      || (state.activeAccountId === "all" && unifiedAccountsAvailable() ? unifiedAccountView() : null)
      || accounts.find((account) => account.id === state.activeAccountId)
      || accounts[0]
      || (state.user ? {
        id: "",
        kind: "native",
        provider: "alt8mail",
        email: state.user.email,
        displayName: state.user.name || "Alt8Mail",
        color: state.user.color,
        status: "active",
        isNative: true,
        isUnified: false
      } : null);
  const visible = Boolean(active) || accounts.length > 0;
  menu.hidden = !visible;
  if (state.delegatedMode) closeAccountMenu(false);
  const canAdd = !state.delegatedMode && externalAccountsEnabled();
  if (addPop) addPop.hidden = !canAdd;
  if (note) note.hidden = externalAccountsEnabled();
  if (count) count.textContent = String(accounts.length);
  if (searchWrap) searchWrap.hidden = accountMenuEntries().length < 5;
  if (!visible || !active) return;
  triggerLogo.innerHTML = accountMenuLogo(active);
  triggerName.textContent = accountMenuTitle(active);
  triggerEmail.textContent = accountMenuSubtitle(active);
  const title = state.delegatedMode ? active.displayName : accountMenuTitle(active);
  const subtitle = accountMenuSubtitle(active);
  const unreadTotal = accountUnreadTotal();
  const unreadText = unreadTotal > 99 ? "99+" : String(unreadTotal);
  if (triggerUnread) {
    triggerUnread.hidden = unreadTotal <= 0;
    triggerUnread.title = `${unreadTotal} unread message${unreadTotal === 1 ? "" : "s"} across your mailboxes`;
    if (triggerUnreadCount) triggerUnreadCount.textContent = unreadText;
  }
  trigger.setAttribute("aria-label", state.delegatedMode
    ? `Delegated mailbox: ${title}${subtitle ? `, ${subtitle}` : ""}${unreadTotal ? `, ${unreadTotal} unread` : ""}`
    : `Mailbox: ${title}${subtitle ? `, ${subtitle}` : ""}${unreadTotal ? `, ${unreadTotal} unread across mailboxes` : ""}. Switch mailbox`);
  trigger.title = `${title}${subtitle ? ` · ${subtitle}` : ""}${unreadTotal ? ` · ${unreadTotal} unread` : ""}`;
  trigger.classList.toggle("is-unified", Boolean(active.isUnified));
  trigger.classList.toggle("is-static", state.delegatedMode);
  if (state.delegatedMode) {
    trigger.setAttribute("aria-disabled", "true");
    trigger.setAttribute("tabindex", "-1");
    trigger.removeAttribute("aria-haspopup");
    trigger.setAttribute("aria-expanded", "false");
  } else {
    trigger.removeAttribute("aria-disabled");
    trigger.removeAttribute("tabindex");
    trigger.setAttribute("aria-haspopup", "dialog");
  }
  const warning = active.status === "reauth" || active.status === "error";
  if (triggerStatus) {
    triggerStatus.hidden = !warning;
    triggerStatus.title = warning ? (active.lastError || connectedAccountStatus(active).label) : "";
    triggerStatus.innerHTML = warning ? `<svg class="icon" aria-hidden="true"><use href="#i-alert"/></svg>` : "";
  }
  renderAccountMenuList();
}

function toggleAccountMenu(force) {
  const menu = document.getElementById("accountMenu");
  const pop = document.getElementById("accountPopover");
  const trigger = document.getElementById("accountMenuBtn");
  if (!menu || !pop || menu.hidden || state.delegatedMode) return;
  const open = typeof force === "boolean" ? force : pop.hidden;
  if (open) {
    clearAccountPings();
    state.accountMenuQuery = "";
    const search = document.getElementById("accountSearch");
    if (search) search.value = "";
    renderAccountSwitcher();
  }
  state.accountMenuOpen = open;
  pop.hidden = !open;
  menu.classList.toggle("is-open", open);
  trigger?.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) {
    setTimeout(() => {
      const searchWrap = document.getElementById("accountSearchWrap");
      const search = document.getElementById("accountSearch");
      if (searchWrap && !searchWrap.hidden && search) {
        search.focus();
        return;
      }
      const row = pop.querySelector(".account-row.is-selected") || pop.querySelector(".account-row");
      row?.focus();
    }, 30);
  }
}

function closeAccountMenu(restoreFocus = false) {
  const menu = document.getElementById("accountMenu");
  const pop = document.getElementById("accountPopover");
  const trigger = document.getElementById("accountMenuBtn");
  if (!menu || !pop) return;
  const wasOpen = !pop.hidden || state.accountMenuOpen;
  state.accountMenuOpen = false;
  state.accountMenuQuery = "";
  pop.hidden = true;
  menu.classList.remove("is-open");
  trigger?.setAttribute("aria-expanded", "false");
  if (restoreFocus && wasOpen) trigger?.focus();
}

function accountMenuVisible() {
  const menu = document.getElementById("accountMenu");
  if (!menu || menu.hidden) return false;
  const rect = menu.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0 && rect.right > 0 && rect.left < window.innerWidth;
}

function resetAccountPingTimer() {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = setTimeout(() => dismissAccountPing(), 12000);
}

function renderAccountPing() {
  const node = document.getElementById("accountPing");
  const menu = document.getElementById("accountMenu");
  if (!node) return;
  const ping = state.accountPingCurrent;
  if (!ping) {
    node.hidden = true;
    menu?.classList.remove("has-news");
    return;
  }
  const account = (state.accounts || []).find((item) => item.id === ping.accountId) || ping.account;
  const latest = ping.latest || account?.latestUnread || {};
  const unread = accountUnreadCount(account);
  const unreadText = unread > 99 ? "99+" : String(unread);
  const sender = latest.fromName || latest.fromEmail || "New sender";
  const senderLine = latest.fromEmail && latest.fromEmail !== sender ? `${sender} · ${latest.fromEmail}` : sender;
  const logo = document.getElementById("accountPingLogo");
  const accountLabel = document.getElementById("accountPingAccount");
  const subject = document.getElementById("accountPingSubject");
  const meta = document.getElementById("accountPingMeta");
  const count = document.getElementById("accountPingCount");
  const open = document.getElementById("accountPingOpen");
  if (logo) logo.innerHTML = accountMenuLogo(account);
  if (accountLabel) accountLabel.textContent = account?.isNative ? "Alt8Mail" : accountMenuTitle(account);
  if (subject) subject.textContent = latest.subject || "New message";
  if (meta) meta.textContent = senderLine;
  if (count) count.innerHTML = `<svg class="icon" aria-hidden="true"><use href="#i-mail"/></svg><span>${unreadText}</span>`;
  if (open) {
    open.setAttribute("data-account-ping-id", ping.accountId);
    open.setAttribute("aria-label", `Open ${accountMenuTitle(account)} with new mail from ${sender}`);
  }
  node.hidden = false;
  menu?.classList.add("has-news");
}

function showNextAccountPing() {
  if (state.accountPingCurrent) return;
  const next = state.accountPingQueue.shift();
  if (!next) return;
  state.accountPingCurrent = next;
  renderAccountPing();
  resetAccountPingTimer();
}

function maybeQueueAccountPing(account, increase, latest) {
  if (!account || state.delegatedMode) return;
  if (state.activeAccountId === "all" || state.activeAccountId === account.id) return;
  const payload = {
    accountId: account.id,
    account: { ...account },
    increase,
    latest: latest || account.latestUnread || null
  };
  const detail = payload.latest || {};
  const sender = detail.fromName || detail.fromEmail || "a new sender";
  const subject = detail.subject || "New message";
  if (document.visibilityState !== "visible") {
    showBrowserNotification(`New mail in ${accountMenuTitle(account)}`, `${sender}: ${subject}`, `a8m-account-${account.id}`);
    return;
  }
  if (state.task !== "mail" || !accountMenuVisible()) {
    showToast(`New mail in ${accountMenuTitle(account)}: ${subject}`, "Open", () => {
      setTask("mail");
      switchMailAccount(account.id);
    });
    return;
  }
  const existing = state.accountPingCurrent?.accountId === account.id
    ? state.accountPingCurrent
    : state.accountPingQueue.find((item) => item.accountId === account.id);
  if (existing) {
    Object.assign(existing, payload);
    if (existing === state.accountPingCurrent) {
      renderAccountPing();
      resetAccountPingTimer();
    }
    return;
  }
  state.accountPingQueue.push(payload);
  showNextAccountPing();
}

function dismissAccountPing(showNext = true) {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = null;
  state.accountPingCurrent = null;
  renderAccountPing();
  if (showNext) {
    setTimeout(() => {
      if (!state.accountPingCurrent) showNextAccountPing();
    }, 300);
  }
}

function clearAccountPings() {
  clearTimeout(state.accountPingTimer);
  state.accountPingTimer = null;
  state.accountPingCurrent = null;
  state.accountPingQueue = [];
  renderAccountPing();
}

function removeAccountPings(accountId) {
  state.accountPingQueue = state.accountPingQueue.filter((item) => item.accountId !== accountId);
  if (state.accountPingCurrent?.accountId === accountId) dismissAccountPing();
}

function connectedAccountStatus(account) {
  switch (account.status) {
    case "reauth": return { label: "Reconnect required", className: "is-reauth" };
    case "error": return { label: "Sync error", className: "is-error" };
    case "disabled": return { label: "Disabled", className: "" };
    default: return { label: "Connected", className: "" };
  }
}

function renderConnectedAccounts() {
  const holder = document.getElementById("connectedAccountsList");
  if (!holder) return;
  const add = document.getElementById("connectedAccountAdd");
  if (add) add.hidden = !externalAccountsEnabled() || state.delegatedMode;
  const connected = (state.accounts || []).filter((account) => !account.isNative);
  if (!connected.length) {
    holder.innerHTML = externalAccountsEnabled()
      ? `<div class="connected-account-empty"><strong>No connected accounts yet.</strong><span>Add Gmail, Microsoft 365 or another IMAP mailbox to read it here and send from its own address.</span></div>`
      : `<div class="connected-account-empty"><strong>Connected accounts are disabled by your organization.</strong><span>An administrator can enable them under Mail access → Connected accounts.</span></div>`;
    return;
  }
  holder.innerHTML = connected.map((account) => {
    const status = connectedAccountStatus(account);
    return `<div class="connected-account-row" data-connected-account="${esc(account.id)}">
      <span class="connected-account-logo"><img src="${mailProviderLogo(account.provider)}" alt="" loading="lazy"></span>
      <div class="connected-account-copy">
        <strong>${esc(account.displayName || account.email)}</strong>
        <span>${esc(account.email)} · <span class="connected-account-status ${status.className}">${esc(status.label)}</span></span>
        ${account.lastError ? `<span title="${esc(account.lastError)}">${esc(account.lastError)}</span>` : ""}
      </div>
      <div class="connected-account-actions">
        <button class="btn-secondary" type="button" data-account-sync="${esc(account.id)}">${esc(t("accounts.sync"))}</button>
        <button class="btn-secondary" type="button" data-account-servers="${esc(account.id)}">${esc(t("accounts.servers"))}</button>
        <button class="btn-secondary" type="button" data-account-reconnect="${esc(account.id)}">${esc(account.oauth ? t("accounts.reconnect") : account.status === "reauth" ? t("accounts.reconnect") : t("accounts.password"))}</button>
        <button class="btn-secondary" type="button" data-account-remove="${esc(account.id)}">${esc(t("accounts.remove"))}</button>
      </div>
    </div>`;
  }).join("");
}

function applyConnectedAccountSettingsScope() {
  const connected = Boolean(state.activeAccount && state.activeAccount.kind === "external");
  document.querySelectorAll('[data-settings-tab="rules"], [data-settings-tab="autoreply"]').forEach((tab) => {
    tab.hidden = connected;
  });
  if (connected && ["rules", "autoreply"].includes(state.settingsTab)) {
    state.settingsTab = "account";
  }
}

function switchMailAccount(accountId, { reload = true } = {}) {
  const account = accountId === "all"
    ? (unifiedAccountsAvailable() ? unifiedAccountView() : null)
    : (state.accounts || []).find((item) => item.id === accountId);
  if (!account || accountId === state.activeAccountId) return;
  state.activeAccountId = accountId;
  state.activeAccount = account;
  try { localStorage.setItem(activeAccountStorageKey(), accountId); } catch {}
  state.folder = "inbox";
  state.filter = "all";
  state.query = "";
  state.selectedThreadId = null;
  state.selectedMessageId = null;
  state.messages = [];
  state.mailPages = {};
  state.knownInboxIds = null;
  state.knownSnoozeDueIds = new Set();
  state.homeTab = "home";
  state.pulseData = null;
  state.pulseYear = null;
  renderAccountSwitcher();
  renderAccountChrome();
  if (reload) {
    loadBootstrap({ quiet: true }).catch((error) => showToast(error.message || "Could not switch mail account"));
  }
}

function startMailOAuth(provider, accountId = "") {
  return new Promise((resolve, reject) => {
    const query = accountId ? `?account=${encodeURIComponent(accountId)}` : "";
    const popup = window.open(
      `/api/mail/oauth/${encodeURIComponent(provider)}/start${query}`,
      "a8m-mail-oauth",
      "width=520,height=720,menubar=no,toolbar=no"
    );
    if (!popup) {
      reject(new Error("Allow pop-ups for Alt8Mail to finish the sign-in."));
      return;
    }
    let settled = false;
    let poll = null;
    let timeout = null;
    const cleanup = () => {
      window.removeEventListener("message", onMessage);
      if (poll) clearInterval(poll);
      if (timeout) clearTimeout(timeout);
    };
    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      cleanup();
      fn(value);
    };
    const onMessage = (event) => {
      if (event.origin !== window.location.origin) return;
      const data = event.data || {};
      if (data.type !== "a8m-mail-oauth") return;
      if (data.status === "connected") finish(resolve, data.accountId || "");
      else finish(reject, new Error(data.message || "The mail account was not connected."));
    };
    window.addEventListener("message", onMessage);
    poll = setInterval(() => {
      if (popup.closed) finish(reject, new Error("Sign-in was cancelled."));
    }, 800);
    timeout = setTimeout(() => finish(reject, new Error("Sign-in timed out. Try again.")), 5 * 60 * 1000);
  });
}

async function connectMailAccountWithOAuth(provider, accountId = "") {
  const accountID = await startMailOAuth(provider, accountId);
  showToast(accountId ? "Mail account reconnected" : "Mail account connected");
  await loadBootstrap({ quiet: true });
  if (!accountId && accountID) {
    const connected = state.accounts.find((account) => account.id === accountID);
    if (connected) switchMailAccount(connected.id, { reload: false });
    await loadBootstrap({ quiet: true });
    setTimeout(() => loadBootstrap({ quiet: true }).catch(() => {}), 4000);
  }
}

