  document.addEventListener("click", (event) => {
    if (!event.target.closest(".compose-mention-menu")) {
      composeSessions.forEach(closeComposeMentionMenu);
    }
    const catchUpDismiss = event.target.closest("[data-catchup-dismiss]");
    if (catchUpDismiss) {
      const since = state.catchUp?.since;
      if (since) {
        try { localStorage.setItem(catchUpStorageKey(since), "1"); } catch {}
      }
      state.catchUp = null;
      renderList({ preserveScroll: true });
      return;
    }
    if (event.target.closest("[data-catchup-unread]")) {
      state.catchUp = null;
      setFilter("unread");
      return;
    }
    const scheduleSuggestion = event.target.closest("[data-schedule-suggestion]");
    if (scheduleSuggestion) {
      applyScheduleSuggestion(scheduleSuggestion.getAttribute("data-schedule-suggestion"));
      return;
    }
    if (event.target.closest("[data-year-review-close]") || event.target.id === "yearReviewOverlay") {
      const overlay = document.getElementById("yearReviewOverlay");
      if (overlay) overlay.hidden = true;
      return;
    }
    if (event.target.closest("[data-reaction-rule-close]") || event.target.id === "reactionRuleOverlay") {
      closeReactionRuleEditor();
      return;
    }
    const reactionRuleToggle = event.target.closest("[data-reaction-rule-toggle]");
    if (reactionRuleToggle) {
      toggleReactionRule(reactionRuleToggle.getAttribute("data-reaction-rule-toggle")).catch(showError);
      return;
    }
    const reactionRuleEdit = event.target.closest("[data-reaction-rule-edit]");
    if (reactionRuleEdit) {
      openReactionRuleEditor(reactionRuleEdit.getAttribute("data-reaction-rule-edit"));
      return;
    }
    const reactionRuleDelete = event.target.closest("[data-reaction-rule-delete]");
    if (reactionRuleDelete) {
      deleteReactionRule(reactionRuleDelete.getAttribute("data-reaction-rule-delete")).catch(showError);
      return;
    }
    const reactionOpen = event.target.closest("[data-reaction-open]");
    if (reactionOpen) {
      const message = messageById(reactionOpen.getAttribute("data-reaction-open"));
      if (message) openReactionMenu(reactionOpen, message);
      return;
    }
    const reactionEmoji = event.target.closest(".reaction-menu [data-reaction-emoji]");
    if (reactionEmoji && reactionMenuMessage) {
      const message = reactionMenuMessage;
      const emoji = reactionEmoji.getAttribute("data-reaction-emoji");
      const readOnlyDelegate = Boolean(message.delegateOwnerId) && message.delegateCanSend !== true;
      const visibility = readOnlyDelegate ? "private" : reactionMenuSendMode;
      const semantic = reactionEmoji.getAttribute("data-reaction-semantic") || "";
      rememberReactionEmoji(emoji);
      closeReactionMenu();
      if (visibility === "sent") openReactionConfirm(message, emoji, semantic);
      else applyReaction(message, emoji, visibility, semantic).catch(showError);
      return;
    }
    if (event.target.closest("[data-reaction-close]")) {
      closeReactionMenu();
      return;
    }
    const reactionRemove = event.target.closest("[data-reaction-remove]");
    if (reactionRemove) {
      const message = messageById(reactionRemove.getAttribute("data-reaction-remove"));
      if (message) removeReaction(message).catch(showError);
      return;
    }
    if (reactionMenu && !event.target.closest(".reaction-menu") && !event.target.closest('[data-action="react"]')) closeReactionMenu();
    const unsubscribeButton = event.target.closest("[data-unsubscribe]");
    if (unsubscribeButton) {
      const message = messageById(unsubscribeButton.getAttribute("data-unsubscribe"));
      if (message) requestUnsubscribe(message, unsubscribeButton);
      return;
    }
    const threadCloseButton = event.target.closest("[data-thread-close]");
    if (threadCloseButton) {
      const bar = threadCloseButton.closest(".thread-collab-bar");
      const thread = bar ? threadById(bar.getAttribute("data-collab-thread")) : null;
      if (bar && thread) {
        const meta = threadMetaForThread(thread);
        patchThreadCollaboration(thread, bar.getAttribute("data-collab-owner"), { closed: !(meta?.closed === true) });
      }
      return;
    }
    const notesToggle = event.target.closest("[data-thread-notes-toggle]");
    if (notesToggle) {
      const panel = notesToggle.closest(".thread-collab-bar")?.nextElementSibling?.matches("[data-thread-notes-panel]")
        ? notesToggle.closest(".thread-collab-bar").nextElementSibling
        : document.querySelector("[data-thread-notes-panel]");
      const thread = currentThread();
      if (panel && thread) {
        if (panel.hidden) {
          panel.hidden = false;
          renderThreadNotesPanel(thread, panel.getAttribute("data-owner-id"), panel);
        } else {
          panel.hidden = true;
        }
      }
      return;
    }
    if (event.target.closest("[data-thread-notes-close]")) {
      const panel = event.target.closest("[data-thread-notes-panel]");
      if (panel) panel.hidden = true;
      return;
    }
    const noteDelete = event.target.closest("[data-thread-note-delete]");
    if (noteDelete) {
      const panel = noteDelete.closest("[data-thread-notes-panel]");
      const thread = panel ? threadById(panel.getAttribute("data-thread-id")) : null;
      if (panel && thread) {
        const ownerId = panel.getAttribute("data-owner-id");
        api(`/api/threads/${encodeURIComponent(thread.id)}/notes/${encodeURIComponent(noteDelete.getAttribute("data-thread-note-delete"))}`, {
          method: "DELETE", body: { ownerId }
        }).then(() => renderThreadNotesPanel(thread, ownerId, panel)).catch(showError);
      }
      return;
    }
    if (event.target.closest("[data-ai-reader-close]")) { closeReaderAi(); return; }
    if (event.target.closest("[data-ai-commitments-chip]")) {
      runReaderAi("commitments");
      return;
    }
    const commitment = event.target.closest("[data-ai-commitment]");
    if (commitment) {
      event.preventDefault();
      focusCommitment(commitment.getAttribute("data-ai-commitment"), commitment.getAttribute("data-ai-commitment-quote"));
      return;
    }
    const aiAction = event.target.closest("[data-ai-action]");
    if (aiAction) {
      event.preventDefault();
      const action = aiAction.getAttribute("data-ai-action");
      runReaderAi(action === "translate" ? "translation" : action === "commitments" ? "commitments" : "summary");
      return;
    }
    if (aiReaderMenus.some((menu) => !menu.hidden) && !event.target.closest("[data-ai-wrap]")) closeReaderAiMenus();
  });
